import java.io.*;
import java.math.*;
import java.text.*;
import java.util.*;
import java.util.regex.*;

public class Solution 
{
    static class InputReader
	{
	    private final InputStream stream;
	    private final byte[] buf = new byte[8192];
	    private int curChar, snumChars;

	    public InputReader(InputStream st) {
	      this.stream = st;
	    }

	    public int read() {
	      if (snumChars == -1)
	        throw new InputMismatchException();
	      if (curChar >= snumChars) {
	        curChar = 0;
	        try {
	          snumChars = stream.read(buf);
	        } catch (IOException e) {
	          throw new InputMismatchException();
	        }
	        if (snumChars <= 0)
	          return -1;
	      }
	      return buf[curChar++];
	    }

	    public int nextInt() {
	      int c = read();
	      while (isSpaceChar(c)) {
	        c = read();
	      }
	      int sgn = 1;
	      if (c == '-') {
	        sgn = -1;
	        c = read();
	      }
	      int res = 0;
	      do {
	        res *= 10;
	        res += c - '0';
	        c = read();
	      } while (!isSpaceChar(c));
	      return res * sgn;
	    }

	    public long nextLong() {
	      int c = read();
	      while (isSpaceChar(c)) {
	        c = read();
	      }
	      int sgn = 1;
	      if (c == '-') {
	        sgn = -1;
	        c = read();
	      }
	      long res = 0;
	      do {
	        res *= 10;
	        res += c - '0';
	        c = read();
	      } while (!isSpaceChar(c));
	      return res * sgn;
	    }

	    public int[] nextIntArray(int n) {
	      int a[] = new int[n];
	      for (int i = 0; i < n; i++) {
	        a[i] = nextInt();
	      }
	      return a;
	    }

	    public String readString() {
	      int c = read();
	      while (isSpaceChar(c)) {
	        c = read();
	      }
	      StringBuilder res = new StringBuilder();
	      do {
	        res.appendCodePoint(c);
	        c = read();
	      } while (!isSpaceChar(c));
	      return res.toString();
	    }

	    public String nextLine() {
	      int c = read();
	      while (isSpaceChar(c))
	        c = read();
	      StringBuilder res = new StringBuilder();
	      do {
	        res.appendCodePoint(c);
	        c = read();
	      } while (!isEndOfLine(c));
	      return res.toString();
	    }

	    public boolean isSpaceChar(int c) {
	      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	    }

	    private boolean isEndOfLine(int c) {
	      return c == '\n' || c == '\r' || c == -1;
	    }
	}
    /*static class node implements Comparable<node>
    {
        int index;
        int val;
        node(int a1,int a2)
        {
            index=a1;
            val=a2;
        }
        public int compareTo(node n1)
        {
            return(this.val-n1.val);
        }
    }*/
    public static void main(String[] args) throws IOException 
    {
        InputReader in=new InputReader(System.in);
        int n=in.nextInt();
        int b=in.nextInt();
        int [] a=new int[n];
        a=in.nextIntArray(n);
        int[] odd=new int[n+1];
        int[] even=new int[n+1];
        odd[0]=0;
        even[0]=0;
        for(int i=1;i<=n;i++)
        {
            if(a[i-1]%2==1)
            {
                odd[i]=odd[i-1]+1;
                even[i]=even[i-1];
            }
            else
            {
                odd[i]=odd[i-1];
                even[i]=even[i-1]+1;
            }
        }
        int prev=0;
        PriorityQueue<Integer> cost=new PriorityQueue<Integer>();
        for(int i=1;i<=n-1;i++)
        {
            int oc=odd[i]-odd[prev];
            int ec=even[i]-even[prev];
            if(oc==ec)
            {
                cost.add((int)Math.abs(a[i]-a[i-1]));
                //System.out.println((int)Math.abs(a[i]-a[i-1]));
                prev=i;
            }
        }
        int sum=0;
        int count=0;
        while(!cost.isEmpty() && sum<=b)
        {
            sum+=cost.peek().intValue();
            cost.poll();
            count++;
        }
        if(count==0)
        {
            System.out.println("0");
        }
        else
        {
            if(cost.isEmpty() && sum<=b)
            {
                System.out.println(count);
            }
            else
            {
                System.out.println(count-1);
            }
        }
    }
}

