public class q4_variant1 {
    static int[] arr;
    static int[] oddCount;
    static int[] evenCount;
    static int n;
    static int budget;

    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        n = Reader.nextInt();
        budget = Reader.nextInt();
        arr = new int[n + 1];
        oddCount = new int[n + 1];
        evenCount = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            arr[i] = Reader.nextInt();
            if (arr[i] % 2 == 1) {
                oddCount[i] = oddCount[i - 1] + 1;
                evenCount[i] = evenCount[i - 1];
            } else {
                oddCount[i] = oddCount[i - 1];
                evenCount[i] = evenCount[i - 1] + 1;
            }
        }

        List<Integer> cuts = new ArrayList<>();
        for (int i = 2; i < n; i += 2) {
            if (oddCount[i] == evenCount[i]) {
                cuts.add(Math.abs(arr[i] - arr[i + 1]));
            }
        }

        Collections.sort(cuts);
        int cutCount = 0;
        long sum = 0;
        for (int cost : cuts) {
            if (sum + cost <= budget) {
                cutCount++;
                sum += cost;
            } else {
                break;
            }
        }
        System.out.println(cutCount);
    }
}

