public class q4_variant2 {
    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        int n = Reader.nextInt();
        int b = Reader.nextInt();
        int[] a = new int[n + 1];
        int[] oc = new int[n + 1];
        int[] ec = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            a[i] = Reader.nextInt();
            oc[i] = oc[i - 1] + (a[i] % 2 == 1 ? 1 : 0);
            ec[i] = ec[i - 1] + (a[i] % 2 == 0 ? 1 : 0);
        }

        int[] diffs = new int[n / 2 - 1];
        int idx = 0;
        for (int i = 2; i < n; i += 2) {
            if (oc[i] == ec[i]) {
                diffs[idx++] = Math.abs(a[i] - a[i + 1]);
            } else {
                diffs[idx++] = -1;
            }
        }

        Arrays.sort(diffs);
        int cuts = 0;
        long total = 0;
        for (int i = 0; i < diffs.length; i++) {
            if (diffs[i] != -1 && total + diffs[i] <= b) {
                cuts++;
                total += diffs[i];
            }
        }
        System.out.println(cuts);
    }
}

