public class q4_variant3 {
    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        int n = Reader.nextInt();
        int budget = Reader.nextInt();
        int[] values = new int[n + 1];
        int[] oddPrefix = new int[n + 1];
        int[] evenPrefix = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            values[i] = Reader.nextInt();
            oddPrefix[i] = oddPrefix[i - 1] + (values[i] & 1);
            evenPrefix[i] = evenPrefix[i - 1] + (1 - (values[i] & 1));
        }

        PriorityQueue<Integer> candidates = new PriorityQueue<>();
        for (int i = 2; i < n; i += 2) {
            if (oddPrefix[i] == evenPrefix[i]) {
                candidates.offer(Math.abs(values[i] - values[i + 1]));
            }
        }

        int cutCount = 0;
        long spent = 0;
        while (!candidates.isEmpty() && spent + candidates.peek() <= budget) {
            spent += candidates.poll();
            cutCount++;
        }
        System.out.println(cutCount);
    }
}

