            a[i] = sc.nextInt();
        }

        int odd = 0, even = 0;
        int[] diffs = new int[n]; // max possible size
        int diffCount = 0;

        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 == 1) odd++;
            else even++;

            if (odd == even) {
                diffs[diffCount++] = Math.abs(a[i + 1] - a[i]);
            }
        }

        // Sort only the used portion of diffs array
        Arrays.sort(diffs, 0, diffCount);

        int sum = 0, count = 0;
        for (int i = 0; i < diffCount; i++) {
            sum += diffs[i];
            if (sum <= b) count++;
            else break;
        }

        System.out.println(count);
    }
}

