public class Cutting {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int b = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int odd = 0, even = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 != 0) odd++;
            else even++;

            if (odd == even) {
                pq.offer(Math.abs(a[i + 1] - a[i]));
            }
        }

        int sum = 0, count = 0;
        while (!pq.isEmpty()) {
            int cost = pq.poll();
            if (sum + cost <= b) {
                sum += cost;
                count++;
            } else {
                break;
            }
        }

        System.out.println(count);
    }
}

