public class Cutting {

    private static int[] convertStringToIntArray(String input) {
        return Arrays.stream(input.trim().split("\\s+"))
                     .mapToInt(Integer::parseInt)
                     .toArray();
    }

    private static boolean isEvenOddBalanced(int[] array, int boundary) {
        int evens = 0, odds = 0;
        for (int i = 0; i <= boundary; i++) {
            if (array[i] % 2 == 0) evens++;
            else odds++;
        }
        return evens == odds;
    }

    private static int locateCheapestValidCut(int[] values, int coinsLeft, Set<Integer> blocked) {
        int bestPos = -1;
        int minExpense = coinsLeft + 1;

        for (int i = 1; i < values.length - 1; i++) {
            int expense = Math.abs(values[i] - values[i + 1]);
            if (expense < minExpense && isEvenOddBalanced(values, i) && !blocked.contains(i)) {
                minExpense = expense;
                bestPos = i;
            }
        }
        return bestPos;
    }

    public int calculateMaxCuts(int totalItems, int initialCoins, int[] coinValues) {
        int coins = initialCoins;
        int cuts = 0;
        Set<Integer> usedPositions = new HashSet<>();

        while (coins > 0) {
            int pos = locateCheapestValidCut(coinValues, coins, usedPositions);
            if (pos == -1) break;

            usedPositions.add(pos);
            coins -= Math.abs(coinValues[pos] - coinValues[pos + 1]);
            cuts++;
        }
        return cuts;
    }

