public class Cutting {

    private static int[] parseLineToIntArray(String line) {
        return Arrays.stream(line.trim().split("\\s+"))
                     .mapToInt(Integer::parseInt)
                     .toArray();
    }

    private static boolean hasEqualEvenOdd(int[] data, int pos) {
        int even = 0, odd = 0;
        for (int i = 0; i <= pos; i++) {
            if (data[i] % 2 == 0) even++;
            else odd++;
        }
        return even == odd;
    }

    private static int findBestCutIndex(int[] arr, int budget, Set<Integer> forbidden) {
        int best = -1;
        int minDiff = budget + 1;

        for (int i = 1; i < arr.length - 1; i++) {
            int diff = Math.abs(arr[i] - arr[i + 1]);
            if (diff < minDiff && hasEqualEvenOdd(arr, i) && !forbidden.contains(i)) {
                minDiff = diff;
                best = i;
            }
        }
        return best;
    }

    public int maximizeCuts(int n, int money, int[] sequence) {
        int remaining = money;
        int count = 0;
        Set<Integer> taken = new HashSet<>();

        while (remaining > 0) {
            int idx = findBestCutIndex(sequence, remaining, taken);
            if (idx == -1) break;

            taken.add(idx);
            remaining -= Math.abs(sequence[idx] - sequence[idx + 1]);
            count++;
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        int[] params = parseLineToIntArray(in.readLine());
        int[] values = parseLineToIntArray(in.readLine());

