        int[] weights = new int[n];

        for (int i = 0; i < n; i++) {
            positions[i] = Integer.parseInt(tokens[i]);
            weights[i] = (positions[i] & 1) == 0 ? -1 : 1;
        }

        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        int prefixSum = 0;

        for (int i = 0; i < n - 1; i++) {
            prefixSum += weights[i];
            if (prefixSum == 0) {
                int distance = Math.abs(positions[i + 1] - positions[i]);
                minHeap.offer(distance);
            }
        }

        int total = 0;
        int count = 0;

        while (!minHeap.isEmpty() && total + minHeap.peek() <= b) {
            total += minHeap.poll();
            count++;
        }

        System.out.println(count);
    }
}

