            long tmp = n;
            n = m;
            m = tmp;
        }

        if (n <= 2 && m <= 2) {
            out.println(0);
        } else if (n == 1) {
            long blocks = m / 6;
            long result = blocks * 6;
            long remainder = m % 6;
            if (remainder >= 4) {
                result += (remainder - 3) * 2;
            }
            out.println(result);
        } else if (n == 2) {
            long result = n * m;
            if (m == 3) result = 4;
            else if (m == 7) result = 12;
            out.println(result);
        } else {
            out.println((n * m / 2) * 2);
        }

        out.close();
    }

    static long pow(long base, long exp) {
        if (exp == 0) return 1;
        if (exp == 1) return base;
        long half = pow(base, exp / 2);
        return (exp % 2 == 0) ? half * half : half * half * base;
    }

    static long powMod(long base, long exp) {
        if (exp == 0) return 1;
        if (exp == 1) return base % MOD;
        long half = powMod(base, exp / 2) % MOD;
        long result = (half * half) % MOD;
        if (exp % 2 == 1) {
            result = (result * (base % MOD)) % MOD;
        }
        return result % MOD;
    }

    static void mergeSort(int[] arr) {
        int len = arr.length;
        if (len < 2) return;
        int mid = len / 2;
        int[] left = new int[mid];
        int[] right = new int[len - mid];

        System.arraycopy(arr, 0, left, 0, mid);
        System.arraycopy(arr, mid, right, 0, len - mid);

        mergeSort(left);
        mergeSort(right);
        merge(left, right, arr);
    }

    static void merge(int[] left, int[] right, int[] target) {
        int i = 0, j = 0, k = 0;
        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                target[k++] = left[i++];
            } else {
                target[k++] = right[j++];
            }
        }
        while (i < left.length) target[k++] = left[i++];
        while (j < right.length) target[k++] = right[j++];
    }

