            }
            writer.println(count);
        } else if (smaller == 2) {
            long result = 2 * larger;
            if (larger == 3) result = 4;
            else if (larger == 7) result = 12;
            writer.println(result);
        } else {
            long total = smaller * larger;
            writer.println(total - (total & 1));
        }

        writer.close();
    }

    static long exponentiate(long base, long exp) {
        if (exp == 0) return 1;
        long half = exponentiate(base, exp / 2);
        if (exp % 2 == 0) return half * half;
        return half * half * base;
    }

    static long modExponentiate(long base, long exp) {
        if (exp == 0) return 1;
        if (exp == 1) return base % MOD;
        long half = modExponentiate(base, exp / 2) % MOD;
        long result = (half * half) % MOD;
        if (exp % 2 == 1) {
            result = (result * (base % MOD)) % MOD;
        }
        return result % MOD;
    }

    static void heapSort(int[] arr) {
        int n = arr.length;
        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(arr, n, i);
        }
        for (int i = n - 1; i > 0; i--) {
            int temp = arr[0];
            arr[0] = arr[i];
            arr[i] = temp;
            heapify(arr, i, 0);
        }
    }

    static void heapify(int[] arr, int n, int i) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && arr[left] > arr[largest]) largest = left;
        if (right < n && arr[right] > arr[largest]) largest = right;

        if (largest != i) {
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;
            heapify(arr, n, largest);
        }
    }

