public class Main{


    public static void main(String[] args) throws IOException  {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long rep = 0;
        if(n>=4&&m>=4){
            if(n%2==0||m%2==0) rep = n*m;
            else rep = n*m-1;
        }
        else{
            long min = Math.min(n,m);
            long max = Math.max(n,m);
            if(min==1){
                rep = max- (max%6);
                if(max%6==4) rep += 2;
                if(max%6==5) rep += 4;
            }
            else if(min==2){
                if(max<3) rep = 0;
                else if(max==3) rep = 4;
                else if(max==7) rep = 12;
                else rep = min * max;
            }
            else if(min==3) {
                if(max<3) rep = 0;
                else {
                    rep = min * max;
                    if(max%2==1) rep--;
                }
            }

        }
        System.out.println(rep);
    }



}

