        long n = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);
        long rep = 0;

        if (n >= 4 && m >= 4) {
            rep = (n * m) - ((n % 2 == 1 && m % 2 == 1) ? 1 : 0);
        } else {
            long min = Math.min(n, m);
