    static long solve(long n, long m) {
        if (n > m) {
            long tmp = n;
            n = m;
            m = tmp;
        }

        long total = n * m;
        if ((n % 2) != 0 && (m % 2) != 0) {
            total--;
        }

        if (n == 1) {
            long product = n * m;
            long groups = product / 6;
            long rem = product % 6;
            long extra = 0;
            if (rem == 4) extra = 2;
            if (rem == 5) extra = 4;
            return groups * 6 + extra;
        }

        if (n == 2) {
            if (m == 2) return 0L;
            if (m == 3) return 4L;
            if (m == 7) return 12L;
        }

        return total;
    }

