public class B {
    static final PrintWriter out = new PrintWriter(System.out, true);

    public static void main(String[] args) {
        FS in = new FS();
        long R = in.nextLong();
        long C = in.nextLong();
        long minRC = Math.min(R, C);
        long maxRC = Math.max(R, C);
        long result = compute(minRC, maxRC);
        out.println(result);
        out.close();
    }

    static long compute(long rows, long cols) {
        if (rows < 3 && cols < 3) {
            return 0L;
        }
        if (rows == 1) {
            long total = cols;
            long remainder = cols % 6;
            if (remainder != 0) {
                if (remainder <= 3) {
                    total -= remainder;
                } else if (remainder == 4) {
                    total -= 2;
                } else if (remainder == 5) {
                    total -= 1;
                }
            }
            return total;
        }
        if (rows == 2) {
            if (cols == 3 || cols == 7) {
                return 2 * (cols - 1);
            }
            return 2 * cols;
        }
        long total = rows * cols;
        return (total & 1L) == 0 ? total : total - 1;
    }

    static class FS {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FS() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        int[] NIA(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        long[] NLA(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        char[][] grid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = nextToken();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}

