        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        long n = fr.nextLong();
        long m = fr.nextLong();

        if (n > m) {
            long t = n;
            n = m;
            m = t;
        }

        long result;
        if (n == 1) {
            long r = m % 6;
            if (r == 0) result = n * m;
            else if (r == 1 || r == 5) result = n * m - 1;
            else if (r == 2 || r == 4) result = n * m - 2;
            else result = n * m - 3;
        } else if (n == 2) {
            if (m == 2) result = n * m - 4;
            else if (m == 3 || m == 7) result = n * m - 2;
            else result = n * m;
        } else if (n == 3) {
            result = (m % 2 == 0) ? n * m : n * m - 1;
        } else {
            result = (n % 2 == 1 && m % 2 == 1) ? n * m - 1 : n * m;
        }

        System.out.println(result);
    }
}

