        private int ptr = 0, len = 0;

        Reader(InputStream in) { this.in = in; }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private int skip() throws IOException {
            int c;
            while ((c = read()) <= 32 && c != -1) {}
            return c;
        }

        long nextLong() throws IOException {
            int c = skip();
