    static class BDiv1 {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            long n = in.ni(), m = in.ni();
            if (n > m) {
                long t = n;
                n = m;
                m = t;
            }
            if (n == 1) {
                if (m % 6 == 0)
                    out.println(m);
