            if (ptr >= len) {
                ptr = 0;
                try {
                    len = stream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c));
            if (c == -1) throw new NoSuchElementException();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        private static class NoSuchElementException extends RuntimeException {}
    }
