                }
            }
        }
        System.out.println(table[n][n]);
    }
}

import java.util.Scanner;

public class Codeforces {
    final static int P = 1000000007;
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int[][] table = new int[n+1][n+1];   
        table[0][0] = 0;
        for (int i=0; i<=n; i++) {
            for (int j=i; j<=n; j++) {
                if (i == 0 && j == 0) continue;
                int parity = (i + j) & 1;
                int up = (i > 0) ? table[i-1][j] : 0;
                int left = (j > 0) ? table[i][j-1] : 0;
                int sum = up + left + parity;
                if (i == 0) {
                    table[i][j] = (left + parity) % P;
                } else if (j == 0) {
                    table[i][j] = (up + parity) / P;
                } else {
                    table[i][j] = sum % P;
                }
            }
        }
        System.out.println(table[n][n]);
    }
}

