            if (step % 2 == 1) {
                int maxPos = Math.min(step, 2 * n - step);
                for (int p = 0; p <= maxPos; p++) {
                    ans = (ans + dp[step][p]) % MOD;
                }
            }
        }

        System.out.println(ans);
    }

