public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    private final FastReader reader = new FastReader();
    private final PrintWriter writer = new PrintWriter(System.out);
    private static final long MOD = 1000000007L;

    private void execute() {
        solve();
        writer.flush();
    }

    private long computeGcd(long a, long b) {
        while (a != 0) {
            long temp = a;
            a = b % a;
            b = temp;
        }
        return b;
    }

    private void solve() {
        int n = reader.nextInt();
        long[] dp = new long[2 * n + 1];
        long result = 0;
        dp[0] = 1;

        for (int step = 1; step <= 2 * n; step++) {
            long[] nextDp = new long[2 * n + 1];
            for (int i = 0; i < 2 * n; i++) {
                if (dp[i] != 0) {
                    nextDp[i + 1] = (nextDp[i + 1] + dp[i]) % MOD;
                    if (i - 1 >= 0) {
                        nextDp[i - 1] = (nextDp[i - 1] + dp[i]) % MOD;
                        if (step % 2 == 0) {
                            int remaining = 2 * n - step;
                            if (remaining >= i - 1) {
                                result = (result + dp[i]) % MOD;
                            }
                        }
                    }
                }
            }
            dp = nextDp;
        }
        writer.println(result);
    }
}

