    static class DNekoIPrank {
        private static final int MOD = 1_000_000_007;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            out.print(new Solver().compute(n));
        }

        private class Solver {
            int compute(int n) {
                int maxLen = 2 * n + 1;
                int[][] prev = new int[maxLen][2];
                int[][] curr = new int[maxLen][2];
                prev[0][0] = 1;

                for (int step = 1; step <= 2 * n; step++) {
                    for (int open = step & 1; open <= step; open += 2) {
                        curr[open][0] = 0;
                        curr[open][1] = 0;

                        if (open > 0) {
                            curr[open][0] = (curr[open][0] + prev[open - 1][1]) % MOD;
                            curr[open][1] = (curr[open][1] + prev[open - 1][0]) % MOD;
                        }
                        if (open + 1 < maxLen) {
                            curr[open][0] = (curr[open][0] + prev[open + 1][1]) % MOD;
                            curr[open][1] = (curr[open][1] + prev[open + 1][0]) % MOD;
                        }
                        curr[open][0] = (curr[open][0] + 1) % MOD;
                    }
                    int[][] temp = prev;
                    prev = curr;
                    curr = temp;
                }
                return prev[0][1];
            }
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream output) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(output)));
        }

        public void print(int value) {
            writer.print(value);
        }

        public void close() {
            writer.close();
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (len == -1) throw new NoSuchElementException();
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = stream.read(buffer);
                } catch (IOException e) {
                    throw new NoSuchElementException();
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int readInt() {
            int c = read();
            while (isSpace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            do {
                if (c < '0' || c > '9') throw new NoSuchElementException();
                val = val * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            return val * sign;
        }

        private boolean isSpace(int c) {
            return c <= ' ' && (c == ' ' || c == '\n' || c == '\r' || c == '\t');
        }
    }

    private static class NoSuchElementException extends RuntimeException {}
}

