        public void close() {
            writer.close();
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int pos, count;

        public InputReader(InputStream stream) {
            in = stream;
        }

        private int readByte() {
            if (count == -1) throw new InputMismatchException();
            if (pos >= count) {
                pos = 0;
                try {
                    count = in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (count <= 0) return -1;
            }
            return buf[pos++];
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int val = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                val = val * 10 + c - '0';
                c = readByte();
            } while (c > ' ');
            return val * sign;
        }
    }

    static class InputMismatchException extends RuntimeException {}
}

