public class P1152D {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        final int MOD = 1000000007;
        int n = in.readInt();
        int m = 2 * n;
        int[][] dp = new int[m + 1][m + 2];
        dp[0][0] = 1;
        int result = 0;

        for (int i = 1; i <= m; i++) {
            dp[i][0] = dp[i - 1][1];
            for (int j = 1; j <= m; j++) {
                dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j + 1]) % MOD;
            }
            if ((i & 1) == 1) {
                for (int k = 1; i + k <= m; k += 2) {
                    result = (result + dp[i][k]) % MOD;
                }
            }
        }

        out.printLine(result);
        out.flush();
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[10240];
        private int curChar, numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1)
                throw new RuntimeException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream output) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(output)));
        }

        public void printLine(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0)
                    writer.print(' ');
                writer.print(objects[i]);
            }
            writer.println();
        }

        public void flush() {
            writer.flush();
        }
    }
}

