        long evenCount = totalRange / 2 + (totalRange % 2 == 0 && L % 2 == 0 ? 1 : 0);
        long oddCount = totalRange - evenCount;

        long totalWays;
        if ((N * M) % 2 == 1) {
            totalWays = modPow(evenCount + oddCount, N * M);
        } else {
            long term1 = modPow(evenCount + oddCount, N * M);
            long term2 = modPow(evenCount - oddCount, N * M);
            totalWays = (term1 + term2) % MOD;
            totalWays = (totalWays * modInverse(2)) % MOD;
        }

        out.println(totalWays);
        out.close();
    }

    static long modPow(long base, long exp) {
        base %= MOD;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long modInverse(long a) {
        return modPow(a, MOD - 2);
    }

    static class FastScanner {
        private final int BUFFER_SIZE = 1 << 16;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int bufferPointer = 0, bytesRead = 0;
        private final InputStream stream = System.in;

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = stream.read(buffer, 0, BUFFER_SIZE);
                if (bytesRead == -1) buffer[0] = -1;
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }

        public long nextLong() throws IOException {
            long num = 0;
            byte c = read();
            boolean neg = false;
            while (c <= ' ') {
                c = read();
            }
            if (c == '-') {
                neg = true;
                c = read();
            }
            while (c >= '0' && c <= '9') {
                num = (num << 3) + (num << 1) + (c - '0');
                c = read();
            }
            return neg ? -num : num;
        }

        public int nextInt() throws IOException {
            return (int) nextLong();
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            byte c;
            while ((c = read()) <= ' ');
            do {
                sb.append((char) c);
            } while ((c = read()) > ' ');
            return sb.toString();
        }
    }
}

