        long r = Long.parseLong(st.nextToken());

        if (l == r) {
            pw.println(1);
            pw.flush();
            return;
        }

        long odds = (r + 1) / 2 - l / 2;
        long evens = r / 2 - (l - 1) / 2;

        long total = odds + evens;
        long diff = odds - evens;

        long ans;
        if ((n * m) % 2 == 1) {
            ans = modPow(total, n * m);
        } else {
            ans = (modPow(total, n * m) + modPow(diff, n * m)) % MOD;
            ans = (ans * modInverse(2)) % MOD;
        }

        pw.println(ans);
        pw.flush();
    }
}

