		long m = M;
		if(b == 0)
			return 1;
		else if(b == 1)
			return a;
		else if(a == 1)
			return 1;
		else if(b%2 == 0)
			return exp((a*a)%m, b/2);
		else
			return (exp((a*a)%m, b/2) * a)%m;
	}

}

