        long l = sc.nextLong();
        long r = sc.nextLong();

        long T = mulMod(m, n);
        long num = safeMod(r - l + 1);

        long a = fastPow(num, T);

        if ((T & 1) == 1) {
            System.out.println(a);
        } else {
            long inv2 = fastPow(2, MOD - 2);
            if ((num & 1) == 0) {
                System.out.println(mulMod(a, inv2));
            } else {
                System.out.println(mulMod(addMod(a, 1), inv2));
            }
        }
    }

    static long addMod(long a, long b) {
        return ((a % MOD) + (b % MOD)) % MOD;
    }

    static long mulMod(long a, long b) {
        a %= MOD; b %= MOD;
        return (a * b) % MOD;
    }

    static long safeMod(long x) {
        return ((x % MOD) + MOD) % MOD;
    }

    static long fastPow(long base, long exp) {
        base = safeMod(base);
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = mulMod(result, base);
            }
            base = mulMod(base, base);
            exp >>= 1;
        }
        return result;
    }
}

