        long num = ((r - l + 1) % MOD + MOD) % MOD;

        long result = solve(T, num);
        System.out.println(result);
    }

    private static long solve(long T, long num) {
        long power = modPow(num, T);

        if ((T & 1) == 1) {
            return power;
        }

        long inv2 = modPow(2, MOD - 2);
        if ((num & 1) == 0) {
            return (power * inv2) % MOD;
        } else {
            return ((power + 1) * inv2) % MOD;
        }
    }

    private static long modPow(long base, long exp) {
        base = ((base % MOD) + MOD) % MOD;
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

