        long m = scan.nextLong();
        long L = scan.nextLong();
        long R = scan.nextLong();
        long range = R - L;

        long evenCount, oddCount;
        if (range % 2 == 1) {
            evenCount = (range + 1) / 2;
            oddCount = (range + 1) / 2;
        } else {
            evenCount = range / 2;
            oddCount = range / 2;
            if (L % 2 == 1) {
                oddCount++;
            } else {
                evenCount++;
            }
        }

        long[][] baseMatrix = { { evenCount, oddCount }, { oddCount, evenCount } };
        long[][] resultMatrix = matrixPower(baseMatrix, n * m);
        long answer = resultMatrix[0][0];
        if ((n * m) % 2 == 1) {
            answer = (answer + resultMatrix[0][1]) % MOD;
        }
        System.out.println(answer);
