    static long[][] matrixPower(long[][] base, long exponent) {
        int size = base.length;
        long[][] result = identityMatrix(size);
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = multiplyMatrices(result, base);
            }
            base = multiplyMatrices(base, base);
            exponent >>= 1;
        }
        return result;
    }

    static long[][] identityMatrix(int n) {
        long[][] identity = new long[n][n];
        for (int i = 0; i < n; i++) {
            identity[i][i] = 1;
        }
        return identity;
    }

    static long[][] multiplyMatrices(long[][] a, long[][] b) {
        int n = a.length;
        int m = b[0].length;
        int k = a[0].length;
        long[][] product = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                long sum = 0;
                for (int p = 0; p < k; p++) {
                    sum = (sum + (a[i][p] % MOD) * (b[p][j] % MOD)) % MOD;
                }
                product[i][j] = sum;
            }
        }
        return product;
    }
}

