                result = (ch * ch % MOD + nch * nch % MOD) % MOD;
            } else {
                result = (2 * ch % MOD * nch % MOD) % MOD;
            }
        }
        memo[parity][0].put(size, result);
        return result;
    }

    private static long fastPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
