public class E {
    static final long MOD = 998244353;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        long n = in.nextLong();
        long m = in.nextLong();
        long p = in.nextLong();
        long q = in.nextLong();

        long len = q - p + 1;
        long odd = (p % 2 == 1) ? (len + 1) / 2 : len / 2;
        long even = len - odd;

        Map<Long, Long>[][] cache = new HashMap[2][1];
        cache[0][0] = new HashMap<>();
        cache[1][0] = new HashMap<>();

        if ((n & m) % 2 == 0) {
            long ans = solve(even, odd, n * m, 0, cache);
            System.out.println(ans);
        } else {
            long ans = modExp(even + odd, n * m);
            System.out.println(ans);
        }
    }

    static long solve(long e, long o, long s, int t, Map<Long, Long>[][] cache) {
        if (cache[t][0].containsKey(s)) return cache[t][0].get(s);

        if (s == 1) {
            long val = (t == 0) ? e : o;
            cache[t][0].put(s, val);
            return val;
        }

        long res;
        if (s % 2 == 1) {
            long term1 = e * solve(e, o, s - 1, t, cache) % MOD;
            long term2 = o * solve(e, o, s - 1, 1 - t, cache) % MOD;
            res = (term1 + term2) % MOD;
        } else {
            long h = s / 2;
            long c = solve(e, o, h, 0, cache);
            long nc = solve(e, o, h, 1, cache);
            if (t == 0) {
                res = (c * c % MOD + nc * nc % MOD) % MOD;
            } else {
                res = (2 * c % MOD * nc % MOD) % MOD;
            }
        }
        cache[t][0].put(s, res);
        return res;
    }

    static long modExp(long b, long e) {
        long res = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return res;
    }

