		long n = fs.nextLong(), m = fs.nextLong(), l = fs.nextLong(), r = fs.nextLong();

		if((n*m&1)==1) {
			out.println(exp(r-l+1,n*m));
			out.close();
			return;
		}

		long E = r/2 - (l-1)/2;
		long O = r-l+1 - E;


		long ans = (exp(E+O,n*m) + exp(E-O,n*m))%mod;
		ans = (ans*exp(2,mod-2))%mod;

		out.println(ans);





		out.close();
	}


