import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = br.readLine().trim().split("\\s+");
        long N = Long.parseLong(tokens[0]);
        long M = Long.parseLong(tokens[1]);
        long L = Long.parseLong(tokens[2]);
        long R = Long.parseLong(tokens[3]);

        long total = N * M;
        long range = R - L + 1;

        if (total % 2 == 1) {
            long result = modPow(range, total, MOD);
            System.out.println((result + MOD) % MOD);
        } else {
            long result = modPow(range, total, MOD);
            if ((R - L) % 2 == 0) {
                result = (result + 1) % MOD;
            }
            long inv2 = modPow(2, MOD - 2, MOD);
            result = (result * inv2) % MOD;
            System.out.println(result);
        }
    }

    static long modPow(long base, long exp, long mod) {
        long res = 1;
        base = ((base % mod) + mod) % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

