public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int n = Integer.parseInt(br.readLine().trim());
            if (n >= 100) {
                pw.println(0);
                return;
            }

            int[][] points = new int[n+1][5];
            for (int i = 1; i <= n; i++) {
                String[] line = br.readLine().split("\\s+");
                for (int j = 0; j < 5; j++) {
                    points[i][j] = Integer.parseInt(line[j]);
                }
            }

            Set<Integer> badIndices = new HashSet<>();

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
                        if (i == j || j == k || k == i) continue;

                        long[] ax = new long[5];
                        long[] ay = new long[5];
                        for (int d = 0; d < 5; d++) {
                            ax[d] = points[j][d] - points[i][d];
                            ay[d] = points[k][d] - points[i][d];
                        }

                        double dotProduct = 0;
                        double mag1 = 0, mag2 = 0;
                        for (int d = 0; d < 5; d++) {
                            dotProduct += ax[d] * ay[d];
                            mag1 += ax[d] * ax[d];
                            mag2 += ay[d] * ay[d];
                        }

                        double cosAngle = dotProduct / Math.sqrt(mag1 * mag2);
                        double angleDeg = Math.toDegrees(Math.acos(cosAngle));

                        if (angleDeg + 1e-9 < 90) {
                            badIndices.add(i);
                            break;
                        }
                    }
                    if (badIndices.contains(i)) break;
                }
            }

            pw.println(n - badIndices.size());
            for (int i = 1; i <= n; i++) {
                if (!badIndices.contains(i)) {
                    pw.println(i);
                }
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

