                        double mag1 = Math.sqrt(ax*ax + bx*bx + cx*cx + dx*dx + ex*ex);
                        double mag2 = Math.sqrt(ay*ay + by*by + cy*cy + dy*dy + ey*ey);

                        double cosAngle = dot / (mag1 * mag2);
                        double angleDeg = Math.toDegrees(Math.acos(cosAngle));

                        if (angleDeg + 1e-9 < 90) {
                            isBad[i] = true;
                            break;
                        }
                    }
                    if (isBad[i]) break;
                }
            }

            int count = 0;
            for (int i = 1; i <= n; i++) {
                if (!isBad[i]) count++;
            }

            pw.println(count);
            for (int i = 1; i <= n; i++) {
                if (!isBad[i]) {
                    pw.println(i);
                }
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

