            this.a = a;
            this.b = b;
            this.c = c;
            this.d = d;
            this.e = e;
        }

        Point diff(Point other) {
            return new Point(a - other.a, b - other.b, c - other.c, d - other.d, e - other.e);
        }

        boolean isAcute(Point other) {
            return a * other.a + b * other.b + c * other.c + d * other.d + e * other.e > 0;
        }
    }
}

