    static double computeAngle(int[] origin, int[] a, int[] b) {
        double dot = 0.0, lenA = 0.0, lenB = 0.0;
        for (int i = 0; i < origin.length; i++) {
            int da = a[i] - origin[i];
            int db = b[i] - origin[i];
            dot += da * db;
            lenA += da * da;
            lenB += db * db;
        }
        return Math.toDegrees(Math.acos(dot / Math.sqrt(lenA * lenB)));
    }

    static class FastReader {
