            bufferPtr = bytesRead = 0;
        }

        private void fillBuffer() throws IOException {
            bytesRead = dis.read(buffer, bufferPtr = 0, BUFFER_SIZE);
            if (bytesRead == -1) buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPtr == bytesRead) fillBuffer();
            return buffer[bufferPtr++];
        }

        public int nextInt() throws IOException {
            int c, num = 0;
            while ((c = read()) <= ' ');
            boolean neg = c == '-';
            if (neg) c = read();
            do { num = num * 10 + c - '0'; } while ((c = read()) >= '0' && c <= '9');
            return neg ? -num : num;
        }
    }
