import java.io.*;
import java.util.*;
public class div375B
{
	BufferedReader in;
	PrintWriter ob;
	StringTokenizer st;
	public static void main(String[] args) throws IOException {
		new div375B().run();
	}
	void run() throws IOException {
		in=new BufferedReader(new InputStreamReader(System.in));
		ob=new PrintWriter(System.out);
		solve();
		ob.flush();
	}
	void solve() throws IOException {
		int n=ni();
		char s[]=ns().toCharArray();
		int ans1=0,ans2=0;
		for (int i=0; i<n ; i++ ) {
			if(s[i]=='(') {
				int c=0;
				while(i+1<n) {
					if(s[i+1]==')') {
						if(c>0)++ans2;
						break;
					}
					if(s[i+1]=='_'){
						if(c>0) {
							++ans2;
							c=0;
						}
					}
					else
						++c;
					++i;
				}	
			}
			else if(s[i]==')' || s[i]=='_') {
				int c=0;
				while(i+1<n && s[i+1]!=')' && s[i+1]!='_' && s[i+1]!='(') {++c;++i;}
				ans1=Math.max(c,ans1);
			}
			else {
				int c=0;
				while(i<n && s[i]!=')' && s[i]!='_' && s[i]!='(') {++c;++i;}
				ans1=Math.max(c,ans1);	
				--i;
			}
		}
		ob.println(ans1+" "+ans2);
	}
	String ns()throws IOException {
		return nextToken();
	}
	int ni() throws IOException {
		return Integer.parseInt(nextToken());
	}
	String nextToken() throws IOException {
		if(st==null || !st.hasMoreTokens())
			st=new StringTokenizer(in.readLine());
		return st.nextToken();
	}
}

import java.io.*;
import java.util.*;

public class div375B_variant1 {
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    public static void main(String[] args) throws IOException {
        new div375B_variant1().execute();
    }

    private void execute() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        process();
        writer.flush();
    }

    private void process() throws IOException {
        int n = readInt();
        char[] arr = readString().toCharArray();
        int maxConsecutive = 0;
        int matchedPairs = 0;

        for (int i = 0; i < n; ) {
            if (arr[i] == '(') {
                int count = 0;
                int j = i + 1;
                while (j < n) {
                    if (arr[j] == ')') {
                        if (count > 0) matchedPairs++;
                        break;
                    } else if (arr[j] == '_') {
                        if (count > 0) {
                            matchedPairs++;
                            count = 0;
                        }
                    } else {
                        count++;
                    }
                    j++;
                }
                i = j;
            } else if (arr[i] == ')' || arr[i] == '_') {
                int count = 0;
                int j = i + 1;
                while (j < n && arr[j] != ')' && arr[j] != '_' && arr[j] != '(') {
                    count++;
                    j++;
                }
                maxConsecutive = Math.max(maxConsecutive, count);
                i = j;
            } else {
                int count = 0;
                int j = i;
                while (j < n && arr[j] != ')' && arr[j] != '_' && arr[j] != '(') {
                    count++;
                    j++;
                }
                maxConsecutive = Math.max(maxConsecutive, count);
                i = j;
            }
        }

        writer.println(maxConsecutive + " " + matchedPairs);
    }

    private String readString() throws IOException {
        return nextToken();
    }

    private int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private String nextToken() throws IOException {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }
}

