        char[] s = reader.readLine().toCharArray();
        int max = 0, pairs = 0;

        for (int i = 0; i < n; ) {
            if (s[i] == '(') {
                int cnt = 0;
                int j = i + 1;
                while (j < n) {
                    if (s[j] == ')') {
                        if (cnt > 0) pairs++;
                        break;
                    } else if (s[j] == '_') {
                        if (cnt > 0) {
                            pairs++;
                            cnt = 0;
                        }
                    } else {
                        cnt++;
                    }
                    j++;
                }
                i = j;
            } else if (s[i] == ')' || s[i] == '_') {
                int cnt = 0;
                int j = i + 1;
                while (j < n && s[j] != ')' && s[j] != '_' && s[j] != '(') {
                    cnt++;
                    j++;
                }
                max = Math.max(max, cnt);
                i = j;
            } else {
                int cnt = 0;
                int j = i;
                while (j < n && s[j] != ')' && s[j] != '_' && s[j] != '(') {
                    cnt++;
                    j++;
                }
                max = Math.max(max, cnt);
                i = j;
            }
        }

        writer.println(max + " " + pairs);
    }
}

