        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        boolean inParen = false;
        StringBuilder buffer = new StringBuilder();
        int maxLen = 0;
        int insideCount = 0;

        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                if (!inParen) {
                    int len = getMaxLength(buffer.toString());
                    if (len > maxLen) maxLen = len;
                    buffer.setLength(0);
                }
                inParen = true;
            } else if (ch == ')') {
                inParen = false;
                String[] parts = buffer.toString().split("_");
                for (String p : parts) {
                    if (!p.isEmpty()) insideCount++;
                }
                buffer.setLength(0);
            } else {
                buffer.append(ch);
            }
        }

        int len = getMaxLength(buffer.toString());
        if (len > maxLen) maxLen = len;

        System.out.println(maxLen + " " + insideCount);
    }

    private static int getMaxLength(String str) {
        if (str.isEmpty()) return 0;
        int max = 0;
        for (String word : str.split("_")) {
            if (word.length() > max) max = word.length();
        }
        return max;
    }
}

