                        ++winpars;
                    } else {
                        String[] parts = content.split("_", -1);
                        int count = 0;
                        for (String part : parts) {
                            if (!part.isEmpty()) ++count;
                        }
                        winpars += count;
                    }
                    s = s.substring(0, l) + "_" + s.substring(r + 1);
                } else {
                    break;
                }
            }

            String[] segments = s.split("_", -1);
            for (String seg : segments) {
                if (seg.length() > longest) {
                    longest = seg.length();
                }
            }

            out.println(longest + " " + winpars);
        }
    }
