import java.io.*;
import java.util.*;
public class Main {
    public static void main(String[] args) {
        new Main().run();
    }
    void run() {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            int n = in.nextInt();
            String s = in.next();
            int winpars = countValidParens(s);
            int longest = findLongestSegment(s);
            out.println(longest + " " + winpars);
        } finally {
            out.close();
        }
    }
    int countValidParens(String s) {
        s = s.replaceAll("__", "_");
        int count = 0;
        Pattern paren = Pattern.compile("\\(([^)]*)\\)");
        Matcher matcher = paren.matcher(s);
        while (matcher.find()) {
            String content = matcher.group(1);
            if (content.isEmpty()) {
                ++count;
            } else if (!content.contains("_")) {
                ++count;
            } else {
                String[] parts = content.split("_");
                int nonEmpty = 0;
                for (String part : parts) {
                    if (!part.isEmpty()) nonEmpty++;
                }
                count += nonEmpty;
            }
        }
        s = s.replaceAll("\\([^)]*\\)", "_");
        return count;
    }
    int findLongestSegment(String s) {
        s = s.replaceAll("__", "_");
        s = s.replaceAll("\\([^)]*\\)", "_");
        int maxLen = 0;
        String[] parts = s.split("_", -1);
        for (String part : parts) {
            if (part.length() > maxLen) {
                maxLen = part.length();
            }
        }
        return maxLen;
    }
}

import java.io.*;
import java.util.*;
public class Main {
    public static void main(String[] args) {
        new Main().process();
    }
    void process() {
        try (Scanner sc = new Scanner(System.in); PrintWriter pw = new PrintWriter(System.out)) {
            int n = sc.nextInt();
            String s = sc.next();
            s = normalizeUnderscores(s);
            int winpars = countMatchingParenSegments(s);
            int longest = computeMaxSegmentLength(s);
            pw.println(longest + " " + winpars);
        }
    }
    String normalizeUnderscores(String s) {
        while (s.contains("__")) {
            s = s.replace("__", "_");
        }
        return s;
    }
    int countMatchingParenSegments(String s) {
        int total = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (c == '(') {
                stack.push(i);
            } else if (c == ')') {
                if (!stack.isEmpty()) {
                    int start = stack.pop() + 1;
                    String segment = s.substring(start, i);
                    if (segment.isEmpty()) {
                        total++;
                    } else if (!segment.contains("_")) {
                        total++;
                    } else {
                        int nonEmpty = 0;
                        for (String part : segment.split("_")) {
                            if (!part.isEmpty()) nonEmpty++;
                        }
                        total += nonEmpty;
                    }
                }
            }
        }
        // Replace parentheses with underscore
        s = s.replaceAll("\\([^()]*\\)", "_");
        return total;
    }
    int computeMaxSegmentLength(String s) {
        s = s.replaceAll("\\([^()]*\\)", "_");
        s = s.replaceAll("__", "_");
        int max = 0;
        StringBuilder cur = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '_') {
                max = Math.max(max, cur.length());
                cur.setLength(0);
            } else {
                cur.append(c);
            }
        }
        max = Math.max(max, cur.length());
        return max;
    }
}

import java.io.*;
import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        String s = sc.next();
        int winpars = processParentheses(s);
        int longest = computeLongest(s);
        pw.println(longest + " " + winpars);
        pw.close();
    }
    static int processParentheses(String s) {
        String normalized = s.replaceAll("__", "_");
        int count = 0;
        int depth = 0;
        StringBuilder inner = new StringBuilder();
        for (char c : normalized.toCharArray()) {
            if (c == '(') {
                depth++;
                inner.setLength(0);
            } else if (c == ')') {
                if (depth > 0) {
                    depth--;
                    String content = inner.toString();
                    if (content.isEmpty()) {
                        count++;
                    } else if (!content.contains("_")) {
                        count++;
                    } else {
                        String[] tokens = content.split("_", -1);
                        for (String tok : tokens) {
                            if (!tok.isEmpty()) count++;
                        }
                    }
                    inner.setLength(0);
                }
            } else if (depth > 0) {
                inner.append(c);
            }
        }
        // Replace valid parentheses substrings with underscores
        String cleaned = normalized.replaceAll("\\([^()]*\\)", "_");
        return count;
    }
    static int computeLongest(String s) {
        String normalized = s.replaceAll("__", "_");
        String cleaned = normalized.replaceAll("\\([^()]*\\)", "_");
        int max = 0;
        int cur = 0;
        for (char c : cleaned.toCharArray()) {
            if (c == '_') {
                max = Math.max(max, cur);
                cur = 0;
            } else {
                cur++;
            }
        }
        max = Math.max(max, cur);
        return max;
    }
}

