    }

    void runProgram() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            br.readLine(); // skip n
            String s = br.readLine();

            int maxWordLength = 0;
            String[] outsideParts = s.split("\\([\\w_]*\\)");
            for (String part : outsideParts) {
                String[] words = part.split("_");
                for (String word : words) {
                    maxWordLength = Math.max(maxWordLength, word.length());
                }
            }

            long underscoreCount = 0;
            int pos = 0;
            while (pos < s.length()) {
                int open = s.indexOf('(', pos);
                if (open == -1) break;
                int close = s.indexOf(')', open);
                if (close == -1) break;

                String inside = s.substring(open + 1, close);
                underscoreCount += inside.isEmpty() ? 0 : inside.split("_").length;

                pos = close + 1;
            }

            out.println(maxWordLength + " " + underscoreCount);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

