        for (char c : s.toCharArray()) {
            if (c == '(') {
                inside = true;
                current.setLength(0);
            } else if (c == ')' && inside) {
                parenContents.add(current.toString());
                inside = false;
            } else if (inside) {
                current.append(c);
            }
        }

        // Find maximum word length and count non-empty words
        int maxLen = 0;
        int wordCount = 0;

        for (String content : parenContents) {
            String[] words = content.split("_");
            for (String word : words) {
                if (!word.isEmpty()) {
                    maxLen = Math.max(maxLen, word.length());
                    wordCount++;
                }
            }
        }

        System.out.println(maxLen + " " + wordCount);
    }
}

import java.util.*;
import java.util.stream.*;

public class TextDoc {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        scan.nextLine();
        String s = scan.nextLine();

        // Extract parenthetical content using regex
        List<String> parenContents = new ArrayList<>();
        int start = 0;
        while ((start = s.indexOf('(', start)) != -1) {
            int end = s.indexOf(')', start);
            if (end != -1) {
                parenContents.add(s.substring(start + 1, end));
                start = end + 1;
            } else {
                break;
            }
        }

        // Use streams to compute max length and count
        int[] result = parenContents.stream()
            .flatMap(content -> Arrays.stream(content.split("_")))
            .filter(word -> !word.isEmpty())
            .mapToInt(String::length)
            .reduce(new int[]{0, 0}, 
                (acc, len) -> { acc[0] = Math.max(acc[0], len); acc[1]++; return acc; },
                (acc1, acc2) -> { acc1[0] = Math.max(acc1[0], acc2[0]); acc1[1] += acc2[1]; return acc1; });

        System.out.println(result[0] + " " + result[1]);
    }
}

import java.util.*;

public class TextDoc {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        scan.nextLine();
        String s = scan.nextLine();

        // Extract parenthetical content using manual parsing with stack-like tracking
        List<String> parenContents = new ArrayList<>();
        int depth = 0;
        int startIdx = -1;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if (depth == 0) startIdx = i + 1;
                depth++;
            } else if (c == ')') {
                depth--;
                if (depth == 0 && startIdx != -1) {
                    parenContents.add(s.substring(startIdx, i));
                    startIdx = -1;
                }
            }
        }

        // Find maximum word length and count non-empty words
        int maxLen = 0;
        int wordCount = 0;

        for (String content : parenContents) {
            int idx = 0;
            int nextIdx;
            while ((nextIdx = content.indexOf('_', idx)) != -1) {
                String word = content.substring(idx, nextIdx);
                if (!word.isEmpty()) {
                    maxLen = Math.max(maxLen, word.length());
                    wordCount++;
                }
                idx = nextIdx + 1;
            }
            String lastWord = content.substring(idx);
            if (!lastWord.isEmpty()) {
                maxLen = Math.max(maxLen, lastWord.length());
                wordCount++;
            }
        }

        System.out.println(maxLen + " " + wordCount);
    }
}

