        StringBuilder bracketContent = new StringBuilder();
        int i = 0;
        int currentUnderscoreRun = 0;
        int maxUnderscoreRun = 0;
        int bracketGroupCount = 0;

        // Process the input string
        while (i < n) {
            if (input.charAt(i) == '(') {
                i++; // skip '('
                while (i < n && input.charAt(i) != ')') {
                    bracketContent.append(input.charAt(i));
                    i++;
                }
                i++; // skip ')'
                bracketContent.append('_');
                underscore.append('_');
            } else {
                underscore.append(input.charAt(i));
                i++;
            }
        }

        // Append trailing underscores to both buffers
        underscore.append('_');
        bracketContent.append('_');

        // Analyze underscore string for maximum consecutive non-underscore characters
        currentUnderscoreRun = 0;
        for (int j = 0; j < underscore.length(); j++) {
            if (underscore.charAt(j) == '_') {
                if (currentUnderscoreRun > maxUnderscoreRun) {
                    maxUnderscoreRun = currentUnderscoreRun;
                }
                currentUnderscoreRun = 0;
            } else {
                currentUnderscoreRun++;
            }
        }

        // Analyze bracket content for groups of non-underscore characters
        currentUnderscoreRun = 0;
        for (int j = 0; j < bracketContent.length(); j++) {
            if (bracketContent.charAt(j) == '_') {
                if (currentUnderscoreRun > 0) {
                    bracketGroupCount++;
                }
                currentUnderscoreRun = 0;
            } else {
                currentUnderscoreRun++;
            }
        }

        System.out.println(maxUnderscoreRun + " " + bracketGroupCount);
    }
}

