        int parenDepth = 0;
        StringBuilder currentWord = new StringBuilder();

        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '(') {
                parenDepth++;
                if (parenDepth == 1) {
                    processWord(currentWord, false, maxLenOutside, countInParens);
                    currentWord = new StringBuilder();
                } else {
                    currentWord.append(c);
