                if (parenDepth == 1) {
                    processWord(currentWord, true, maxLenOutside, countInParens);
                    currentWord = new StringBuilder();
                } else {
                    currentWord.append(c);
                }
                parenDepth--;
            } else if (c == '_') {
                if (parenDepth == 0) {
                    if (currentWord.length() > 0) {
                        maxLenOutside = Math.max(maxLenOutside, currentWord.length());
                        currentWord = new StringBuilder();
                    }
                } else {
                    currentWord.append(c);
