/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            String input = in.next();
            String pattern = "\\([\\w_]*\\)";
            String[] outSite = input.split(pattern);
            int longest = 0;
            for (String s : outSite) {
                longest = Math.max(longest, longestWords(s));
            }
            Pattern r = Pattern.compile(pattern);
            Matcher m = r.matcher(input);
            long numberInside = 0;
            while (m.find()) {
                numberInside += Arrays.stream(trimParentheses(m.group()).split("_")).filter(s -> !s.isEmpty()).count();
            }
            out.println(longest + " " + numberInside);
        }

        private int longestWords(String line) {
            return Arrays.stream(line.split("_")).map(String::length).max(Integer::compare).orElse(0);
        }

        private String trimParentheses(String input) {
            String temp = input.substring(1, input.length());
            return temp.substring(0, temp.length() - 1);
        }

    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int n = Integer.parseInt(br.readLine().trim());
            String input = br.readLine();

            String[] parts = input.split("\\([\\w_]*\\)");
            int maxLen = 0;
            for (String part : parts) {
                maxLen = Math.max(maxLen, maxWordLength(part));
            }

            long underscoreCount = 0;
            int i = 0;
            while (i < input.length()) {
                if (input.charAt(i) == '(') {
                    int j = i + 1;
                    while (j < input.length() && input.charAt(j) != ')') j++;
                    if (j < input.length()) {
                        String content = input.substring(i + 1, j);
                        underscoreCount += countUnderscoreSegments(content);
                        i = j + 1;
                        continue;
                    }
                }
                i++;
            }

            pw.println(maxLen + " " + underscoreCount);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private int maxWordLength(String s) {
        if (s.isEmpty()) return 0;
        int max = 0;
        int start = 0;
        for (int i = 0; i <= s.length(); i++) {
            if (i == s.length() || s.charAt(i) == '_') {
                max = Math.max(max, i - start);
                start = i + 1;
            }
        }
        return max;
    }

    private long countUnderscoreSegments(String s) {
        if (s.isEmpty()) return 0;
        long count = 1;
        for (char c : s.toCharArray()) {
            if (c == '_') count++;
        }
        return count;
    }
}

