public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    void execute() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        String s = sc.nextLine();

        String[] outside = s.split("\\([\\w_]*\\)");
        int maxWord = 0;
        for (String part : outside) {
            maxWord = Math.max(maxWord, findLongestWord(part));
        }

        long insideCount = 0;
        Pattern p = Pattern.compile("\\(([\\w_]*)\\)");
        Matcher m = p.matcher(s);
        while (m.find()) {
            String group = m.group(1);
            if (!group.isEmpty()) {
                insideCount += group.split("_", -1).length;
            }
        }

        System.out.println(maxWord + " " + insideCount);
    }

    int findLongestWord(String str) {
        if (str.isEmpty()) return 0;
        int max = 0, current = 0;
        for (int i = 0; i <= str.length(); i++) {
            if (i == str.length() || str.charAt(i) == '_') {
                max = Math.max(max, current);
                current = 0;
            } else {
                current++;
            }
        }
        return max;
    }
}

import java.io.*;
