public class Main {
    public static void main(String[] args) {
        new Main().start();
    }

    void start() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int n = Integer.parseInt(br.readLine());
            String line = br.readLine();

            int maxOutside = 0;
            int left = 0;
            for (int right = 0; right <= line.length(); right++) {
                if (right == line.length() || line.charAt(right) == '(') {
                    maxOutside = Math.max(maxOutside, longestInSegment(line.substring(left, right)));
                    left = right + 1;
                    while (left < line.length() && line.charAt(left) != ')') left++;
                    if (left < line.length()) left++;
                }
            }

            long insideCount = 0;
            Pattern pat = Pattern.compile("\\(([\\w_]*)\\)");
            Matcher mat = pat.matcher(line);
            while (mat.find()) {
                String inner = mat.group(1);
                if (!inner.isEmpty()) {
                    insideCount += inner.split("_", -1).length;
                }
            }

            pw.println(maxOutside + " " + insideCount);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    int longestInSegment(String seg) {
        if (seg.isEmpty()) return 0;
        int max = 0, curr = 0;
        for (char c : seg.toCharArray()) {
            if (c == '_') {
                max = Math.max(max, curr);
                curr = 0;
            } else {
                curr++;
            }
        }
        return Math.max(max, curr);
    }
}

