        int n = sc.nextInt();
        String s = sc.next();

        // Replace content inside parentheses with underscores
        StringBuilder sb = new StringBuilder();
        int depth = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                depth++;
                sb.append('_');
            } else if (c == ')') {
                depth--;
                sb.append('_');
            } else if (depth > 0) {
                sb.append('_');
            } else {
                sb.append(c);
            }
        }

        String processed = sb.toString();
        String[] tokens = processed.split("_+", -1);
        int maxLen = 0;
        for (String token : tokens) {
            if (!token.isEmpty()) {
                maxLen = Math.max(maxLen, token.length());
            }
        }

        System.out.println(maxLen);

        // Count underscore-separated segments inside parentheses
        int cnt = 0;
        depth = 0;
        StringBuilder inside = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '(') {
                depth++;
                inside.setLength(0);
            } else if (c == ')') {
                if (depth > 0) {
                    String content = inside.toString();
                    if (!content.isEmpty()) {
                        String[] segs = content.split("_+", -1);
                        for (String seg : segs) {
                            if (!seg.isEmpty()) cnt++;
                        }
                    }
                }
                depth--;
            } else if (depth > 0) {
                inside.append(c);
            }
        }

        System.out.println(cnt);
    }
}

