public class AK375 {
    private static final Scanner cin = new Scanner(System.in);

    public String process(int n, String str) {
        int maxLen = 0;
        int count = 0;
        StringBuilder sb1 = new StringBuilder();
        StringBuilder sb2 = new StringBuilder();
        int len = 0;

        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                while (i + 1 < n && str.charAt(i + 1) != ')') {
                    sb2.append(str.charAt(i + 1));
                    i++;
                }
            } else if (c == ')') {
                if (len > maxLen) maxLen = len;
                len = 0;
                sb1.append('.');
            } else {
                sb1.append(c);
                len++;
            }
        }
        if (len > maxLen) maxLen = len;

        String[] parts1 = sb1.toString().split("\\.");
        for (String part : parts1) {
            if (!part.isEmpty()) count++;
        }

        return maxLen + " " + count;
    }

    public static void main(String[] args) {
        AK375 solver = new AK375();
        while (cin.hasNextInt()) {
            int n = cin.nextInt();
            String str = cin.next();
            System.out.println(solver.process(n, str));
        }
    }
}

import java.util.*;

public class AK375 {
    static Scanner in = new Scanner(System.in);

    public String compute(int n, String s) {
        List<String> parenthesesContent = new ArrayList<>();
        int longestNonParen = 0;
        StringBuilder current = new StringBuilder();

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '(') {
                StringBuilder buf = new StringBuilder();
                i++;
                while (i < n && s.charAt(i) != ')') {
                    buf.append(s.charAt(i));
                    i++;
                }
                if (buf.length() > 0) parenthesesContent.add(buf.toString());
                i--;
            } else if (c == ')') {
                longestNonParen = Math.max(longestNonParen, current.length());
                current.setLength(0);
            } else {
                current.append(c);
            }
        }
        longestNonParen = Math.max(longestNonParen, current.length());

        return longestNonParen + " " + parenthesesContent.size();
    }

    public static void main(String[] args) {
        AK375 inst = new AK375();
        while (in.hasNext()) {
            int n = in.nextInt();
            String s = in.next();
            System.out.println(inst.compute(n, s));
        }
    }
}

import java.util.*;

public class AK375 {
    public static Scanner scanner = new Scanner(System.in);

    public String solve(int n, String input) {
        int maxPlainLength = 0;
        int segmentCount = 0;
        int currentPlainLength = 0;
        int parenthesizedSegments = 0;

        for (int idx = 0; idx < n; idx++) {
            char ch = input.charAt(idx);
            if (ch == '(') {
                parenthesizedSegments++;
                idx++;
                while (idx < n && input.charAt(idx) != ')') {
                    idx++;
                }
            } else if (ch == ')') {
                if (currentPlainLength > maxPlainLength) {
                    maxPlainLength = currentPlainLength;
                }
                currentPlainLength = 0;
                segmentCount++;
            } else {
                currentPlainLength++;
            }
        }
        if (currentPlainLength > maxPlainLength) {
            maxPlainLength = currentPlainLength;
        }

        return maxPlainLength + " " + parenthesizedSegments;
    }

    public static void main(String[] args) {
        AK375 solver = new AK375();
        while (scanner.hasNext()) {
            int n = scanner.nextInt();
            String input = scanner.next();
            System.out.println(solver.solve(n, input));
        }
    }
}

