public class AK375 {
    private static Scanner sc = new Scanner(System.in);

    public String execute(int len, String data) {
        int longestRun = 0;
        int parenthesesCount = 0;

        for (int p = 0; p < len; ) {
            char c = data.charAt(p);
            if (c == '(') {
                p++;
                while (p < len && data.charAt(p) != ')') {
                    p++;
                }
                parenthesesCount++;
            } else if (c == ')') {
                p++;
            } else {
                int run = 0;
                while (p < len && data.charAt(p) != '(' && data.charAt(p) != ')') {
                    run++;
                    p++;
                }
                if (run > longestRun) longestRun = run;
            }
        }

        return longestRun + " " + parenthesesCount;
    }

    public static void main(String[] args) {
        AK375 instance = new AK375();
        while (sc.hasNext()) {
            int n = sc.nextInt();
            String s = sc.next();
            System.out.println(instance.execute(n, s));
        }
    }
}

import java.util.*;

public class AK375 {
    private static Scanner cin = new Scanner(System.in);

    public String analyze(int size, String expr) {
        int maxNonSpecial = 0;
        int bracketGroups = 0;

        for (int i = 0; i < size; i++) {
            char ch = expr.charAt(i);
            if (ch == '(') {
                bracketGroups++;
                i++;
                while (i < size && expr.charAt(i) != ')') {
                    i++;
                }
            } else if (ch == ')') {
                continue;
            } else {
                int run = 0;
                while (i < size && expr.charAt(i) != '(' && expr.charAt(i) != ')') {
                    run++;
                    i++;
                }
                if (run > maxNonSpecial) maxNonSpecial = run;
                i--;
            }
        }

        return maxNonSpecial + " " + bracketGroups;
    }

    public static void main(String[] args) {
        AK375 handler = new AK375();
        while (cin.hasNext()) {
            int n = cin.nextInt();
            String s = cin.next();
            System.out.println(handler.analyze(n, s));
        }
    }
}

