public class Codechef {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        br.readLine();
        String line = br.readLine();

        int maxLen = 0;
        int count = 0;
        int anchor = 0;

        while (true) {
            int open = line.indexOf('(', anchor);
            if (open == -1 || open >= line.lastIndexOf(')')) break;

            int close = line.indexOf(')', open);
            if (close == -1) break;

            String pre = line.substring(anchor, open);
            for (String token : pre.split("_")) {
                maxLen = Math.max(maxLen, token.length());
            }

            String mid = line.substring(open + 1, close);
            for (String token : mid.split("_")) {
                if (!token.isEmpty()) count++;
            }

            anchor = close + 1;
        }

        String post = line.substring(anchor);
        for (String token : post.split("_")) {
            maxLen = Math.max(maxLen, token.length());
        }

        System.out.println(maxLen + " " + count);
    }
}

