                if (depth == 0) lastOpen = i;
                depth++;
            } else if (s[i] == ')' && depth > 0) {
                depth--;
                if (depth == 0 && lastOpen >= 0) {
                    boolean hasContent = false;
                    for (int k = lastOpen + 1; k < i; k++) {
                        if (s[k] != '_' && s[k] != '(') {
                            hasContent = true;
                            break;
                        }
                    }
                    if (hasContent) count++;
                }
            }
        }
        return count;
