        int max = 0;
        int current = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == '_' || s[i] == '(') {
                current = 0;
            } else {
                current++;
                max = Math.max(max, current);
            }
        }
        return max;
    }

    public static int countValidParenthesizedGroups(char[] s, int n) {
        int count = 0;
        int depth = 0;
        int lastOpen = -1;
        for (int i = 0; i < n; i++) {
