public class codeforces {

    public static int longestNonSpecial(char[] s, int n) {
        int max = 0;
        int i = 0;
        while (i < n) {
            if (s[i] == '_' || s[i] == '(') {
                i++;
                continue;
            }
            int j = i;
            while (j < n && s[j] != '_' && s[j] != '(') j++;
            max = Math.max(max, j - i);
            i = j;
        }
        return max;
    }

    public static int countParenthesizedSegments(char[] s, int n) {
        int count = 0;
        int depth = 0;
        int openPos = -1;
        for (int i = 0; i < n; i++) {
            if (s[i] == '(') {
                if (depth == 0) openPos = i;
                depth++;
            } else if (s[i] == ')') {
                depth--;
                if (depth == 0 && openPos >= 0) {
                    boolean hasContent = false;
                    for (int k = openPos + 1; k < i; k++) {
                        if (s[k] != '_' && s[k] != '(') {
                            hasContent = true;
                            break;
                        }
                    }
                    if (hasContent) count++;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
