import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    private void execute() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine());
            String s = br.readLine();

            int[] stats = analyzeString(s, n);
            System.out.println(stats[0] + " " + stats[1]);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private int[] analyzeString(String s, int n) {
        int maxLen = 0, wordCount = 0;
        boolean inParen = false, inWord = false;
        int currLen = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);

            if (c == '(') {
                if (inWord) {
                    if (currLen > maxLen) maxLen = currLen;
                    if (inParen) wordCount++;
                    inWord = false;
                    currLen = 0;
                }
                inParen = true;
            } else if (c == ')') {
                if (inWord) {
                    if (currLen > maxLen) maxLen = currLen;
                    if (inParen) wordCount++;
                    inWord = false;
                    currLen = 0;
                }
                inParen = false;
            } else if (c == '_') {
                if (inWord) {
                    if (currLen > maxLen) maxLen = currLen;
                    if (inParen) wordCount++;
                    inWord = false;
                    currLen = 0;
                }
            } else {
                inWord = true;
                currLen++;
                if (i == n - 1) {
                    if (currLen > maxLen) maxLen = currLen;
                    if (inParen) wordCount++;
                }
            }
        }

        return new int[]{maxLen, wordCount};
    }
}

