public class Text_Document_Analysis {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        br.readLine();
        String line = br.readLine();

        int maxLen = 0;
        int i = 0;
        while (i < line.length()) {
            if (line.charAt(i) == '(') {
                int start = i + 1;
                while (i < line.length() && line.charAt(i) != ')') i++;
                String id = line.substring(start, i);
                int j = 0;
                while (j < id.length()) {
                    int k = j;
                    while (k < id.length() && Character.isLetter(id.charAt(k))) k++;
                    if (k > j) {
                        maxLen = Math.max(maxLen, k - j);
                    }
                    j = k + 1;
                }
            } else {
                int j = i;
                while (j < line.length() && line.charAt(j) != '(') j++;
                String segment = line.substring(i, j);
                String[] parts = segment.split("_+");
                for (String p : parts) {
                    maxLen = Math.max(maxLen, p.length());
                }
                i = j;
                continue;
            }
            i++;
        }

        int count = 0;
        boolean inParens = false;
        boolean prevWasLetter = false;

        for (int j = 0; j < line.length(); j++) {
            char c = line.charAt(j);
            if (c == '(') {
                inParens = true;
                prevWasLetter = false;
            } else if (c == ')') {
                inParens = false;
                prevWasLetter = false;
            } else if (inParens && Character.isLetter(c)) {
                if (!prevWasLetter) {
                    count++;
                }
                prevWasLetter = true;
            } else {
                prevWasLetter = false;
            }
        }

        System.out.println(maxLen + " " + count);
    }
}

