public class GregAndFriends {
	static int n, k, a = 0, b = 0;
	static long MOD = 1000000007, ans = 0;
	static long[][] choose = new long[100][100];
	static LinkedList<Integer> q = new LinkedList<Integer>();
	static HashMap<Integer, Pair> ways = new HashMap<Integer, Pair>();
	static class Pair {
		int d;
		long w;
		public Pair(int D, long W) {
			d = D;
			w = W;
		}
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		k = sc.nextInt();
		for(int i = 0; i < n; i++)
			if(sc.nextInt() == 50)
				a++;
			else
				b++;
		sc.close();
		fillChoose();
		int startMask = 1000000 + 100 * a + b;
		q.add(startMask);
		ways.put(startMask, new Pair(0, 1));
		while(!q.isEmpty())
			bfs(q.pollFirst());
		System.out.println(ways.containsKey(0) ? ways.get(0).d + "\n" + ways.get(0).w : "-1\n0");
	}
	static void bfs(int mask) {
		int boat = mask / 1000000;
		int nA = (mask % 1000000) / 100, nB = mask % 100;
		if(boat > 0) {
			for(int i = nA; i >= 0 && 50 * (nA - i) <= k; i--)
				for(int j = nB; j >= 0 && 50 * (nA - i) + 100 * (nB - j) <= k; j--)
					if(i != nA || j != nB)
						resolve(i, j, boat, mask, choose[nA][i] * choose[nB][j] % MOD);
		} else {
			for(int i = nA; i <= a && 50 * (i - nA) <= k; i++)
				for(int j = nB; j <= b && 50 * (i - nA) + 100 * (j - nB) <= k; j++)
					if(i != nA || j != nB)
						resolve(i, j, boat, mask, choose[a - nA][i - nA] * choose[b - nB][j - nB] % MOD);
		}
	}
	static void resolve(int i, int j, int boat, int mask, long edgeWays) {
		int newMask = 1000000 * (1 - boat) + i * 100 + j;
		int newD = ways.get(mask).d + 1;
		if(!ways.containsKey(newMask)) {
			ways.put(newMask, new Pair(newD, 0));
			q.add(newMask);
		}
		if(ways.get(newMask).d == newD)
			ways.get(newMask).w = (ways.get(newMask).w + ways.get(mask).w * edgeWays % MOD) % MOD;
	}
	static void fillChoose() {
		for(int i = 0; i < 100; i++)
			choose[i][0] = 1;
		for(int i = 1; i < 100; i++)
			for(int j = 1; j <= i; j++)
				choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD;
	}
}

import java.util.*;

public class GregAndFriends {
    static int n, k, a = 0, b = 0;
    static final long MOD = 1000000007L;
    static long[][] choose = new long[100][100];
    static Queue<Integer> queue = new LinkedList<>();
    static Map<Integer, State> stateMap = new HashMap<>();

    static class State {
        int depth;
        long ways;

        State(int d, long w) {
            depth = d;
            ways = w;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        for (int i = 0; i < n; i++) {
            if (sc.nextInt() == 50) a++;
            else b++;
        }
        sc.close();

        precomputeBinomialCoefficients();
        int startState = encodeState(1, a, b);
        queue.offer(startState);
        stateMap.put(startState, new State(0, 1));

        while (!queue.isEmpty()) {
            bfs(queue.poll());
        }

        if (stateMap.containsKey(0)) {
            State finalState = stateMap.get(0);
            System.out.println(finalState.depth + "\n" + finalState.ways);
        } else {
            System.out.println("-1\n0");
        }
    }

    static void bfs(int state) {
        int boat = state / 1000000;
        int currA = (state % 1000000) / 100;
        int currB = state % 100;

        if (boat == 1) {
            for (int takeA = currA; takeA >= 0 && 50 * (currA - takeA) <= k; takeA--) {
                for (int takeB = currB; takeB >= 0 && 50 * (currA - takeA) + 100 * (currB - takeB) <= k; takeB--) {
                    if (takeA != currA || takeB != currB) {
                        long ways = (choose[currA][takeA] * choose[currB][takeB]) % MOD;
                        updateState(takeA, takeB, 0, state, ways);
                    }
                }
            }
        } else {
            for (int takeA = currA; takeA <= a && 50 * (takeA - currA) <= k; takeA++) {
                for (int takeB = currB; takeB <= b && 50 * (takeA - currA) + 100 * (takeB - currB) <= k; takeB++) {
                    if (takeA != currA || takeB != currB) {
                        long ways = (choose[a - currA][takeA - currA] * choose[b - currB][takeB - currB]) % MOD;
                        updateState(takeA, takeB, 1, state, ways);
                    }
                }
            }
        }
    }

    static void updateState(int newA, int newB, int newBoat, int oldState, long edgeWays) {
        int newState = encodeState(newBoat, newA, newB);
        int newDepth = stateMap.get(oldState).depth + 1;

        if (!stateMap.containsKey(newState)) {
            stateMap.put(newState, new State(newDepth, 0));
            queue.offer(newState);
        }

        if (stateMap.get(newState).depth == newDepth) {
            long currentWays = stateMap.get(newState).ways;
            long updatedWays = (currentWays + (stateMap.get(oldState).ways * edgeWays) % MOD) % MOD;
            stateMap.get(newState).ways = updatedWays;
        }
    }

    static void precomputeBinomialCoefficients() {
        for (int i = 0; i < 100; i++) {
            choose[i][0] = 1;
        }
        for (int i = 1; i < 100; i++) {
            for (int j = 1; j <= i; j++) {
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD;
            }
        }
    }

    static int encodeState(int boat, int aCount, int bCount) {
        return 1000000 * boat + 100 * aCount + bCount;
    }
}

