            for (int take50 = curr50; take50 >= 0 && 50 * (curr50 - take50) <= k; take50--) {
                for (int take100 = curr100; take100 >= 0 && 50 * (curr50 - take50) + 100 * (curr100 - take100) <= k; take100--) {
                    if (take50 != curr50 || take100 != curr100) {
                        long comb = (C[curr50][take50] * C[curr100][take100]) % MOD;
                        int nextBoat = 0;
                        int next50 = take50;
                        int next100 = take100;
                        updateState(nextBoat, next50, next100, state, comb);
                    }
                }
            }
        } else {
            for (int take50 = curr50; take50 <= people50 && 50 * (take50 - curr50) <= k; take50++) {
                for (int take100 = curr100; take100 <= people100 && 50 * (take50 - curr50) + 100 * (take100 - curr100) <= k; take100++) {
                    if (take50 != curr50 || take100 != curr100) {
                        long comb = (C[people50 - curr50][take50 - curr50] * C[people100 - curr100][take100 - curr100]) % MOD;
                        int nextBoat = 1;
                        int next50 = take50;
                        int next100 = take100;
                        updateState(nextBoat, next50, next100, state, comb);
                    }
                }
            }
        }
    }

    static void updateState(int boat, int a, int b, int prev, long comb) {
        int next = encode(boat, a, b);
        int newDist = visited.get(prev).dist + 1;

        if (!visited.containsKey(next)) {
            visited.put(next, new Node(newDist, 0));
            q.add(next);
        }

        if (visited.get(next).dist == newDist) {
            long newWays = (visited.get(next).cnt + visited.get(prev).cnt * comb % MOD) % MOD;
            visited.get(next).cnt = newWays;
        }
    }

    static void buildCombinationTable() {
        for (int i = 0; i < 100; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }
    }

    static int encode(int boat, int a, int b) {
        return 1000000 * boat + 100 * a + b;
    }
}

