public class GregAndFriends {
    static int n, k, count50 = 0, count100 = 0;
    static final long MOD = 1000000007;
    static long[][] binom = new long[100][100];
    static Deque<Integer> deque = new ArrayDeque<>();
    static Map<Integer, Result> memo = new HashMap<>();

    static class Result {
        int steps;
        long paths;

        Result(int s, long p) {
            steps = s;
            paths = p;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        k = scanner.nextInt();
        for (int i = 0; i < n; i++) {
            int weight = scanner.nextInt();
            if (weight == 50) count50++;
            else count100++;
        }
        scanner.close();

        computeBinomial();
        int initial = pack(1, count50, count100);
        deque.push(initial);
        memo.put(initial, new Result(0, 1));

        while (!deque.isEmpty()) {
            expand(deque.pop());
        }

        Result finalResult = memo.get(0);
        if (finalResult != null) {
            System.out.println(finalResult.steps + "\n" + finalResult.paths);
        } else {
            System.out.println("-1\n0");
        }
    }

    static void expand(int state) {
        int boat = state / 1000000;
        int curr50 = (state % 1000000) / 100;
        int curr100 = state % 100;

        if (boat == 1) {
            for (int take50 = curr50; take50 >= 0 && 50 * (curr50 - take50) <= k; take50--) {
                for (int take100 = curr100; take100 >= 0 && 50 * (curr50 - take50) + 100 * (curr100 - take100) <= k; take100--) {
                    if (take50 != curr50 || take100 != curr100) {
                        long comb = (binom[curr50][take50] * binom[curr100][take100]) % MOD;
                        int next = pack(0, take50, take100);
                        update(next, state, comb);
                    }
                }
            }
        } else {
            for (int take50 = curr50; take50 <= count50 && 50 * (take50 - curr50) <= k; take50++) {
                for (int take100 = curr100; take100 <= count100 && 50 * (take50 - curr50) + 100 * (take100 - curr100) <= k; take100++) {
                    if (take50 != curr50 || take100 != curr100) {
                        long comb = (binom[count50 - curr50][take50 - curr50] * binom[count100 - curr100][take100 - curr100]) % MOD;
                        int next = pack(1, take50, take100);
                        update(next, state, comb);
                    }
                }
            }
        }
    }

    static void update(int next, int prev, long comb) {
        int newDepth = memo.get(prev).steps + 1;
        if (!memo.containsKey(next)) {
            memo.put(next, new Result(newDepth, 0));
            deque.push(next);
        }
        if (memo.get(next).steps == newDepth) {
            long newPaths = (memo.get(next).paths + memo.get(prev).paths * comb % MOD) % MOD;
            memo.get(next).paths = newPaths;
        }
    }

    static void computeBinomial() {
        for (int i = 0; i < 100; i++) {
            binom[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % MOD;
            }
        }
    }

    static int pack(int boat, int a, int b) {
        return 1000000 * boat + 100 * a + b;
    }
}

