public class GregAndFriends {
    static int n, k, groupA = 0, groupB = 0;
    static final long MOD = 1000000007L;
    static long[][] comb = new long[100][100];
    static Queue<Integer> queue = new LinkedList<>();
    static Map<Integer, Info> info = new HashMap<>();

    static class Info {
        int level;
        long count;

        Info(int l, long c) {
            level = l;
            count = c;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        k = in.nextInt();
        for (int i = 0; i < n; i++) {
            int w = in.nextInt();
            if (w == 50) groupA++;
            else groupB++;
        }
        in.close();

        precompute();
        int start = encode(1, groupA, groupB);
        queue.add(start);
        info.put(start, new Info(0, 1));

        while (!queue.isEmpty()) {
            int cur = queue.remove();
            process(cur);
        }

        Info res = info.get(0);
        if (res != null) {
            System.out.println(res.level + "\n" + res.count);
        } else {
            System.out.println("-1\n0");
        }
    }

    static void process(int state) {
        int boat = state / 1000000;
        int curA = (state % 1000000) / 100;
        int curB = state % 100;

        if (boat == 1) {
            for (int i = curA; i >= 0 && 50 * (curA - i) <= k; i--) {
                for (int j = curB; j >= 0 && 50 * (curA - i) + 100 * (curB - j) <= k; j--) {
                    if (i != curA || j != curB) {
                        long ways = (comb[curA][i] * comb[curB][j]) % MOD;
                        int next = encode(0, i, j);
                        apply(next, state, ways);
                    }
                }
            }
        } else {
            for (int i = curA; i <= groupA && 50 * (i - curA) <= k; i++) {
                for (int j = curB; j <= groupB && 50 * (i - curA) + 100 * (j - curB) <= k; j++) {
                    if (i != curA || j != curB) {
                        long ways = (comb[groupA - curA][i - curA] * comb[groupB - curB][j - curB]) % MOD;
                        int next = encode(1, i, j);
                        apply(next, state, ways);
                    }
                }
            }
        }
    }

    static void apply(int next, int prev, long ways) {
        int newLevel = info.get(prev).level + 1;
        if (!info.containsKey(next)) {
            info.put(next, new Info(newLevel, 0));
            queue.add(next);
        }
        if (info.get(next).level == newLevel) {
            long updated = (info.get(next).count + info.get(prev).count * ways % MOD) % MOD;
            info.get(next).count = updated;
        }
    }

    static void precompute() {
        for (int i = 0; i < 100; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }
    }

    static int encode(int boat, int a, int b) {
        return 1000000 * boat + 100 * a + b;
    }
}

