public class Main {
    long mod = 1_000_000_007;

    long inv(long n) {
        long k = mod - 2;
        long res = 1;
        long a = n;
        while(k > 0) {
            if ((k & 1) > 0) {
                res = (res * a) % mod;
            }
            a = (a * a) % mod;
            k >>= 1;
        }
        return res;
    }

    public void solve() {
        long[] f = new long[51];
        f[0] = 1;
        for (int i = 1; i < 51; i++) {
            f[i] = (f[i - 1] * i) % mod;
        }
        long[][] c = new long[51][51];
        for (int i = 0; i < 51; i++) {
            c[i][0] = 1;
        }
        for (int i = 1; i < 51; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (f[i] * inv(((f[j] * f[i - j]) % mod))) % mod;
            }
        }

        int n = ni();
        int k = ni();
        int c50 = 0, c100 = 0;
        for (int i = 0; i < n; i++) {
            if (ni() == 100) c100++;
            else c50++;
        }
