import java.io.*;
import java.util.*;

public class Main {
    final long MOD = 1_000_000_007L;

    long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    long modInverse(long a) {
        return modPow(a, MOD - 2);
    }

    public void solve() {
        long[] fact = new long[51];
        fact[0] = 1;
        for (int i = 1; i <= 50; i++) {
            fact[i] = (fact[i-1] * i) % MOD;
        }

        long[][] comb = new long[51][51];
        for (int i = 0; i <= 50; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = (fact[i] * modInverse((fact[j] * fact[i-j]) % MOD)) % MOD;
            }
        }

        int n = ni(), k = ni();
        int cnt50 = 0, cnt100 = 0;
        for (int i = 0; i < n; i++) {
            if (ni() == 100) cnt100++;
            else cnt50++;
        }

        Node[][][] nodes = new Node[cnt50+1][cnt100+1][2];
        for (int i = 0; i <= cnt50; i++) {
            for (int j = 0; j <= cnt100; j++) {
                nodes[i][j][0] = new Node(i, j, 0);
                nodes[i][j][1] = new Node(i, j, 1);
            }
        }

        for (int i = 0; i <= cnt50; i++) {
            for (int j = 0; j <= cnt100; j++) {
                int max50 = Math.min(k / 50, i);
                int max100 = Math.min(k / 100, j);
                for (int x = max100; x >= 0; x--) {
                    for (int y = Math.min(max50, (k - 100*x) / 50); y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        Node from = nodes[i][j][0];
                        Node to = nodes[i-y][j-x][1];
                        from.neighbors.add(to);
                        to.neighbors.add(from);
                    }
                }
            }
        }

        ArrayDeque<Node> queue = new ArrayDeque<>();
        nodes[cnt50][cnt100][0].dist = 1;
        nodes[cnt50][cnt100][0].count = 1;
        queue.add(nodes[cnt50][cnt100][0]);

        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            for (Node neighbor : cur.neighbors) {
                if (neighbor.dist == 0 || neighbor.dist == cur.dist + 1) {
                    int fivePick = cur.b == 0 ? cur.cnt50 : cnt50 - cur.cnt50;
                    int fiveDiff = Math.abs(cur.cnt50 - neighbor.cnt50);
                    long p1 = comb[fivePick][fiveDiff];

                    int hundredPick = cur.b == 0 ? cur.cnt100 : cnt100 - cur.cnt100;
                    int hundredDiff = Math.abs(cur.cnt100 - neighbor.cnt100);
                    long p2 = comb[hundredPick][hundredDiff];

                    long transition = (p1 * p2) % MOD;
                    neighbor.count = (neighbor.count + (cur.count * transition) % MOD) % MOD;

                    if (neighbor.dist == 0) {
                        neighbor.dist = cur.dist + 1;
                        queue.add(neighbor);
                    }
                }
            }
        }

        Node target = nodes[0][0][1];
        write((target.dist - 1) + "\n" + target.count + "\n");
    }

    static class Node {
        int cnt50, cnt100, b, dist;
        long count;
        List<Node> neighbors;

        Node(int a, int c, int flag) {
            cnt50 = a;
            cnt100 = c;
            b = flag;
            neighbors = new ArrayList<>();
            dist = 0;
            count = 0;
        }
    }

    public static void main(String[] args) {
        Main solver = new Main();
        solver.solve();
    }

    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    StringTokenizer st;

    String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException ignored) {}
        }
        return st.nextToken();
    }

    int ni() {
        return Integer.parseInt(nextToken());
    }

    void write(String s) {
        System.out.print(s);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;


public class Abood2D {

	static int N, fifty, hundred, K;
	static int memo[][][];
	static int memo2[][][][];
	static final int MOD = (int) 1e9 + 7;
	static long[][] comb; 

	static int solve(int t, int f, int h) {
		if(f == 0 && h == 0)
			return 0;

		if(memo[t][f][h] != -1)
			return memo[t][f][h];

		if(t == 1)
			return 1 + (f < fifty ? solve(0, f + 1, h) : solve(0, f, h + 1));

		int ans = (int) 1e6;

		for (int i = 0; i <= f; i++) {
			if(i * 50 > K)
				break;

			int j = Math.min(( K - i * 50) / 100, h);

			int totalW = i * 50 + j * 100;

			if(fifty - f + i > 0 && totalW > 50 || hundred - h + j > 1 && totalW > 100 || i == fifty && j == hundred)
				ans = Math.min(ans, solve(1, f - i, h - j));

		}

		return memo[t][f][h] = ans + 1;
	}

	static int solve2(int t, int f, int h, int r) {
		if(r == 0 && f == 0 && h == 0)
			return 1;


		if(r == 0)
			return 0;

		if(memo2[t][f][h][r] != -1)
			return memo2[t][f][h][r];


		int ans = 0;

		if(t == 1) {
			for (int i = 0; i <= fifty - f; ++i) {
				if(i * 50 > K)
					break;
				for (int j = 0; j <= hundred - h; ++j) {		
					if(i == 0 && j == 0)
						continue;
					int totalW = i * 50 + j * 100;

					if(totalW > K)
						break;

					ans = (int) ((1l * ans + (1l * (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD) * solve2(0, f + i, h + j, r - 1) % MOD) % MOD);

				}


			}
		} else {
			for (int i = 0; i <= f; ++i) {
				if(i * 50 > K)
					break;
				for (int j = 0; j <= h; ++j) {		
					if(i == 0 && j == 0)
						continue;
					int totalW = i * 50 + j * 100;

					if(totalW > K)
						break;

					ans = (int) ((1l * ans + (1l * (nCk(f, i) * nCk(h, j)) % MOD) * solve2(1, f - i, h - j, r - 1) % MOD)) % MOD;

				}


			}
		}

		return memo2[t][f][h][r] = ans;
	}


	static long nCk(int n, int k)		// O(n * k)
	{
		if(n < k)					
			return 0;
