        if (t == 1) {
            int res = 1 + (f < fifty ? solve(0, f + 1, h) : solve(0, f, h + 1));
            return memo[t][f][h] = res;
        }
        int ans = (int) 1e6;
        for (int i = 0; i <= f; i++) {
