import java.io.*;
import java.util.*;

public class Abood2D {

    static int N, fifty, hundred, K;
    static int[][][] memo;
    static int[][][][] memo2;
    static final int MOD = 1000000007;
    static long[][] comb;

    static int solve(int t, int f, int h) {
        if (f == 0 && h == 0) return 0;
        if (memo[t][f][h] != -1) return memo[t][f][h];
        if (t == 1) {
            int nextF = f < fifty ? f + 1 : f;
            int nextH = f < fifty ? h : h + 1;
            int res = 1 + solve(0, nextF, nextH);
            return memo[t][f][h] = res;
        }
        int ans = 1_000_000;
        for (int i = 0; i <= f; i++) {
            if (i * 50 > K) break;
            int j = Math.min((K - i * 50) / 100, h);
            int totalW = i * 50 + j * 100;
            if ((fifty - f + i > 0 && totalW > 50) || (hundred - h + j > 1 && totalW > 100) || (i == fifty && j == hundred)) {
                ans = Math.min(ans, solve(1, f - i, h - j));
            }
        }
        return memo[t][f][h] = ans + 1;
    }

    static int solve2(int t, int f, int h, int r) {
        if (r == 0 && f == 0 && h == 0) return 1;
        if (r == 0) return 0;
        if (memo2[t][f][h][r] != -1) return memo2[t][f][h][r];
        int ans = 0;
        if (t == 1) {
            for (int i = 0; i <= fifty - f; ++i) {
                if (i * 50 > K) break;
                for (int j = 0; j <= hundred - h; ++j) {
                    if (i == 0 && j == 0) continue;
                    int totalW = i * 50 + j * 100;
                    if (totalW > K) break;
                    long combVal = (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD;
                    ans = (int) ((ans + combVal * solve2(0, f + i, h + j, r - 1)) % MOD);
                }
            }
        } else {
            for (int i = 0; i <= f; ++i) {
                if (i * 50 > K) break;
                for (int j = 0; j <= h; ++j) {
                    if (i == 0 && j == 0) continue;
                    int totalW = i * 50 + j * 100;
                    if (totalW > K) break;
                    long combVal = (nCk(f, i) * nCk(h, j)) % MOD;
                    ans = (int) ((ans + combVal * solve2(1, f - i, h - j, r - 1)) % MOD);
                }
            }
        }
        return memo2[t][f][h][r] = ans;
    }

    static long nCk(int n, int k) {
        if (n < k) return 0;
        if (k == 0 || k == n) return 1;
        if (comb[n][k] != -1) return comb[n][k];
        if (n - k < k) return comb[n][k] = nCk(n, n - k);
        long temp = ((long) n * nCk(n - 1, k - 1)) % MOD;
        return comb[n][k] = (temp * pow(k, MOD - 2)) % MOD;
    }

    static long pow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        N = sc.nextInt();
        K = sc.nextInt();
        for (int i = 0; i < N; i++) {
            int val = sc.nextInt();
            if (val == 50) fifty++; else hundred++;
        }
        memo = new int[2][fifty + 1][hundred + 1];
        for (int i = 0; i < 2; i++) {
