import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.io.IOException;
import java.util.ArrayDeque;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CGregAndFriends solver = new CGregAndFriends();
        solver.solve(1, in, out);
        out.close();
    }

    static class CGregAndFriends {
        long mod = 1000000007;
        long INF = (long) 1e18 + 1;
        PrintWriter out;
        InputReader in;
        long[][] nCr = new long[100][100];

        long f(long p, int a, int b, int c, int d) {
            p *= nCr[a][b];
            p %= mod;
            p *= nCr[c][d];
            p %= mod;
            return p;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            int n = ni();
            int K = ni();
            int cnt1 = 0, cnt2 = 0;
            int i = 0, j = 0, k = 0;
            for (i = 0; i < 100; i++) {
                for (j = 0; j <= i; j++) {
                    if (j == 0 || j == i)
                        nCr[i][j] = 1;
                    else
                        nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod;
                }
            }
            for (i = 0; i < n; i++) {
                if (ni() == 50)
                    cnt1++;
                else
                    cnt2++;
            }
            long[][][] dist = new long[200][200][2];
            long[][][] dp = new long[200][200][2];
            for (i = 0; i < 200; i++) {
                for (j = 0; j < 200; j++)
                    Arrays.fill(dist[i][j], INF);
            }
            dist[0][0][0] = 0;
            dp[0][0][0] = 1;
            ArrayDeque<Tuple> pq = new ArrayDeque<>();
            pq.add(new Tuple(0, 0, 0, 0));
            while (pq.size() > 0) {
                Tuple curr = pq.poll();
                int x = curr.x;
                int y = curr.y;
                int z = curr.z;
                long d = dist[x][y][z];
                if (z == 0) {
                    int rem_x = cnt1 - x;
                    int rem_y = cnt2 - y;
                    for (i = 0; i <= rem_x; i++) {
                        for (j = 0; j <= rem_y; j++) {
                            if (i + j == 0)
                                continue;
                            if (i * 50 + j * 100 > K)
                                break;
                            if (dist[i + x][j + y][z ^ 1] >= d + 1) {
                                if (dist[i + x][j + y][z ^ 1] > d + 1) {
                                    dist[i + x][j + y][z ^ 1] = d + 1;
                                    pq.add(new Tuple(dist[i + x][j + y][z ^ 1], i + x, j + y, z ^ 1));
                                    dp[i + x][j + y][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[i + x][j + y][z ^ 1] %= mod;
                                } else {
                                    dp[i + x][j + y][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[i + x][j + y][z ^ 1] %= mod;
                                }
                            }
                        }
                    }
                } else {
                    int rem_x = x;
                    int rem_y = y;
                    for (i = 0; i <= rem_x; i++) {
                        for (j = 0; j <= rem_y; j++) {
                            if (i + j == 0)
                                continue;
                            if (i * 50 + j * 100 > K)
                                break;
                            if (dist[x - i][y - j][z ^ 1] >= d + 1) {
                                if (dist[x - i][y - j][z ^ 1] > d + 1) {
                                    dist[x - i][y - j][z ^ 1] = d + 1;
                                    pq.add(new Tuple(dist[x - i][y - j][z ^ 1], x - i, y - j, z ^ 1));
                                    dp[x - i][y - j][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[x - i][y - j][z ^ 1] %= mod;
                                } else {
                                    dp[x - i][y - j][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[x - i][y - j][z ^ 1] %= mod;
                                }
                            }
                        }
                    }
                }
            }
            if (dist[cnt1][cnt2][1] == INF)
                pn(-1);
            else
                pn(dist[cnt1][cnt2][1]);
            pn(dp[cnt1][cnt2][1]);
        }

        int ni() {
            return in.nextInt();
        }

        void pn(long zx) {
            out.println(zx);
        }

        class Tuple {
            long d;
            int x;
            int y;
            int z;

            Tuple(long d, int x, int y, int z) {
                this.d = d;
                this.x = x;
                this.y = y;
                this.z = z;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();
        solver.solve(1, in, out);
        out.close();
    }

    static class Solver {
        static final long MOD = 1000000007L;
        static final long INF = (long)1e18 + 1;
        long[][] nCr = new long[100][100];

        long comb(long base, int a, int b, int c, int d) {
            base = (base * nCr[a][b]) % MOD;
            base = (base * nCr[c][d]) % MOD;
            return base;
        }

        void solve(int testNum, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int K = in.nextInt();
            int cnt50 = 0, cnt100 = 0;
            for (int i = 0; i < n; i++) {
                if (in.nextInt() == 50) cnt50++;
                else cnt100++;
            }

            // Precompute binomial coefficients
            for (int i = 0; i < 100; i++) {
                for (int j = 0; j <= i; j++) {
                    if (j == 0 || j == i) nCr[i][j] = 1;
                    else nCr[i][j] = (nCr[i-1][j] + nCr[i-1][j-1]) % MOD;
                }
            }

            long[][][] dist = new long[200][200][2];
            long[][][] ways = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                    Arrays.fill(ways[i][j], 0);
                }
            }

            dist[0][0][0] = 0;
            ways[0][0][0] = 1;

            Deque<State> queue = new ArrayDeque<>();
            queue.offer(new State(0, 0, 0, 0));

            while (!queue.isEmpty()) {
                State cur = queue.poll();
                int x = cur.x;
                int y = cur.y;
                int side = cur.side;
                long d = dist[x][y][side];

                if (side == 0) {
                    int rem50 = cnt50 - x;
                    int rem100 = cnt100 - y;
                    for (int take50 = 0; take50 <= rem50; take50++) {
                        for (int take100 = 0; take100 <= rem100; take100++) {
                            if (take50 + take100 == 0) continue;
                            if (take50 * 50 + take100 * 100 > K) break;

                            int nx = x + take50;
                            int ny = y + take100;
                            int nside = side ^ 1;
                            long nd = d + 1;

                            if (dist[nx][ny][nside] >= nd) {
                                if (dist[nx][ny][nside] > nd) {
                                    dist[nx][ny][nside] = nd;
                                    queue.offer(new State(nx, ny, nside, nd));
                                }
                                ways[nx][ny][nside] = (ways[nx][ny][nside] + comb(ways[x][y][side], rem50, take50, rem100, take100)) % MOD;
                            }
                        }
                    }
                } else {
                    int rem50 = x;
                    int rem100 = y;
                    for (int take50 = 0; take50 <= rem50; take50++) {
                        for (int take100 = 0; take100 <= rem100; take100++) {
                            if (take50 + take100 == 0) continue;
                            if (take50 * 50 + take100 * 100 > K) break;

                            int nx = x - take50;
                            int ny = y - take100;
                            int nside = side ^ 1;
                            long nd = d + 1;

                            if (dist[nx][ny][nside] >= nd) {
                                if (dist[nx][ny][nside] > nd) {
                                    dist[nx][ny][nside] = nd;
                                    queue.offer(new State(nx, ny, nside, nd));
                                }
                                ways[nx][ny][nside] = (ways[nx][ny][nside] + comb(ways[x][y][side], rem50, take50, rem100, take100)) % MOD;
                            }
                        }
                    }
                }
            }

            if (dist[cnt50][cnt100][1] == INF) {
                out.println(-1);
            } else {
                out.println(dist[cnt50][cnt100][1]);
            }
            out.println(ways[cnt50][cnt100][1]);
        }

        static class State {
            int x, y, side;
            long d;
            State(int x, int y, int side, long d) {
                this.x = x;
                this.y = y;
                this.side = side;
                this.d = d;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        InputReader(InputStream in) { this.in = in; }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try { len = in.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (isSpace(c)) c = read();
            int val = 0, sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            for (; '0' <= c && c <= '9'; c = read()) val = val * 10 + c - '0';
            return val * sign;
        }

        private boolean isSpace(int c) { return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1; }
    }
}

