    static class CGregAndFriends {
        static final long MOD = 1000000007L;
        static final long INF = (long)1e18 + 1;
        long[][] C = new long[100][100];

        long ways(long base, int a, int b, int c, int d) {
            base = (base * C[a][b]) % MOD;
            base = (base * C[c][d]) % MOD;
            return base;
        }

        void solve(int testNum, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int K = in.nextInt();
            int cnt50 = 0, cnt100 = 0;
            for (int i = 0; i < n; i++) {
                if (in.nextInt() == 50) cnt50++;
                else cnt100++;
            }

            for (int i = 0; i < 100; i++) {
                for (int j = 0; j <= i; j++) {
                    C[i][j] = (j == 0 || j == i) ? 1 : (C[i-1][j] + C[i-1][j-1]) % MOD;
                }
            }

            long[][][] dist = new long[200][200][2];
            long[][][] num = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                }
            }

            dist[0][0][0] = 0;
            num[0][0][0] = 1;

            Deque<State> dq = new ArrayDeque<>();
            dq.add(new State(0, 0, 0, 0));

            while (!dq.isEmpty()) {
                State s = dq.removeFirst();
                int x = s.x;
                int y = s.y;
                int side = s.side;
                long d = dist[x][y][side];

                if (side == 0) {
                    int r50 = cnt50 - x;
                    int r100 = cnt100 - y;
                    for (int t50 = 0; t50 <= r50; t50++) {
                        for (int t100 = 0; t100 <= r100; t100++) {
                            if (t50 + t100 == 0) continue;
                            if (t50 * 50 + t100 * 100 > K) break;

                            int nx = x + t50;
                            int ny = y + t100;
                            int ns = side ^ 1;
                            long nd = d + 1;

                            if (dist[nx][ny][ns] >= nd) {
                                if (dist[nx][ny][ns] > nd) {
                                    dist[nx][ny][ns] = nd;
                                    dq.addLast(new State(nx, ny, ns, nd));
                                }
                                num[nx][ny][ns] = (num[nx][ny][ns] + ways(num[x][y][side], r50, t50, r100, t100)) % MOD;
                            }
                        }
                    }
                } else {
                    int r50 = x;
                    int r100 = y;
                    for (int t50 = 0; t50 <= r50; t50++) {
                        for (int t100 = 0; t100 <= r100; t100++) {
                            if (t50 + t100 == 0) continue;
                            if (t50 * 50 + t100 * 100 > K) break;

                            int nx = x - t50;
                            int ny = y - t100;
                            int ns = side ^ 1;
                            long nd = d + 1;

                            if (dist[nx][ny][ns] >= nd) {
                                if (dist[nx][ny][ns] > nd) {
                                    dist[nx][ny][ns] = nd;
                                    dq.addLast(new State(nx, ny, ns, nd));
                                }
                                num[nx][ny][ns] = (num[nx][ny][ns] + ways(num[x][y][side], r50, t50, r100, t100)) % MOD;
                            }
                        }
                    }
                }
            }

            if (dist[cnt50][cnt100][1] == INF) {
                out.println(-1);
            } else {
                out.println(dist[cnt50][cnt100][1]);
            }
            out.println(num[cnt50][cnt100][1]);
        }

        static class State {
            int x, y, side;
            long d;
            State(int x, int y, int side, long d) {
                this.x = x;
                this.y = y;
                this.side = side;
                this.d = d;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int ptr = 0, len = 0;

        InputReader(InputStream in) { this.in = in; }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int val = 0, sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            for (; '0' <= c && c <= '9'; c = read()) val = val * 10 + c - '0';
            return val * sign;
        }
    }
}

