    public static void main(String[] args) {
        new Rock_Paper_Scissors().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        int n = in.nextInt();
        long[] a = in.readLongArray(3);
        long[] b = in.readLongArray(3);

        long max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        long min = Math.max(0, a[0] - b[0] - b[2]) + Math.max(0, a[1] - b[0] - b[1]) + Math.max(0, a[2] - b[1] - b[2]);

        System.out.println(min + " " + max);
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public long[] readLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) arr[i] = nextLong();
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

public class Rock_Paper_Scissors {
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] tokens = br.readLine().trim().split("\\s+");
            int n = Integer.parseInt(tokens[0]);
            long[] a = parseLongArray(br.readLine());
            long[] b = parseLongArray(br.readLine());

            long max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            long min = Math.max(0, a[0] - b[0] - b[2]) + Math.max(0, a[1] - b[0] - b[1]) + Math.max(0, a[2] - b[1] - b[2]);

            System.out.println(min + " " + max);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static long[] parseLongArray(String line) {
        String[] tokens = line.trim().split("\\s+");
        long[] arr = new long[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            arr[i] = Long.parseLong(tokens[i]);
        }
        return arr;
    }
}

