import java.io.*;
import java.util.*;

public class first {
    private static final PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    private BufferedReader in;
    private StringTokenizer tok;

    public int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public void go() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        String test = in.readLine();
        if (test == null || test.trim().isEmpty()) return;

        tok = new StringTokenizer(test);
        int tt = Integer.parseInt(tok.nextToken());
        ntok();
        int n = tt;
        int[] a = iapar(3);
        ntok();
        int[] b = iapar(3);

        int alicemax = 0, bobmax = 0;

        // Alice's score calculation
        if (a[0] != 0) alicemax += Math.min(a[0], b[1]);
        if (a[1] != 0) alicemax += Math.min(a[1], b[2]);
        if (a[2] != 0) alicemax += Math.min(a[2], b[0]);

        // Bob's score calculation with resource updates
        if (b[0] != 0) {
            int use1 = Math.min(b[0], a[1]);
            bobmax += use1;
            b[0] -= use1;
            if (b[0] != 0) bobmax += Math.min(b[0], a[0]);
        }
        if (b[1] != 0) {
            int use2 = Math.min(b[1], a[2]);
            bobmax += use2;
            b[1] -= use2;
            if (b[1] != 0) bobmax += Math.min(b[1], a[1]);
        }
        if (b[2] != 0) {
            int use3 = Math.min(b[2], a[0]);
            bobmax += use3;
            b[2] -= use3;
            if (b[2] != 0) bobmax += Math.min(b[2], a[2]);
        }

        System.out.println((n - bobmax) + " " + alicemax);
        out.flush();
        in.close();
    }

    public void ntok() throws IOException {
        String line = in.readLine();
        if (line == null || line.trim().isEmpty()) return;
        tok = new StringTokenizer(line);
    }

    public int ipar() {
        return tok.hasMoreTokens() ? Integer.parseInt(tok.nextToken()) : 0;
    }

    public int[] iapar(int n) {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = ipar();
        return arr;
    }

    public long lpar() {
        return tok.hasMoreTokens() ? Long.parseLong(tok.nextToken()) : 0L;
    }

    public long[] lapar(int n) {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) arr[i] = lpar();
        return arr;
    }

    public double dpar() {
        return Double.parseDouble(tok.nextToken());
    }

    public String spar() {
        return tok.hasMoreTokens() ? tok.nextToken() : "";
    }

    public static void main(String[] args) throws IOException {
        new first().go();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class GameScoreCalculator {
    private BufferedReader reader;
    private StringTokenizer tokenizer;
    private static final PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public int computeGCD(int x, int y) {
        return y == 0 ? x : computeGCD(y, x % y);
    }

    public void execute() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) return;

        tokenizer = new StringTokenizer(line);
        int testCaseCount = Integer.parseInt(tokenizer.nextToken());
        nextLine();
        int totalRounds = testCaseCount;
        int[] aliceResources = readIntArray(3);
        nextLine();
        int[] bobResources = readIntArray(3);

        int aliceScore = 0;
        int bobScore = 0;

        // Alice's scoring logic
        aliceScore += (aliceResources[0] > 0) ? Math.min(aliceResources[0], bobResources[1]) : 0;
        aliceScore += (aliceResources[1] > 0) ? Math.min(aliceResources[1], bobResources[2]) : 0;
        aliceScore += (aliceResources[2] > 0) ? Math.min(aliceResources[2], bobResources[0]) : 0;

        // Bob's scoring logic with resource consumption
        if (bobResources[0] > 0) {
            int consumed1 = Math.min(bobResources[0], aliceResources[1]);
            bobScore += consumed1;
            bobResources[0] -= consumed1;
            if (bobResources[0] > 0) {
                bobScore += Math.min(bobResources[0], aliceResources[0]);
            }
        }
        if (bobResources[1] > 0) {
            int consumed2 = Math.min(bobResources[1], aliceResources[2]);
            bobScore += consumed2;
            bobResources[1] -= consumed2;
            if (bobResources[1] > 0) {
                bobScore += Math.min(bobResources[1], aliceResources[1]);
            }
        }
        if (bobResources[2] > 0) {
            int consumed3 = Math.min(bobResources[2], aliceResources[0]);
            bobScore += consumed3;
            bobResources[2] -= consumed3;
            if (bobResources[2] > 0) {
                bobScore += Math.min(bobResources[2], aliceResources[2]);
            }
        }

        System.out.println((totalRounds - bobScore) + " " + aliceScore);
        writer.flush();
        reader.close();
    }

    private void nextLine() throws IOException {
        String line = reader.readLine();
        if (line != null && !line.trim().isEmpty()) {
            tokenizer = new StringTokenizer(line);
        }
    }

    private int readToken() {
        return tokenizer.hasMoreTokens() ? Integer.parseInt(tokenizer.nextToken()) : 0;
    }

    private int[] readIntArray(int size) {
        return IntStream.range(0, size).map(i -> readToken()).toArray();
    }

    private long readLongToken() {
        return tokenizer.hasMoreTokens() ? Long.parseLong(tokenizer.nextToken()) : 0L;
    }

    private long[] readLongArray(int size) {
        return IntStream.range(0, size).mapToLong(i -> readLongToken()).toArray();
    }

    private double readDoubleToken() {
        return Double.parseDouble(tokenizer.nextToken());
    }

    private String readStringToken() {
        return tokenizer.hasMoreTokens() ? tokenizer.nextToken() : "";
    }

    public static void main(String[] args) throws IOException {
        new GameScoreCalculator().execute();
    }
}

