import java.io.*;
import java.util.*;
import java.util.function.IntSupplier;

public class Solution {
    private static BufferedReader reader;
    private static StringTokenizer tokenizer;
    private static final PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        new Solution().run();
        writer.flush();
        reader.close();
    }

    private void run() throws IOException {
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) return;

        tokenizer = new StringTokenizer(line);
        int rounds = Integer.parseInt(tokenizer.nextToken());
        skipLine();
        int[] alice = readArray(3);
        skipLine();
        int[] bob = readArray(3);

        int aliceScore = 0;
        int bobScore = 0;

        // Alice's scoring
        aliceScore += (alice[0] > 0) ? Math.min(alice[0], bob[1]) : 0;
        aliceScore += (alice[1] > 0) ? Math.min(alice[1], bob[2]) : 0;
        aliceScore += (alice[2] > 0) ? Math.min(alice[2], bob[0]) : 0;

        // Bob's scoring with resource updates
        if (bob[0] > 0) {
            int used = Math.min(bob[0], alice[1]);
            bobScore += used;
            bob[0] -= used;
            if (bob[0] > 0) bobScore += Math.min(bob[0], alice[0]);
        }
        if (bob[1] > 0) {
            int used = Math.min(bob[1], alice[2]);
            bobScore += used;
            bob[1] -= used;
            if (bob[1] > 0) bobScore += Math.min(bob[1], alice[1]);
        }
        if (bob[2] > 0) {
            int used = Math.min(bob[2], alice[0]);
            bobScore += used;
            bob[2] -= used;
            if (bob[2] > 0) bobScore += Math.min(bob[2], alice[2]);
        }

        System.out.println((rounds - bobScore) + " " + aliceScore);
    }

    private void skipLine() throws IOException {
        String line = reader.readLine();
        if (line != null && !line.trim().isEmpty()) {
            tokenizer = new StringTokenizer(line);
        }
    }

    private int readInt() {
        return tokenizer.hasMoreTokens() ? Integer.parseInt(tokenizer.nextToken()) : 0;
    }

    private int[] readArray(int size) {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) arr[i] = readInt();
        return arr;
    }

    private long readLong() {
        return tokenizer.hasMoreTokens() ? Long.parseLong(tokenizer.nextToken()) : 0L;
    }

    private long[] readLongArray(int size) {
        long[] arr = new long[size];
        for (int i = 0; i < size; i++) arr[i] = readLong();
        return arr;
    }

    private double readDouble() {
        return Double.parseDouble(tokenizer.nextToken());
    }

    private String readString() {
