import java.io.*;
import java.util.*;

public class Main {
    private static BufferedReader in;
    private static StringTokenizer st;
    private static final PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        new Main().solve();
        out.flush();
        in.close();
    }

    private void solve() throws IOException {
        String line = in.readLine();
        if (line == null || line.trim().isEmpty()) return;

        st = new StringTokenizer(line);
        int T = Integer.parseInt(st.nextToken());
        nextLine();
        int N = T;
        int[] A = readInts(3);
        nextLine();
        int[] B = readInts(3);

        int alice = 0;
        int bob = 0;

        // Alice's points
        if (A[0] > 0) alice += Math.min(A[0], B[1]);
        if (A[1] > 0) alice += Math.min(A[1], B[2]);
        if (A[2] > 0) alice += Math.min(A[2], B[0]);

        // Bob's points with resource updates
        if (B[0] > 0) {
            int use = Math.min(B[0], A[1]);
            bob += use;
            B[0] -= use;
            if (B[0] > 0) bob += Math.min(B[0], A[0]);
        }
        if (B[1] > 0) {
            int use = Math.min(B[1], A[2]);
            bob += use;
            B[1] -= use;
            if (B[1] > 0) bob += Math.min(B[1], A[1]);
        }
        if (B[2] > 0) {
            int use = Math.min(B[2], A[0]);
            bob += use;
            B[2] -= use;
            if (B[2] > 0) bob += Math.min(B[2], A[2]);
        }

        System.out.println((N - bob) + " " + alice);
    }

    private static void nextLine() throws IOException {
        String line = in.readLine();
        if (line != null && !line.trim().isEmpty()) {
            st = new StringTokenizer(line);
        }
    }

    private static int nextInt() {
        return st.hasMoreTokens() ? Integer.parseInt(st.nextToken()) : 0;
    }

    private static int[] readInts(int n) {
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = nextInt();
        return res;
    }

    private static long nextLong() {
        return st.hasMoreTokens() ? Long.parseLong(st.nextToken()) : 0L;
    }

    private static long[] readLongs(int n) {
        long[] res = new long[n];
        for (int i = 0; i < n; i++) res[i] = nextLong();
        return res;
    }

    private static double nextDouble() {
        return Double.parseDouble(st.nextToken());
    }

    private static String nextToken() {
        return st.hasMoreTokens() ? st.nextToken() : "";
    }
}

