    static int bsearch(List<Long> list,long val,int ind)
    {
        int l=ind,r=list.size()-1;
        int res=list.size();

        while(l<=r)
        {
            int mid=(l+r)/2;
            if(list.get(mid)>val)
            {
                if(mid==0)
                {
                    return mid;
                }
                if(list.get(mid-1)<=val)
                {
                    return mid;
                }
                r=mid-1;
            }
            else
            {
                l=mid+1;
            }
        }
        return res;

    }

