        long min1 = Math.min(first.val, b[bInd]);
        first.val -= min1;
        b[bInd] -= min1;


        long min2 = Math.min(first.val, b[first.ind]);
        first.val -= min2;
        b[first.ind] -= min2;
        long sum = first.val;
        sum+=calc(list,b,i+1);
        first.val+=min1+min2;
        b[bInd]+=min1;
        b[first.ind]+=min2;



