public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int n = Integer.parseInt(br.readLine().trim());
            String[] line1 = br.readLine().trim().split("\\s+");
            String[] line2 = br.readLine().trim().split("\\s+");

            int[] a = new int[]{Integer.parseInt(line1[0]), Integer.parseInt(line1[1]), Integer.parseInt(line1[2])};
            int[] b = new int[]{Integer.parseInt(line2[0]), Integer.parseInt(line2[1]), Integer.parseInt(line2[2])};

            int max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            int min = Integer.MAX_VALUE;

            List<int[]> moves = new ArrayList<>();
            moves.add(new int[]{0, 0});
            moves.add(new int[]{1, 1});
            moves.add(new int[]{2, 2});
            moves.add(new int[]{0, 2});
            moves.add(new int[]{1, 0});
            moves.add(new int[]{2, 1});

            min = computeMin(a.clone(), b.clone(), moves, 0);
            pw.println(min + " " + max);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private int computeMin(int[] a, int[] b, List<int[]> moves, int idx) {
        if (idx == moves.size()) {
            return a[0] + a[1] + a[2];
        }

        int[] move = moves.get(idx);
