import java.util.*;

public class E {
    private static final FastWriter out = new FastWriter();
    private static FastScanner in;

    void solver() throws IOException {
        long n = in.intNext();
        long[] a = in.nextLongArray(3);
        long[] b = in.nextLongArray(3);
        long maxWins = 0;
        long maxDrawsOrLosses = 0;

        for (int i = 0; i < 3; i++) {
            maxWins += Math.min(a[i], b[(i + 1) % 3]);
            long potentialLoss = Math.min(b[i], a[(i + 1) % 3]);
            long potentialDraw = Math.min(b[i], a[i]);
            maxDrawsOrLosses += Math.min(b[i], potentialLoss + potentialDraw);
        }

        out.pp(n - maxDrawsOrLosses, maxWins);
    }

    public static void main(String[] args) throws IOException {
        in = new FastScanner();
        new E().solver();
        out.close();
    }

    static class FastWriter {
        private final StringBuilder buffer = new StringBuilder(128 * 1024);

        public FastWriter p(Object o) { buffer.append(o); return this; }
        public FastWriter pp(Object... items) { 
            for (Object item : items) { buffer.append(item).append(" "); }
            buffer.append("\n"); 
            return this; 
        }
        public FastWriter pp(long[] arr) {
            for (long v : arr) { buffer.append(v).append(" "); }
            buffer.append("\n");
            return this;
        }
        public void close() throws IOException { System.out.print(buffer); }
    }

    static class FastScanner {
        private final InputStream input = System.in;
        private final byte[] buf = new byte[1024];
        private int ptr = 0, len = 0;

        private boolean hasByte() {
            if (ptr >= len) {
                ptr = 0;
                try { len = input.read(buf); } catch (IOException e) { e.printStackTrace(); }
                if (len <= 0) return false;
            }
            return true;
        }

        private int nextByte() { return hasByte() ? buf[ptr++] : -1; }

        private boolean isPrintable(int c) { return c >= 33 && c <= 126; }

        public boolean hasNext() {
            while (hasByte() && !isPrintable(buf[ptr])) ptr++;
            return hasByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int c = nextByte();
            while (isPrintable(c)) {
                sb.appendCodePoint(c);
                c = nextByte();
            }
            return sb.toString();
        }

        public long longNext() {
            if (!hasNext()) throw new NoSuchElementException();
            long num = 0;
            boolean negative = false;
            int c = nextByte();
            if (c == '-') { negative = true; c = nextByte(); }
            if (c < '0' || c > '9') throw new NumberFormatException();
            while (true) {
                if (c >= '0' && c <= '9') {
                    num = num * 10 + (c - '0');
                } else if (c == -1 || !isPrintable(c) || c == ':') {
                    return negative ? -num : num;
                } else {
                    throw new NumberFormatException();
                }
                c = nextByte();
            }
        }

        public int intNext() {
            long val = longNext();
            if (val < Integer.MIN_VALUE || val > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) val;
        }

        public long[] nextLongArray(int size) {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++) arr[i] = longNext();
            return arr;
        }

        public int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) arr[i] = intNext();
            return arr;
        }
    }

    private static long min(long... nums) {
        long m = nums[0];
        for (long n : nums) if (n < m) m = n;
        return m;
    }

    private static int min(int... nums) {
        int m = nums[0];
        for (int n : nums) if (n < m) m = n;
        return m;
    }

    private static long max(long... nums) {
        long m = nums[0];
        for (long n : nums) if (n > m) m = n;
        return m;
    }
}

