            arrB[i] = Long.parseLong(partsB[i]);
        }

        long victories = 0L;
        long nonVictories = 0L;

        for (int i = 0; i < 3; ++i) {
            victories += Math.min(arrA[i], arrB[(i + 1) % 3]);
            long tempLoss = Math.min(arrB[i], arrA[(i + 1) % 3]);
            long tempDraw = Math.min(arrB[i], arrA[i]);
            nonVictories += Math.min(arrB[i], tempLoss + tempDraw);
        }

        pw.println((n - nonVictories) + " " + victories);
    }

