            long potentialDraw = Math.min(opp[i], me[i]);
            nonWinningMoves += Math.min(opp[i], potentialLoss + potentialDraw);
        }

        System.out.println((totalRounds - nonWinningMoves) + " " + winningMoves);
    }

    public static void main(String[] args) throws IOException {
        new E().process();
    }
}

import java.io.*;
import java.util.*;

public class E {
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1 << 16];
        private int curChar, numChars;

        InputReader(InputStream s) { stream = s; }

        private int read() throws IOException {
            if (numChars == -1) throw new IOException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buf);
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        long nextLong() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new IOException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        int nextInt() throws IOException { return (int) nextLong(); }

        private boolean isSpaceChar(int c) { return c <= 32 || c == 127; }
    }

    void execute() throws IOException {
        InputReader in = new InputReader(System.in);
        long n = in.nextLong();
        long[] first = new long[3];
        long[] second = new long[3];

        for (int i = 0; i < 3; ++i) first[i] = in.nextLong();
        for (int i = 0; i < 3; ++i) second[i] = in.nextLong();

        long wins = 0;
        long lossesOrDraws = 0;

        for (int i = 0; i < 3; ++i) {
            wins += Math.min(first[i], second[(i + 1) % 3]);
            long potentialLoss = Math.min(second[i], first[(i + 1) % 3]);
            long potentialDraw = Math.min(second[i], first[i]);
            lossesOrDraws += Math.min(second[i], potentialLoss + potentialDraw);
        }

        System.out.println((n - lossesOrDraws) + " " + wins);
    }

    public static void main(String[] args) throws IOException {
        new E().execute();
    }
}

