            Arrays.sort(arr);
        }

        public static int[] shuffle(int[] arr) {
            Random rnd = new Random();
            for (int i = arr.length - 1; i > 0; i--) {
                int j = rnd.nextInt(i + 1);
                int tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
            }
            return arr;
        }
    }
