    long dfs(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (best <= 1 || diff - C[v1][r] * C[v2][r] >= best) return -1;
        if (v1 == r-1 && v2 == r-1) {
            best = Math.min(best, diff);
            return 1;
        }
        long res = 0;
        if (v1 >= r) {
            long c1 = C[v1][r] - C[v1-1][r], s2 = C[v2][r];
            res += dfs(x, y + c1*s2, v1-1, v2);
        }
        if (v2 >= r) {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2-1][r];
            res += dfs(x + s1*c2, y, v1, v2-1);
        }
        return res;
    }

    long memo(long x, long y, int v1, int v2) {
        long key = ((x * 31 + y) * 31 + v1) * 31 + v2;
        if (dp.containsKey(key)) return dp.get(key);
        long diff = Math.abs(x - y);
