        if (v1 > 0 && cur != 'B') {
            long c1 = C[v1][r] - C[v1-1][r], s2 = C[v2][r];
            count += memo(x, y + c1*s2, v1-1, v2);
        }
        if (v2 > 0 && cur != 'A') {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2-1][r];
            count += memo(x + s1*c2, y, v1, v2-1);
        }
        dp.put(key, count);
        return count;
    }

    void start() {
