public class Algo {
    private static class IO {
        BufferedReader reader;
        StringTokenizer tokenizer;
        IO() { reader = new BufferedReader(new InputStreamReader(System.in)); }
        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) { e.printStackTrace(); }
            return tokenizer.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }

    int rows, cols;
    long[][] C = new long[130][130];
    long minDiff = Long.MAX_VALUE;
    char[] seq;
    int[] cntsA = new int[130], cntsB = new int[130];
    Map<Long, Long> mem = new HashMap<>();

    void populateC() {
        for (int i = 0; i < 130; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = C[i-1][j-1] + C[i-1][j];
            }
        }
    }

    long tracePath(long a, long b, int pa, int pb) {
        long diff = Math.abs(a - b);
        if (minDiff <= 1 || diff - C[pa][rows] * C[pb][rows] >= minDiff) return 0;
        if (pa == rows-1 && pb == rows-1) {
            minDiff = Math.min(minDiff, diff);
            return 1;
        }
        long sum = 0;
        if (pa >= rows) {
            long dA = C[pa][rows] - C[pa-1][rows], dB = C[pb][rows];
            sum += tracePath(a, b + dA*dB, pa-1, pb);
        }
        if (pb >= rows) {
            long dA = C[pa][rows], dB = C[pb][rows] - C[pb-1][rows];
            sum += tracePath(a + dA*dB, b, pa, pb-1);
        }
        return sum;
    }

    long explore(long a, long b, int pa, int pb) {
        long state = (a * 1000007L + b) * 1000033L + pa * 1009L + pb;
        if (mem.containsKey(state)) return mem.get(state);
        long diff = Math.abs(a - b);
        if (diff - C[pa][rows]*C[pb][rows] > minDiff) {
            mem.put(state, 0L);
            return 0;
        }
        if (pa == 0 && pb == 0) return 1;
        char token = seq[pa + pb - 1];
        long total = 0;
        if (pa > 0 && token != 'B') {
            long dA = C[pa][rows] - C[pa-1][rows], dB = C[pb][rows];
            total += explore(a, b + dA*dB, pa-1, pb);
        }
        if (pb > 0 && token != 'A') {
            long dA = C[pa][rows], dB = C[pb][rows] - C[pb-1][rows];
            total += explore(a + dA*dB, b, pa, pb-1);
        }
        mem.put(state, total);
        return total;
    }

    void process() {
        IO io = new IO();
        rows = io.nextInt(); cols = io.nextInt();
        try {
            seq = io.reader.readLine().toCharArray();
        } catch (IOException e) { seq = new char[0]; }
        populateC();
        int i = rows + cols, j = rows + cols;
        long A = 0, B = 0;
        while (i >= rows && j >= rows) {
            if (A > B) {
                long dA = C[i][rows] - C[i-1][rows], dB = C[j][rows];
                B += dA * dB;
                i--;
            } else {
                long dA = C[i][rows], dB = C[j][rows] - C[j-1][rows];
                A += dA * dB;
                j--;
            }
        }
        minDiff = Math.abs(A - B);
        tracePath(0, 0, rows + cols, rows + cols);
        for (int k = 0; k < 2*(rows + cols); k++) {
            cntsA[k+1] = cntsA[k] + (seq[k] == 'A' ? 1 : 0);
            cntsB[k+1] = cntsB[k] + (seq[k] == 'B' ? 1 : 0);
        }
        long total = explore(0, 0, rows + cols, rows + cols);
        System.out.println(total);
    }

    public static void main(String[] args) {
        new Algo().process();
    }
}

import java.io.*;
