public class Main {
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;
        public FastScanner() { br = new BufferedReader(new InputStreamReader(System.in)); }
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try { st = new StringTokenizer(br.readLine()); }
                catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        private int nextInt() { return Integer.parseInt(next()); }
    }

    private int r, c;
    private long[][] binomial = new long[130][130];
    private long minimalDifference = Long.MAX_VALUE;
    private char[] sequence;
    private int[] freqA = new int[130], freqB = new int[130];
    private Map<Long, Long> memoization = new HashMap<>();

    private void precompute() {
        for (int i = 0; i < 130; ++i) {
            binomial[i][0] = 1;
            for (int j = 1; j <= i; ++j)
                binomial[i][j] = binomial[i-1][j-1] + binomial[i-1][j];
        }
    }

    private long search(long leftVal, long rightVal, int leftIdx, int rightIdx) {
        long diff = Math.abs(leftVal - rightVal);
        if (minimalDifference <= 1 || diff - binomial[leftIdx][r] * binomial[rightIdx][r] >= minimalDifference)
            return 0;
        if (leftIdx == r-1 && rightIdx == r-1) {
            minimalDifference = Math.min(minimalDifference, diff);
            return 1;
        }
        long count = 0;
        if (leftIdx >= r) {
            long deltaL = binomial[leftIdx][r] - binomial[leftIdx-1][r];
            long sumR = binomial[rightIdx][r];
            count += search(leftVal, rightVal + deltaL * sumR, leftIdx-1, rightIdx);
        }
        if (rightIdx >= r) {
            long sumL = binomial[leftIdx][r];
            long deltaR = binomial[rightIdx][r] - binomial[rightIdx-1][r];
            count += search(leftVal + sumL * deltaR, rightVal, leftIdx, rightIdx-1);
        }
        return count;
    }

    private long countWays(long leftVal, long rightVal, int leftIdx, int rightIdx) {
        long key = (leftVal << 22) ^ (rightVal << 11) ^ (leftIdx << 6) ^ rightIdx;
        if (memoization.containsKey(key)) return memoization.get(key);
        long diff = Math.abs(leftVal - rightVal);
        if (diff - binomial[leftIdx][r] * binomial[rightIdx][r] > minimalDifference) {
            memoization.put(key, 0L);
            return 0;
        }
        if (leftIdx == 0 && rightIdx == 0) return 1;
        char action = sequence[leftIdx + rightIdx - 1];
        long total = 0;
        if (leftIdx > 0 && action != 'B') {
            long deltaL = binomial[leftIdx][r] - binomial[leftIdx-1][r];
            long sumR = binomial[rightIdx][r];
            total += countWays(leftVal, rightVal + deltaL * sumR, leftIdx-1, rightIdx);
        }
        if (rightIdx > 0 && action != 'A') {
            long sumL = binomial[leftIdx][r];
            long deltaR = binomial[rightIdx][r] - binomial[rightIdx-1][r];
            total += countWays(leftVal + sumL * deltaR, rightVal, leftIdx, rightIdx-1);
        }
        memoization.put(key, total);
        return total;
    }

    private void execute() {
        FastScanner fs = new FastScanner();
        r = fs.nextInt(); c = fs.nextInt();
        try { sequence = fs.br.readLine().toCharArray(); }
        catch (IOException e) { sequence = new char[0]; }
        precompute();
        int pa = r + c, pb = r + c;
        long l = 0, rt = 0;
        while (pa >= r && pb >= r) {
            if (l > rt) {
                long delta = binomial[pa][r] - binomial[pa-1][r], sum = binomial[pb][r];
                rt += delta * sum;
                pa--;
            } else {
                long sum = binomial[pa][r], delta = binomial[pb][r] - binomial[pb-1][r];
                l += sum * delta;
                pb--;
            }
        }
        minimalDifference = Math.abs(l - rt);
        search(0, 0, r + c, r + c);
        for (int i = 0; i < 2*(r+c); ++i) {
            freqA[i+1] = freqA[i] + (sequence[i] == 'A' ? 1 : 0);
            freqB[i+1] = freqB[i] + (sequence[i] == 'B' ? 1 : 0);
        }
        long result = countWays(0, 0, r + c, r + c);
        System.out.println(result);
    }

    public static void main(String[] args) {
        new Main().execute();
    }
}

