import java.io.*;
import java.util.*;
public class A
{
    private static ArrayList<Long> list, subsets;
    private static void allSubsets(int i, long sum)
    {
        if(i==list.size())
        {
            subsets.add(sum);
            return;
        }

        allSubsets(i+1,sum+list.get(i));
        allSubsets(i+1,sum);
    }
    private static boolean check(long M, long W, long x)
    {
        if(x==M) return true;

        boolean flag=true;
        x+=M;
        while (x>0)
        {
            if(x%W>1)
            {
                flag=false;
                break;
            }
            x/=W;
        }

        return flag;
    }
    public static void main(String[] args) throws Exception
    {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));

        int i,N;

        String[] s=br.readLine().trim().split(" ");
        long W=Long.parseLong(s[0]);
        long M=Long.parseLong(s[1]);

        if(W==2)
        {
            System.out.println("YES");
            System.exit(0);
        }

        list=new ArrayList<>();
        list.add(1L); list.add(W);

        long cur=W;
        final long MAX=(long)(1e10);

        while (true)
        {
            cur*=W;
            if(cur<0||cur>MAX) break;

            list.add(cur);
        }

        subsets = new ArrayList<>();
        allSubsets(0,0);

        boolean flag=false;
        for(long x: subsets)
        {
            flag |= check(M, W, x);
            if(flag) break;
        }

        System.out.println(flag?"YES":"NO");
    }
}

import java.io.*;
