public class A {
    private static List<Long> powerList;
    private static List<Long> subsetSumList;

    private static void computeSubsets(int idx, long acc) {
        if (idx == powerList.size()) {
            subsetSumList.add(acc);
            return;
        }
        computeSubsets(idx + 1, acc + powerList.get(idx));
        computeSubsets(idx + 1, acc);
    }

    private static boolean validate(long target, long base, long val) {
        if (val == target) return true;
        long temp = val + target;
        while (temp > 0) {
            if (temp % base > 1) return false;
            temp /= base;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = reader.readLine().trim().split("\\s+");
        long W = Long.parseLong(parts[0]);
        long M = Long.parseLong(parts[1]);

        if (W == 2) {
            System.out.println("YES");
            return;
        }

        powerList = new ArrayList<>();
        powerList.add(1L);
        powerList.add(W);
        long next = W;
        long cap = (long)1e10;

        for (;;) {
            next *= W;
            if (next <= 0 || next > cap) break;
            powerList.add(next);
        }

        subsetSumList = new ArrayList<>();
        computeSubsets(0, 0L);

        boolean success = false;
        for (long sum : subsetSumList) {
            if (validate(M, W, sum)) {
                success = true;
                break;
            }
        }

        System.out.println(success ? "YES" : "NO");
    }
}

