    private static void buildCombinations(int pos, long total) {
        if (pos == weights.size()) {
            combinations.add(total);
            return;
        }
        buildCombinations(pos + 1, total + weights.get(pos));
        buildCombinations(pos + 1, total);
    }

    private static boolean matches(long M, long W, long candidate) {
        if (candidate == M) return true;
        long n = candidate + M;
        while (n > 0) {
            if (n % W > 1) return false;
            n /= W;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
