        if (W == 2) {
            System.out.println("YES");
            return;
        }

        weights = new ArrayList<>();
        weights.add(1L);
        weights.add(W);
        long value = W;
        long upperBound = (long)1e10;

        while (true) {
            value *= W;
            if (value <= 0 || value > upperBound) break;
            weights.add(value);
        }

        combinations = new ArrayList<>();
        buildCombinations(0, 0L);

        boolean result = false;
        for (long c : combinations) {
            if (matches(M, W, c)) {
                result = true;
