public class A {
    private static List<Long> basePowers;
    private static List<Long> subsetTotals;

    private static void enumerateSubsets(int depth, long runningSum) {
        if (depth == basePowers.size()) {
            subsetTotals.add(runningSum);
            return;
        }
        enumerateSubsets(depth + 1, runningSum + basePowers.get(depth));
        enumerateSubsets(depth + 1, runningSum);
    }

    private static boolean satisfiesCondition(long M, long W, long trial) {
        if (trial == M) return true;
        long temp = trial + M;
        while (temp > 0) {
            if (temp % W > 1) return false;
            temp /= W;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader console = new BufferedReader(new InputStreamReader(System.in));
        String[] fields = console.readLine().trim().split(" ");
        long W = Long.parseLong(fields[0]);
