        if (W == 2) {
            System.out.println("YES");
            return;
        }

        basePowers = new ArrayList<>();
        basePowers.add(1L);
        basePowers.add(W);
        long power = W;
        long ceiling = (long)1e10;

        for (;;) {
            power *= W;
            if (power <= 0 || power > ceiling) break;
            basePowers.add(power);
        }

        subsetTotals = new ArrayList<>();
        enumerateSubsets(0, 0L);

        boolean matchFound = false;
        for (long t : subsetTotals) {
            if (satisfiesCondition(M, W, t)) {
                matchFound = true;
                break;
            }
        }

        System.out.println(matchFound ? "YES" : "NO");
    }
}

