    private boolean canRepresentIteratively(long W, long M) {
        while (M != 1) {
            if (M % W == 0) {
                M /= W;
            } else if ((M - 1) % W == 0) {
                M = (M - 1) / W;
            } else if ((M + 1) % W == 0) {
                M = (M + 1) / W;
            } else {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        new Main().solve();
    }

}

