class TaskC {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int w = in.nextInt(), m = in.nextInt(), n = 0;
        int[] a = new int[50];
        do {
            a[++n] = m % w;
            m /= w;
        } while (m > 0);

        boolean ok = true;
        for(int i = 1; i <= n;)
            if (a[i] > 1) {
                a[i] += 1;
                if (a[i] == w) {
                    while (i <= n && a[i] >= w) {
                        a[i] = 0;
                        a[++i] += 1;
                    }
                }
                else ++i;
                if (a[i-1] > 1) {
                    ok = false; break;
                }
            } else ++i;
        if (ok) out.print("YES"); else out.print("NO");
    }
}

