         while (m > 0) {

            nr++; t[nr] = m % w;

            m = m / w;

         }

         for (int i = 1; i <= nr; i++)
            if (t[i] > w / 2) {

               t[i] = - (t[i] - w);

               t[i + 1] ++;


            }

