import java.math.BigInteger;
import java.util.Scanner;

public class Main {
    private static int weight;
    private static int itemMass;
    private static final boolean[] used = new boolean[100];

    static {
        for (int i = 0; i < 100; i++) {
            used[i] = false;
        }
    }

    public boolean isBalanced() {
        long left = itemMass;
        long right = 0;

        while (true) {
            if (left > right) {
                long diff = left - right;
                long next = findWeight(diff);
                if (next == 0) break;
                right += next;
            } else if (right > left) {
                long diff = right - left;
                long next = findWeight(diff);
                if (next == 0) break;
                left += next;
            } else {
                return true;
            }
        }
        return false;
    }

    private long findWeight(long target) {
        if (target <= 0) return 0;

        int exponent = (int) (Math.log(target) / Math.log(weight));
        BigInteger base = BigInteger.valueOf(weight);
        BigInteger total = base.pow(exponent + 1).subtract(BigInteger.ONE).divide(BigInteger.valueOf(weight - 1));
        long totalLong = total.longValue();

        if (target > totalLong && !used[exponent + 1]) {
            used[exponent + 1] = true;
            return (long) Math.pow(weight, exponent + 1);
        } else if (target <= totalLong && !used[exponent]) {
            used[exponent] = true;
            return (long) Math.pow(weight, exponent);
        } else {
            return 0;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        weight = scanner.nextInt();
        itemMass = scanner.nextInt();
        Main solver = new Main();
        System.out.println(solver.isBalanced() ? "YES" : "NO");
    }
}

