public class Main {
    private static int weight;
    private static int itemMass;
    private static final boolean[] used = new boolean[100];

    static {
        java.util.Arrays.fill(used, false);
    }

    public boolean isBalanced() {
        long left = itemMass;
        long right = 0;

        for (int iteration = 0; iteration < 200; iteration++) {
            if (left == right) return true;
            if (left > right) {
                long diff = left - right;
                long candidate = getWeightFor(diff);
                if (candidate == 0) break;
                right += candidate;
            } else {
                long diff = right - left;
                long candidate = getWeightFor(diff);
                if (candidate == 0) break;
                left += candidate;
            }
        }
        return false;
    }

    private long getWeightFor(long target) {
        if (target <= 0) return 0;

        int k = (int) (Math.log(target) / Math.log(weight));
        BigInteger w = BigInteger.valueOf(weight);
        BigInteger sum = w.pow(k + 1).subtract(BigInteger.ONE).divide(w.subtract(BigInteger.ONE));
        long sumVal = sum.longValue();

        if (target > sumVal && !used[k + 1]) {
            used[k + 1] = true;
            return (long) Math.pow(weight, k + 1);
        } else if (target <= sumVal && !used[k]) {
            used[k] = true;
            return (long) Math.pow(weight, k);
        }
        return 0;
    }

    public static void main(String[] args) {
