    private long getWeight(long target) {
        if (target <= 0) return 0;

        int k = (int) (Math.log(target) / Math.log(weight));
        BigInteger w = BigInteger.valueOf(weight);
        BigInteger total = w.pow(k + 1).subtract(BigInteger.ONE).divide(w.subtract(BigInteger.ONE));
        long totalVal = total.longValue();

        if (target > totalVal && !used[k + 1]) {
            used[k + 1] = true;
            return (long) Math.pow(weight, k + 1);
        } else if (!used[k]) {
            used[k] = true;
            return (long) Math.pow(weight, k);
        }
        return 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        weight = sc.nextInt();
        itemMass = sc.nextInt();
        Main solver = new Main();
        System.out.println(solver.isBalanced() ? "YES" : "NO");
    }
}

