    static class TaskC {
        private boolean canBalance(long w, long m) {
            long[] powers = new long[105];
            long[] prefixSums = new long[105];
            long p = 1;
            int maxIdx = 0;

            for (int i = 0; i < 100; i++) {
                powers[i] = p;
                prefixSums[i + 1] = p + prefixSums[i];
                p *= w;
                if (p > (1L << 40)) {
                    maxIdx = i;
                    break;
                }
            }

            boolean[] result = {false};
            dfs(0, m, maxIdx, powers, prefixSums, result);
            return result[0];
        }

        private void dfs(long current, long target, int pos, long[] powers, long[] prefixSums, boolean[] found) {
            if (found[0]) return;
            if (current == target) {
                found[0] = true;
                return;
            }

            long remaining = prefixSums[pos + 1];
            long nextPower = powers[pos];

            if (current - remaining > target || current + remaining < target) {
                return;
            }

            if (current + prefixSums[pos] < target) {
                dfs(current + nextPower, target, pos - 1, powers, prefixSums, found);
            } else if (current - prefixSums[pos] > target) {
                dfs(current - nextPower, target, pos - 1, powers, prefixSums, found);
            } else {
                dfs(current, target, pos - 1, powers, prefixSums, found);
            }
        }
    }
