        TaskC solver = new TaskC();
        System.out.println(solver.check(w, m) ? "YES" : "NO");
    }

    static class TaskC {
        public boolean check(long w, long m) {
            long[] pows = new long[105];
            long[] pre = new long[105];
            long power = 1;
            int limit = 0;

            for (int i = 0; i < 100; i++) {
                pows[i] = power;
                pre[i + 1] = power + pre[i];
                power *= w;
                if (power > (1L << 40)) {
                    limit = i;
                    break;
                }
            }

            return search(0, m, limit, pows, pre);
        }

        private boolean search(long val, long goal, int idx, long[] pows, long[] pre) {
            if (val == goal) return true;
            if (idx < 0) return false;

            long maxReach = pre[idx + 1];
            long nextVal = pows[idx];

            if (val - maxReach > goal || val + maxReach < goal) {
                return false;
            }

            if (val + pre[idx] < goal) {
                return search(val + nextVal, goal, idx - 1, pows, pre);
            } else if (val - pre[idx] > goal) {
                return search(val - nextVal, goal, idx - 1, pows, pre);
            } else {
                return search(val, goal, idx - 1, pows, pre);
            }
        }
    }
}

