public class vanyaandscale_variant1 {
    static long[] powers;
    static boolean found;
    static int powerCount;
    static long leftBalance, rightBalance;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long limit = 100_000_000_000L;

        powers = new long[40];
        powers[0] = 1;
        int idx = 1;
        long current = 1;

        if (w <= 3) {
            System.out.println("YES");
            return;
        }

        for (int i = 1; i < 16; i++) {
            current *= w;
            if (current > limit) break;
            powers[idx++] = current;
        }
        powerCount = idx;

        leftBalance = 0;
        rightBalance = m;
        found = false;
        search(0);
        System.out.println(found ? "YES" : "NO");
    }

    static void search(int depth) {
        if (found) return;
        if (depth == powerCount) {
            found = (leftBalance == rightBalance);
            return;
        }

        // Option 0: skip current weight
        search(depth + 1);

        // Option 1: put weight on left side
        leftBalance += powers[depth];
        search(depth + 1);
        leftBalance -= powers[depth];

        // Option 2: put weight on right side
        rightBalance += powers[depth];
        search(depth + 1);
        rightBalance -= powers[depth];
    }
}

