public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long w = sc.nextLong();
        long m = sc.nextLong();
        System.out.println(solve(w, m) ? "YES" : "NO");
    }

    static boolean solve(long w, long m) {
        if (w <= 3) return true;
        if (m == 1) return true;

        for (long k = m - 1; k <= m + 1; k++) {
            if (k % w == 0 && solve(w, k / w)) {
                return true;
            }
        }
        return false;
    }
}

