public class BalancedWeights {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split("\\s+");
        long w = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);

        System.out.println(isPossible(w, m) ? "YES" : "NO");
    }

    static boolean isPossible(long w, long m) {
        if (w <= 3 || m == 1) return true;

        for (long offset = -1; offset <= 1; offset++) {
            long candidate = m + offset;
            if (candidate > 0 && candidate % w == 0) {
                if (isPossible(w, candidate / w)) {
                    return true;
                }
            }
        }
        return false;
    }
}

