        if (k >= n) {
            pw.println(0);
        } else {
            int r = (int)(n - k);
            long[] fact = new long[n + 1];
            long[] invFact = new long[n + 1];

            fact[0] = 1;
            invFact[0] = modInverse(fact[0], MOD);

            for (int i = 1; i <= n; i++) {
                fact[i] = (i * fact[i - 1]) % MOD;
                invFact[i] = modInverse(fact[i], MOD);
            }

            long sum = 0;
            for (int i = 1; i <= r; i++) {
                long binom = fact[r] * invFact[i] % MOD * invFact[r - i] % MOD;
                long term = binom * modPow(i, n) % MOD;
                if ((r - i) % 2 == 1) {
                    term = (MOD - term) % MOD;
                }
                sum = (sum + term) % MOD;
            }

            long result = sum * fact[n] % MOD * invFact[r] % MOD * invFact[n - r] % MOD;

            if (k == 0) {
                pw.println(result);
            } else {
                pw.println((2 * result) % MOD);
            }
        }
        pw.flush();
    }

    private long modPow(long base, long exp) {
        base %= MOD;
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private long modInverse(long a, long mod) {
        return modPow(a, mod - 2);
    }
}

