        int N = Integer.parseInt(input[0]);
        long K = Long.parseLong(input[1]);

        if (K >= N) {
            writer.println(0);
            writer.flush();
            return;
        }
        if (K == 0) {
            writer.println(fact[N]);
            writer.flush();
            return;
        }
        if (K == N - 1) {
            writer.println(2 * N);
            writer.flush();
            return;
        }

        int filled = N - (int)K;
        long colWays = comb(N, filled);

        long sum = 0;
        for (int empty = 0; empty <= filled; empty++) {
            long choose = comb(filled, empty);
            long fillWays = modExp(filled - empty, N);
            long term = (choose * fillWays) % MOD;
            if (empty % 2 == 1) term = (MOD - term) % MOD;
            sum = (sum + term) % MOD;
        }

        sum = (sum * colWays) % MOD;
        sum = (sum * 2) % MOD;

        writer.println(sum);
        writer.flush();
    }
}

