            pw.println(2 * n);
            pw.flush();
            return;
        }

        int filledCols = n - (int)k;
        long chooseCols = nCr(n, filledCols);

        long total = 0;
        for (int empty = 0; empty <= filledCols; empty++) {
            long choose = nCr(filledCols, empty);
            long fill = modPow(filledCols - empty, n);
            long term = (choose * fill) % MOD;
            if (empty % 2 == 1) term = (MOD - term) % MOD;
            total = (total + term) % MOD;
        }

        total = (total * chooseCols) % MOD;
        total = (total * 2) % MOD;

        pw.println(total);
        pw.flush();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long[] factorial;

    static long comb(int n, int r) {
        if (r < 0 || r > n) return 0;
        long numerator = factorial[n];
        long denominator = (factorial[n - r] * factorial[r]) % MOD;
        return (numerator * modPow(denominator, MOD - 2)) % MOD;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        factorial = new long[200001];
        factorial[0] = 1;
        for (int i = 1; i < factorial.length; i++) {
            factorial[i] = (factorial[i - 1] * i) % MOD;
        }

        String[] line = br.readLine().trim().split(" +");
        int n = Integer.parseInt(line[0]);
        long k = Long.parseLong(line[1]);

        if (k >= n) {
            pw.println(0);
            pw.flush();
            return;
        }
        if (k == 0) {
            pw.println(factorial[n]);
            pw.flush();
            return;
        }
        if (k == n - 1) {
            pw.println(2 * n);
            pw.flush();
            return;
        }

        int filled = n - (int)k;
        long colWays = comb(n, filled);

        long ans = 0;
        for (int empty = 0; empty <= filled; empty++) {
            long choose = comb(filled, empty);
            long fillWays = modPow(filled - empty, n);
            long term = (choose * fillWays) % MOD;
            if (empty % 2 == 1) {
                term = (MOD - term) % MOD;
            }
            ans = (ans + term) % MOD;
        }

        ans = (ans * colWays) % MOD;
        ans = (ans * 2) % MOD;

        pw.println(ans);
        pw.flush();
    }
}

