public class Solution {
    static final long MOD = 998244353L;
    static final int MAX_SIZE = 200005;
    static long[] fact = new long[MAX_SIZE];

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    static long modExp(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long comb(int n, int r) {
        if (r > n) return 0;
        return fact[n] * modExp(fact[r], MOD - 2, MOD) % MOD
                * modExp(fact[n - r], MOD - 2, MOD) % MOD;
    }

    static long calc(int n, int k) {
        long total = 0;
        for (int i = 0; i <= n - k; i++) {
            long term = comb(n - k, i) * modExp(n - k - i, n, MOD) % MOD;
            total = (i % 2 == 0) ? (total + term) % MOD : (total - term + MOD) % MOD;
        }
        return total;
    }

