public class E {
    static final long MOD = 998244353;
    static long[] factorial, invFactorial;

    public static void main(String[] args) {
        precompute();
        Scanner sc = new Scanner(System.in);
        try {
            int n = sc.nextInt();
            int k = sc.nextInt();
            if (k == 0) {
                System.out.println(factorial[n]);
                return;
            }
            if (k >= n) {
                System.out.println(0);
                return;
            }
            int usable = n - k;
            long assignments = inclusionExclusion(usable, n);
            long combinations = nCr(n, usable);
            long result = mul(assignments, combinations);
            System.out.println(mul(result, 2));
        } catch (Exception e) {
            System.out.println(0);
        }
    }

    static long inclusionExclusion(int base, long exp) {
        long result = 0;
        for (int i = 0; i < base; i++) {
            long term = mul(fastPow(base - i, exp), nCr(base, i));
            if (i % 2 == 0) {
                result = add(result, term);
            } else {
                result = sub(result, term);
            }
        }
        return result;
    }

    static void precompute() {
        factorial = new long[1_000_000];
        invFactorial = new long[1_000_000];
        factorial[0] = invFactorial[0] = 1;
        for (int i = 1; i < 1_000_000; i++) {
            factorial[i] = mul(factorial[i - 1], i);
        }
