      for(int i = (int)(n-k+1); i <= n; i++)
      {
         num = (num*i) % mod;
      } 
      for(int i = 1; i <= k; i++)
      {
         denom = (denom*i) % mod;
      } 
      denom = power(denom, mod-2) % mod;
      return (num*denom) % mod;
    } 
public static long power(long x, long y) 
{ 
    long res = 1;      
    x = x % mod;
    while (y > 0) 
    { 

        if (y % 2 == 1) 
        {    res = res*x; 
            res = res % mod;}

        y = y>>1;  
        x = x*x; 
        x = x % mod; 
    } 
    return res; 
}
}

