public class PIEFLAVORED_V1 {
    private static final long MOD = 998244353;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long kVal = scanner.nextLong();

        if (kVal >= n) {
            System.out.println(0);
            return;
        }

        int k = (int) kVal;
        int r = n - k;

        long[] rC = precomputeBinomialCoefficients(r);
        long result = 0;
        long sign = 1;

        for (int i = 0; i <= r; i++) {
            long term = power(r - i, n) * rC[i] % MOD;
            term = term * sign % MOD;
            result = (result + term) % MOD;
            sign = -sign;
        }

        result = result * binomial(n, k) % MOD;
        if (k > 0) {
            result = result * 2 % MOD;
        }

        result = (result % MOD + MOD) % MOD;
        System.out.println(result);
    }

    private static long[] precomputeBinomialCoefficients(int r) {
        long[] coeffs = new long[r + 1];
        coeffs[0] = 1;
        long numerator = 1;
        long denominator = 1;

        for (int i = 1; i <= r; i++) {
            numerator = numerator * (r - i + 1) % MOD;
            denominator = denominator * i % MOD;
            coeffs[i] = numerator * modInverse(denominator) % MOD;
        }

        return coeffs;
    }

    private static long binomial(long n, long k) {
        if (k < 0 || k > n) return 0;
        if (k == 0 || k == n) return 1;

        long num = 1;
        for (long i = n - k + 1; i <= n; i++) {
            num = num * i % MOD;
        }

        long denom = 1;
        for (long i = 1; i <= k; i++) {
            denom = denom * i % MOD;
        }

        return num * modInverse(denom) % MOD;
    }

    private static long modInverse(long a) {
        return power(a, MOD - 2);
    }

    private static long power(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

