        int m = in.nextInt();
        if (n > m) {
            int tmp = n;
            n = m;
            m = tmp;
        }

        int[][] dp = new int[1 << n][1 << n];
        fill(dp, INF);
        Arrays.fill(dp[0], 0);

        for (int col = 0; col < m; col++) {
            int[][] nextDp = new int[1 << n][1 << n];
            fill(nextDp, INF);
            int limit = (col == m - 1) ? 1 : (1 << n);

            for (int prev2 = 0; prev2 < (1 << n); prev2++) {
                for (int prev1 = 0; prev1 < (1 << n); prev1++) {
                    if (dp[prev2][prev1] == INF) continue;

                    for (int curr = 0; curr < limit; curr++) {
                        int covered = 0;
                        for (int row = 0; row < n; row++) {
                            if (((1 << row) & prev1) == 0) {
                                boolean upCovered = (row > 0 && ((1 << (row - 1)) & prev1) != 0);
                                boolean downCovered = (row < n - 1 && ((1 << (row + 1)) & prev1) != 0);
                                boolean leftCovered = (((1 << row) & prev2) != 0);
                                boolean rightCovered = (((1 << row) & curr) != 0);
                                if (upCovered || downCovered || leftCovered || rightCovered) {
                                    covered |= (1 << row);
                                }
                            }
                        }
                        int uncoveredCount = n - Integer.bitCount(covered);
                        nextDp[prev1][curr] = Math.min(nextDp[prev1][curr], dp[prev2][prev1] + uncoveredCount);
                    }
                }
            }
            dp = nextDp;
        }

        int maxCovered = INF;
        for (int i = 0; i < (1 << n); i++) {
            for (int j = 0; j < (1 << n); j++) {
                maxCovered = Math.min(maxCovered, dp[i][j]);
            }
        }

        System.out.println(n * m - maxCovered);
    }

    private static void fill(int[][] arr, int val) {
        for (int[] row : arr) {
            Arrays.fill(row, val);
        }
    }
}

