    int rows, cols, maskSize;
    int[] popcounts;
    int[][][] memo;

    void run() {
        rows = rd.nextInt();
        cols = rd.nextInt();
        if (rows < cols) {
            int temp = rows; rows = cols; cols = temp;
        }
        maskSize = 1 << cols;
        popcounts = new int[maskSize];
        memo = new int[rows][maskSize][maskSize];

        for (int[][] layer : memo) {
            for (int[] row : layer) {
                Arrays.fill(row, -1);
            }
        }

        for (int state = 0; state < maskSize; state++) {
