            memo[0][state][0] = popcounts[state];
        }

        int minSpiders = Integer.MAX_VALUE;
        for (int r = 0; r < rows - 1; r++) {
            for (int prevPrev = 0; prevPrev < maskSize; prevPrev++) {
                for (int prev = 0; prev < maskSize; prev++) {
                    if (memo[r][prevPrev][prev] == -1) continue;
                    for (int curr = 0; curr < maskSize; curr++) {
                        int coverage = ((prevPrev | ((prevPrev << 1) | (prevPrev >> 1)) | prev | curr) & (maskSize - 1));
                        if (coverage == (maskSize - 1)) {
                            int newValue = memo[r][prevPrev][prev] + popcounts[curr];
                            if (memo[r + 1][curr][prev] == -1 || newValue < memo[r + 1][curr][prev]) {
                                memo[r + 1][curr][prev] = newValue;
                            }
                        }
                    }
                }
            }
        }

        for (int lastPrev = 0; lastPrev < maskSize; lastPrev++) {
            for (int last = 0; last < maskSize; last++) {
                if (memo[rows - 1][lastPrev][last] != -1) {
                    int coverage = ((lastPrev | ((lastPrev << 1) | (lastPrev >> 1)) | last) & (maskSize - 1));
                    if (coverage == (maskSize - 1)) {
                        minSpiders = Math.min(minSpiders, memo[rows - 1][lastPrev][last]);
                    }
                }
