    static int debugCount = 0;

    static String readToken() {
        try {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        } catch (IOException ex) {
            ex.printStackTrace();
            return "";
        }
    }

    static int readInt() { return Integer.parseInt(readToken()); }
    static long readLong() { return Long.parseLong(readToken()); }
    static double readDouble() { return Double.parseDouble(readToken()); }
    static String readLine() {
        try { return br.readLine(); } catch (IOException e) { e.printStackTrace(); return ""; }
    }

    static void log(String s) {
        if (DEBUG_MODE && debugCount < 200) {
            pw.println(s);
            pw.flush();
            debugCount++;
        }
    }

    public static void main(String[] args) {
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        new Main().solve();
        pw.close();
    }

    int R, C, LIMIT;
    int[] bitCounts;
    int[][][] memoTable;

    void solve() {
        R = readInt();
        C = readInt();
        if (R < C) { int t = R; R = C; C = t; }

        LIMIT = 1 << C;
        bitCounts = new int[LIMIT];
        memoTable = new int[R][LIMIT][LIMIT];

        for (int[][] layer : memoTable)
            for (int[] row : layer)
                Arrays.fill(row, -1);

        for (int mask = 0; mask < LIMIT; mask++) {
            bitCounts[mask] = Integer.bitCount(mask);
            memoTable[0][mask][0] = bitCounts[mask];
        }

        int answer = Integer.MAX_VALUE;

        for (int row = 0; row < R - 1; row++) {
            for (int mask1 = 0; mask1 < LIMIT; mask1++) {
                for (int mask2 = 0; mask2 < LIMIT; mask2++) {
                    if (memoTable[row][mask1][mask2] == -1) continue;
                    for (int mask3 = 0; mask3 < LIMIT; mask3++) {
                        int covered = ((mask1 | (mask1 << 1) | (mask1 >> 1) | mask2 | mask3) & (LIMIT - 1));
                        if (covered == (LIMIT - 1)) {
                            int val = memoTable[row][mask1][mask2] + bitCounts[mask3];
                            if (memoTable[row + 1][mask3][mask2] == -1 || val < memoTable[row + 1][mask3][mask2])
                                memoTable[row + 1][mask3][mask2] = val;
                        }
                    }
                }
            }
        }

        for (int mask1 = 0; mask1 < LIMIT; mask1++) {
            for (int mask2 = 0; mask2 < LIMIT; mask2++) {
                if (memoTable[R - 1][mask1][mask2] != -1) {
                    int finalCover = ((mask1 | (mask1 << 1) | (mask1 >> 1) | mask2) & (LIMIT - 1));
                    if (finalCover == (LIMIT - 1))
                        answer = Math.min(answer, memoTable[R - 1][mask1][mask2]);
                }
            }
        }

        pw.println(R * C - answer);
    }
}

