            int tmp = height; height = width; width = tmp;
        }
        maxMask = 1 << width;
        popCount = new int[maxMask];
        memo = new int[height][maxMask][maxMask];

        for (int i = 0; i < maxMask; i++) popCount[i] = Integer.bitCount(i);

        for (int i = 0; i < height; i++) {
            for (int j = 0; j < maxMask; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }

        for (int mask = 0; mask < maxMask; mask++) {
            memo[0][mask][0] = popCount[mask];
        }

        int result = Integer.MAX_VALUE;

        for (int r = 0; r < height - 1; r++) {
            for (int m1 = 0; m1 < maxMask; m1++) {
                for (int m2 = 0; m2 < maxMask; m2++) {
                    if (memo[r][m1][m2] == -1) continue;
                    for (int m3 = 0; m3 < maxMask; m3++) {
                        int check = ((m1 | (m1 << 1) | (m1 >> 1) | m2 | m3) & (maxMask - 1));
