                    int lastCheck = ((m1 | (m1 << 1) | (m1 >> 1) | m2) & (maxMask - 1));
                    if (lastCheck == (maxMask - 1)) {
                        result = Math.min(result, memo[height - 1][m1][m2]);
                    }
                }
            }
        }

        out.println(height * width - result);
    }
