    private static int bitCount(int num) {
        int count = 0;
        while (num > 0) {
            count++;
            num &= num - 1;
        }
        return count;
    }

    private static boolean fullyCovered(int top, int mid, int bot) {
        int coverage = (maskLimit - 1) & (mid | (mid << 1) | (mid >> 1) | top | bot);
        return coverage == maskLimit - 1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        rows = scanner.nextInt();
