            for (int j = 0; j < maskLimit; j++) {
                Arrays.fill(stateDP[i][j], 999);
            }
        }

        for (int state = 0; state < maskLimit; state++) {
            population[state] = bitCount(state);
            stateDP[0][0][state] = 0;
        }

        for (int layer = 1; layer <= rows; layer++) {
            for (int curState = 0; curState < maskLimit; curState++) {
                for (int prevState = 0; prevState < maskLimit; prevState++) {
                    for (int prevPrevState = 0; prevPrevState < maskLimit; prevPrevState++) {
                        if (stateDP[layer - 1][prevPrevState][prevState] != 999 && 
                            fullyCovered(prevPrevState, prevState, curState)) {
                            stateDP[layer][prevState][curState] = Math.min(
                                stateDP[layer][prevState][curState],
                                stateDP[layer - 1][prevPrevState][prevState] + population[prevState]
                            );
                        }
