public class CF111C_v1 extends PrintWriter {
    CF111C_v1() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);

    public static void main(String[] args) {
        new CF111C_v1().run();
    }

    void run() {
        int n = sc.nextInt();
        int m = sc.nextInt();
        if (n < m) {
            int tmp = n; n = m; m = tmp;
        }
        int p = (int)Math.pow(3, m);
        int[] dp = new int[p];
        int[] dq = new int[p];
        int[] aa = new int[m];
        int[] bb = new int[m];

        Arrays.fill(dp, -1);
        Arrays.fill(aa, 1);
        dp[encode(aa, m)] = 0;

        while (n-- > 0) {
            Arrays.fill(dq, -1);
            for (int state = 0; state < p; state++) {
                if (dp[state] < 0) continue;
                decode(aa, m, state, 3);
                for (int mask = 0; mask < (1 << m); mask++) {
                    decode(bb, m, mask, 2);
                    if (hasInvalidPattern(aa, bb, m)) continue;

                    int cnt = 0;
                    for (int j = 0; j < m; j++) {
                        if (bb[j] == 1) {
                            bb[j] = 2;
                            cnt++;
                        }
                    }
                    applyPropagation(bb, aa, m);
                    int nextState = encode(bb, m);
                    dq[nextState] = Math.max(dq[nextState], dp[state] + m - cnt);
                }
            }
            int[] tmp = dp; dp = dq; dq = tmp;
        }

        int ans = 0;
        for (int state = 0; state < p; state++) {
            if (dp[state] <= ans) continue;
            decode(aa, m, state, 3);
            if (!hasZeros(aa, m)) ans = dp[state];
        }
        println(ans);
        flush();
    }

    int encode(int[] arr, int len) {
        int res = 0;
        for (int i = 0; i < len; i++) {
            res = res * 3 + arr[i];
        }
        return res;
    }

    void decode(int[] arr, int len, int val, int base) {
        for (int i = len - 1; i >= 0; i--) {
            arr[i] = val % base;
            val /= base;
        }
    }

    boolean hasInvalidPattern(int[] a, int[] b, int len) {
        for (int i = 0; i < len; i++) {
            if (a[i] == 0 && b[i] == 0) return true;
        }
        return false;
    }

    void applyPropagation(int[] b, int[] a, int len) {
        for (int i = 0; i < len; i++) {
            if (b[i] == 0 && (a[i] == 2 || (i > 0 && b[i-1] == 2) || (i+1 < len && b[i+1] == 2))) {
                b[i] = 1;
            }
        }
    }

    boolean hasZeros(int[] arr, int len) {
        for (int i = 0; i < len; i++) {
            if (arr[i] == 0) return true;
        }
        return false;
    }
}

