public class CF111C_v2 extends PrintWriter {
    public static void main(String[] args) {
        new CF111C_v2().start();
    }

    Scanner in = new Scanner(System.in);
    PrintWriter out = new PrintWriter(System.out, true);

    void start() {
        int n = in.nextInt();
        int m = in.nextInt();
        if (n < m) { int t = n; n = m; m = t; }
        int states = (int)Math.pow(3, m);
        int[] cur = new int[states];
        int[] nxt = new int[states];
        int[] config = new int[m];
        int[] nextConfig = new int[m];

        Arrays.fill(cur, -1);
        Arrays.fill(config, 1);
        cur[encode(config, m, 3)] = 0;

        for (int step = 0; step < n; step++) {
            Arrays.fill(nxt, -1);
            for (int s = 0; s < states; s++) {
                if (cur[s] < 0) continue;
                decode(config, m, s, 3);
                for (int mask = 0; mask < (1 << m); mask++) {
                    decode(nextConfig, m, mask, 2);
                    if (isInvalid(config, nextConfig, m)) continue;

                    int placed = 0;
                    for (int i = 0; i < m; i++) {
                        if (nextConfig[i] == 1) {
                            nextConfig[i] = 2;
                            placed++;
                        }
                    }
                    propagate(nextConfig, config, m);
                    int ns = encode(nextConfig, m, 3);
                    nxt[ns] = Math.max(nxt[ns], cur[s] + m - placed);
                }
            }
            int[] tmp = cur; cur = nxt; nxt = tmp;
        }

        int best = 0;
        for (int s = 0; s < states; s++) {
            if (cur[s] <= best) continue;
            decode(config, m, s, 3);
            if (!containsZero(config, m)) best = cur[s];
        }
        out.println(best);
        out.close();
    }

    int encode(int[] arr, int len, int base) {
        int res = 0;
        for (int i = 0; i < len; i++) res = res * base + arr[i];
        return res;
    }

    void decode(int[] arr, int len, int val, int base) {
        for (int i = len - 1; i >= 0; i--) {
            arr[i] = val % base;
            val /= base;
