    static class TaskC {
        private static final int BAD = 11111;
        private int rows;
        private int cols;
        private Map<IntIntPair, Integer>[] dpMemo;

        private boolean isBitSet(int state, int pos) {
            if (pos < 0) return false;
            return ((state >> pos) & 1) == 1;
        }

        private int setBit(int state, int pos) {
            if (!isBitSet(state, pos)) {
                state |= (1 << pos);
            }
            return state;
        }

        private int popCount(int state) {
            int count = 0;
            while (state != 0) {
                count += state & 1;
                state >>= 1;
            }
            return count;
        }

        private void sanityCheck() {
            if (!isBitSet(5, 0)) throw new AssertionError();
            if (isBitSet(5, 1)) throw new AssertionError();
            if (isBitSet(5, -1)) throw new AssertionError();
            if (!isBitSet(5, 2)) throw new AssertionError();
            if (!isBitSet(5, 3)) throw new AssertionError();
            if (setBit(0, 2) != 4) throw new AssertionError();
            if (setBit(4, 0) != 5) throw new AssertionError();
            if (setBit(5, 0) != 5) throw new AssertionError();
            if (popCount(5) != 2) throw new AssertionError();
        }

        private int computeDP(int level, int needed, int prevPattern) {
            if (level == rows) {
                return (needed == 0) ? 0 : BAD;
            }
            IntIntPair pair = new IntIntPair(needed, prevPattern);
            if (dpMemo[level].containsKey(pair)) {
                return dpMemo[level].get(pair);
            }
            int best = BAD;
            int maxConfigs = 1 << cols;
            for (int cfg = 0; cfg < maxConfigs; cfg++) {
                int current = 0;
                for (int j = 0; j < cols; j++) {
                    if (((cfg >> j) & 1) == 1) {
                        current |= (1 << j);
                    }
                }
                boolean ok = true;
                for (int k = 0; k < cols; k++) {
                    if (((needed >> k) & 1) == 1 && (((current >> k) & 1) == 0)) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    int future = 0;
                    for (int j = 0; j < cols; j++) {
                        if (!isBitSet(current, j - 1) && !isBitSet(current, j) &&
                            !isBitSet(current, j + 1) && !isBitSet(prevPattern, j)) {
                            future |= (1 << j);
                        }
                    }
                    int temp = popCount(current) + computeDP(level + 1, future, current);
                    best = Math.min(best, temp);
                }
            }
            dpMemo[level].put(pair, best);
            return best;
        }

        public void solve(int testNum, InputReader reader, OutputWriter writer) {
            sanityCheck();
            int n = reader.readInt(), m = reader.readInt();
            cols = Math.min(n, m);
            rows = Math.max(n, m);
            dpMemo = new HashMap[rows];
            for (int i = 0; i < rows; i++) {
                dpMemo[i] = new HashMap<>();
            }
            int res = computeDP(0, 0, 0);
            writer.printLine(cols * rows - res);
        }
    }

