        }
    }

    static class ProblemTask {
        static final int IMPOSSIBLE = 11111;
        int height;
        int width;
        Map<Coordinate, Integer>[] cache;

        boolean getBit(int val, int bitIdx) {
            if (bitIdx < 0) return false;
            return ((val >> bitIdx) & 1) == 1;
        }

        int setBitIfMissing(int val, int bitIdx) {
            if (((val >> bitIdx) & 1) == 0) {
                val |= (1 << bitIdx);
            }
            return val;
        }

        int countSetBits(int val) {
            int cnt = 0;
            while (val != 0) {
                cnt += val & 1;
                val >>>= 1;
            }
            return cnt;
        }

        void validate() {
            if (!getBit(5, 0)) throw new AssertionError();
            if (getBit(5, 1)) throw new AssertionError();
            if (getBit(5, -1)) throw new AssertionError();
            if (!getBit(5, 2)) throw new AssertionError();
            if (!getBit(5, 3)) throw new AssertionError();
            if (setBitIfMissing(0, 2) != 4) throw new AssertionError();
            if (setBitIfMissing(4, 0) != 5) throw new AssertionError();
            if (setBitIfMissing(5, 0) != 5) throw new AssertionError();
            if (countSetBits(5) != 2) throw new AssertionError();
        }

        int memoizedSearch(int row, int required, int priorPattern) {
            if (row == height) {
                return required == 0 ? 0 : IMPOSSIBLE;
            }
            Coordinate state = new Coordinate(required, priorPattern);
            if (cache[row].containsKey(state)) {
                return cache[row].get(state);
            }
            int best = IMPOSSIBLE;
            int totalPatterns = 1 << width;
            for (int pattern = 0; pattern < totalPatterns; pattern++) {
                int present = 0;
                for (int idx = 0; idx < width; idx++) {
                    if (((pattern >> idx) & 1) == 1) {
                        present |= (1 << idx);
                    }
                }
                boolean acceptable = true;
                for (int k = 0; k < width; k++) {
                    if (getBit(required, k) && !getBit(present, k)) {
                        acceptable = false;
                        break;
                    }
                }
                if (acceptable) {
                    int nextRequired = 0;
                    for (int idx = 0; idx < width; idx++) {
                        if (!getBit(present, idx - 1) && !getBit(present, idx) &&
                            !getBit(present, idx + 1) && !getBit(priorPattern, idx)) {
                            nextRequired |= (1 << idx);
                        }
                    }
                    int nextStep = countSetBits(present) + memoizedSearch(row + 1, nextRequired, present);
                    if (nextStep < best) best = nextStep;
                }
            }
            cache[row].put(state, best);
            return best;
        }

        public void run(int caseNum, InputReader reader, OutputWriter writer) {
            validate();
            int a = reader.readInt();
            int b = reader.readInt();
            width = Math.min(a, b);
            height = Math.max(a, b);
            cache = new HashMap[height];
            for (int i = 0; i < height; i++) {
                cache[i] = new HashMap<>();
            }
            int answer = memoizedSearch(0, 0, 0);
            writer.printLine(width * height - answer);
        }
    }

    static class Coordinate implements Comparable<Coordinate> {
        final int x;
        final int y;

        Coordinate(int i, int j) {
            x = i;
            y = j;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Coordinate c = (Coordinate) o;
            return x == c.x && y == c.y;
        }

        public int hashCode() {
            int hash = 17;
            hash = 31 * hash + x;
            hash = 31 * hash + y;
            return hash;
        }

        public String toString() {
            return "(" + x + "," + y + ")";
        }

        public int compareTo(Coordinate other) {
            int diff = Integer.compare(x, other.x);
            if (diff != 0) return diff;
            return Integer.compare(y, other.y);
        }
    }

    static class InputReader {
        private final InputStream input;
        private final byte[] buffer = new byte[1024];
        private int position = 0;
        private int limit = 0;
        private SpaceCharacterPredicate condition;

        public InputReader(InputStream stream) {
            input = stream;
        }

        private int fetch() {
            if (position == limit) {
                position = 0;
                try {
                    limit = input.read(buffer);
                } catch (IOException ex) {
                    throw new InputMismatchException();
                }
                if (limit <= 0) return -1;
            }
            return buffer[position++];
        }

        public int readNumber() {
            int c = fetch();
            while (isWhitespace(c)) c = fetch();
            int multiplier = 1;
            if (c == '-') {
                multiplier = -1;
                c = fetch();
            }
            int value = 0;
            while (!isWhitespace(c)) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = fetch();
            }
            return value * multiplier;
        }

        private boolean isWhitespace(int ch) {
            if (condition != null) return condition.test(ch);
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        public interface SpaceCharacterPredicate {
            boolean test(int ch);
        }
    }

