public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        Algorithm solver = new Algorithm();
        solver.execute(1, in, out);
        out.close();
    }

    static class Algorithm {
        static final int INVALID_RESULT = 11111;
        int R, C;
        Map<Configuration, Integer>[] storage;

        boolean hasBit(int state, int idx) {
            if (idx < 0) return false;
            return ((state >> idx) & 1) == 1;
        }

        int turnOnBit(int state, int idx) {
            if (!hasBit(state, idx)) {
                state |= (1 << idx);
            }
            return state;
        }

        int countBits(int state) {
            int c = 0;
            while (state != 0) {
                c += state & 1;
                state >>= 1;
            }
            return c;
        }

        void initialValidation() {
            if (!hasBit(5, 0)) throw new IllegalStateException("Test1 failed");
            if (hasBit(5, 1)) throw new IllegalStateException("Test2 failed");
            if (hasBit(5, -1)) throw new IllegalStateException("Test3 failed");
            if (!hasBit(5, 2)) throw new IllegalStateException("Test4 failed");
            if (!hasBit(5, 3)) throw new IllegalStateException("Test5 failed");
            if (turnOnBit(0, 2) != 4) throw new IllegalStateException("Test6 failed");
            if (turnOnBit(4, 0) != 5) throw new IllegalStateException("Test7 failed");
            if (turnOnBit(5, 0) != 5) throw new IllegalStateException("Test8 failed");
            if (countBits(5) != 2) throw new IllegalStateException("Test9 failed");
        }

        int recursiveSolve(int level, int need, int previous) {
            if (level == R) {
                return need == 0 ? 0 : INVALID_RESULT;
            }
            Configuration key = new Configuration(need, previous);
            if (storage[level].containsKey(key)) {
                return storage[level].get(key);
            }
            int minVal = INVALID_RESULT;
            int total = 1 << C;
            for (int pattern = 0; pattern < total; pattern++) {
                int cur = 0;
                for (int pos = 0; pos < C; pos++) {
                    if (((pattern >> pos) & 1) == 1) {
                        cur |= (1 << pos);
                    }
                }
                boolean fits = true;
                for (int i = 0; i < C; i++) {
                    if (hasBit(need, i) && !hasBit(cur, i)) {
                        fits = false;
                        break;
                    }
                }
                if (fits) {
                    int futureNeed = 0;
                    for (int pos = 0; pos < C; pos++) {
                        if (!hasBit(cur, pos - 1) && !hasBit(cur, pos) &&
                            !hasBit(cur, pos + 1) && !hasBit(previous, pos)) {
                            futureNeed |= (1 << pos);
                        }
                    }
                    int futureCost = countBits(cur) + recursiveSolve(level + 1, futureNeed, cur);
                    if (futureCost < minVal) minVal = futureCost;
                }
            }
            storage[level].put(key, minVal);
            return minVal;
        }

        public void execute(int caseId, InputReader r, OutputWriter w) {
            initialValidation();
            int dim1 = r.readInt();
            int dim2 = r.readInt();
            C = Math.min(dim1, dim2);
            R = Math.max(dim1, dim2);
            storage = new HashMap[R];
            for (int i = 0; i < R; i++) {
                storage[i] = new HashMap<>();
            }
            int opt = recursiveSolve(0, 0, 0);
            w.println(C * R - opt);
        }
    }

    static class Configuration implements Comparable<Configuration> {
        final int u;
        final int v;

        Configuration(int a, int b) {
            u = a;
            v = b;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Configuration that = (Configuration) o;
            return u == that.u && v == that.v;
        }

        public int hashCode() {
            int h = 17;
            h = 31 * h + u;
            h = 31 * h + v;
            return h;
        }

        public String toString() {
            return "(" + u + "," + v + ")";
        }

        public int compareTo(Configuration other) {
            int d = Integer.compare(u, other.u);
            if (d != 0) return d;
            return Integer.compare(v, other.v);
        }
    }

    static class InputReader {
        private final InputStream src;
        private final byte[] buf = new byte[1024];
        private int idx = 0;
        private int len = 0;

        public InputReader(InputStream stream) {
            src = stream;
        }

        private int next() {
            if (idx == len) {
                idx = 0;
                try {
                    len = src.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (len <= 0) return -1;
            }
            return buf[idx++];
        }

        public int readInt() {
            int c = next();
            while (isSpace(c)) c = next();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = next();
            }
            int val = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                val = val * 10 + (c - '0');
                c = next();
            }
            return val * sign;
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter pw;

        public OutputWriter(OutputStream os) {
            pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(os)));
        }

        public void close() {
            pw.close();
        }

