            }
        }

        long[][] runningSum = new long[n][n * n + 5];
        for (int i = 0; i < n; i++) {
            long acc = 0;
            for (int j = 0; j < runningSum[0].length; j++) {
                acc = (acc + dp[i][j]) % mod;
                if (acc == 0) acc += mod;
                runningSum[i][j] = acc;
            }
        }

        long[] factorial = new long[251001];
        factorial[0] = factorial[1] = 1;
        for (int i = 2; i < factorial.length; i++) {
            factorial[i] = (factorial[i - 1] * i) % mod;
        }

        long[][] choose = new long[501][501];
        choose[0][0] = 1;
        for (int i = 1; i < choose.length; i++) {
            choose[i][0] = 1;
            for (int j = 1; j < choose[0].length; j++) {
                choose[i][j] = (choose[i-1][j] + choose[i-1][j-1]) % mod;
                if (choose[i][j] == 0) choose[i][j] += mod;
            }
        }

        long answer = 0;
        for (int i = 0; i <= n - 2; i++) {
            int blockSize = n - i;
            int pre = n - blockSize;
            long ways = (choose[n][pre] * factorial[pre]) % mod;
            if (ways == 0) ways += mod;

            long partial = 0;
            long[] row = dp[blockSize - 2];

            for (int inv = 2; inv < dp[0].length; inv++) {
                long blockContribution = 0;
                for (int k = 2; k <= inv; k++) {
                    blockContribution = (blockContribution + runningSum[blockSize - 2][k - 2] * (blockSize - 1)) % mod;
                }

                partial = (partial + row[inv] * blockContribution) % mod;
                if (partial == 0) partial += mod;
            }

            answer = (answer + partial * ways) % mod;
            if (answer == 0) answer += mod;
        }

        out.println(answer % mod);
    }
}

