public class e1542easy {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();
        solve(n, mod);
    }

    static void solve(int n, int mod) {
        List<long[]> dp = new ArrayList<>();
        dp.add(new long[]{1});

        for (int step = 1; step < n; step++) {
            long[] prev = dp.get(step - 1);
            int size = step * (step + 1) / 2 + 1;
            long[] curr = new long[size];

            for (int pos = 0; pos < size; pos++) {
                long count = 0;
                int start = Math.min(pos, step);
                for (int offset = start; offset >= 0; offset--) {
                    int prevIdx = pos - offset;
                    if (prevIdx < prev.length) {
                        count = (count + prev[prevIdx]) % mod;
                    }
                }
                curr[pos] = count;
            }
            dp.add(curr);
        }

        long[] output = new long[n];
        output[0] = 0;

        for (int idx = 1; idx < n; idx++) {
            long current = (output[idx - 1] * (idx + 1)) % mod;
            long[] inv = dp.get(idx - 1);

            for (int a = 0; a < inv.length; a++) {
                for (int b = a + 2; b < inv.length; b++) {
                    long gap = b - a;
                    long m = Math.min(gap, idx + 1);
                    long multiplier = (m - 1) * (2L * idx - (m - 2)) / 2;
                    current = (current + ((inv[a] * inv[b]) % mod) * multiplier) % mod;
                }
            }
            output[idx] = current;
        }

        System.out.println(output[n - 1]);
    }
}

