            int c = read();
            while (c <= ' ') c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

import java.io.*;
