public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    private void execute() {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        try {
            int n = in.nextInt();
            int m = in.nextInt();
            ModInt mod = new ModInt(m);
            int[] fact = new int[n + 1];
            fact[0] = n;
            for (int i = 1; i < n; i++) {
                fact[i] = mod.multiply(fact[i - 1], n - i);
            }
            int totalPairs = n * (n - 1);
            int mid = totalPairs / 2;
            int[] cur = new int[totalPairs + 1];
            int[] nxt = new int[totalPairs + 1];
            cur[mid] = 1;
            int ans = 0;
            for (int step = n - 1; step >= 0; step--) {
                int[] tmp = cur;
                cur = nxt;
                nxt = tmp;
                Arrays.fill(nxt, 0);
                int c = n - 1 - step;
                int bound = (c * (c - 1)) / 2;
                int contrib = 0;
                for (int offset = -c; offset < 0; offset++) {
                    int pairs = c + offset + 1;
                    for (int idx = mid - offset + 1; idx <= mid + bound; idx++) {
                        contrib = mod.add(contrib, mod.multiply(tmp[idx], pairs));
                    }
                }
                ans = mod.add(ans, mod.multiply(contrib, step == 0 ? 1 : fact[step - 1]));
                for (int idx = mid - bound; idx <= mid + bound; idx++) {
                    for (int offset = -c; offset <= c; offset++) {
                        int pairs = c - Math.abs(offset) + 1;
                        nxt[idx + offset] = mod.add(nxt[idx + offset], mod.multiply(pairs, tmp[idx]));
                    }
                }
            }
            out.println(ans);
        } finally {
            out.close();
        }
    }

