            pw.close();
        }
    }

    static class ModInt {
        private final int MOD;

        public ModInt(int m) {
            MOD = m;
        }

        public int add(int a, int b) {
            a += b;
            if (a >= MOD) a -= MOD;
            return a;
        }

        public int multiply(int a, int b) {
            return (int) ((1L * a * b) % MOD);
        }
    }

    static class InputReader {
        private final InputStream is;
        private final byte[] buf = new byte[1024];
        private int p, len;

        public InputReader(InputStream stream) {
            is = stream;
        }

        private int nextByte() {
            if (len == -1) throw new RuntimeException();
            if (p >= len) {
                p = 0;
                try {
                    len = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (len <= 0) return -1;
            }
            return buf[p++];
        }

        public int nextInt() {
            int c;
            while ((c = nextByte()) <= ' ') ;
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextByte();
            }
            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + c - '0';
                c = nextByte();
            }
            return val * sign;
        }
    }
}

