                try {
                    len = stream.read(buffer);
                } catch (Exception e) {
                }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            boolean neg = false;
            if (c == '-') {
