public class E {

    public E() {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = sc.nextInt();
        List<Integer> V = new ArrayList<>(), K = new ArrayList<>(), X = new ArrayList<>();
        char[] s = sc.next().toCharArray();
        for (int i = 0; i < n; i++) {
            if (s[i] == 'V') V.add(i);
            else if (s[i] == 'K') K.add(i);
            else X.add(i);
        }
        int vSize = V.size(), kSize = K.size(), xSize = X.size();
        long[][][][] dp = new long[vSize + 1][kSize + 1][xSize + 1][2];
        for (int i = 0; i <= vSize; i++)
            for (int j = 0; j <= kSize; j++)
                for (int k = 0; k <= xSize; k++)
                    for (int d = 0; d < 2; d++)
                        dp[i][j][k][d] = Long.MAX_VALUE;
        dp[0][0][0][0] = 0;

        for (int v = 0; v <= vSize; v++) {
            for (int k = 0; k <= kSize; k++) {
                for (int x = 0; x <= xSize; x++) {
                    for (int t = 0; t < 2; t++) {
                        if (dp[v][k][x][t] == Long.MAX_VALUE) continue;
                        long cur = dp[v][k][x][t];

                        if (v < vSize) {
                            int pos = V.get(v);
                            int cost = countBefore(V, v, pos) + countBefore(K, k, pos) + countBefore(X, x, pos);
                            dp[v+1][k][x][1] = Math.min(dp[v+1][k][x][1], cur + cost);
                        }
                        if (k < kSize && t == 0) {
                            int pos = K.get(k);
                            int cost = countBefore(V, v, pos) + countBefore(K, k, pos) + countBefore(X, x, pos);
                            dp[v][k+1][x][0] = Math.min(dp[v][k+1][x][0], cur + cost);
                        }
                        if (x < xSize) {
                            int pos = X.get(x);
                            int cost = countBefore(V, v, pos) + countBefore(K, k, pos) + countBefore(X, x, pos);
                            dp[v][k][x+1][0] = Math.min(dp[v][k][x+1][0], cur + cost);
                        }
                    }
                }
            }
        }

        long ans = Math.min(dp[vSize][kSize][xSize][0], dp[vSize][kSize][xSize][1]);
        out.println(ans);
        sc.close();
        out.close();
    }

    private int countBefore(List<Integer> list, int idx, int val) {
        int cnt = 0;
        for (int i = 0; i < idx && i < list.size(); i++) {
            if (list.get(i) < val) cnt++;
        }
        return cnt;
    }

    public static void main(String[] args) {
        new E();
    }
}

