                                dp[i+1][j][k][1] = Math.min(dp[i+1][j][k][1], cost + c);
                            }

                            if (j < kLen && state == 0) {
                                int pos = kList.get(j);
                                int c = getCost(vList, i, pos) + getCost(kList, j, pos) + getCost(xList, k, pos);
                                dp[i][j+1][k][0] = Math.min(dp[i][j+1][k][0], cost + c);
                            }

                            if (k < xLen) {
                                int pos = xList.get(k);
                                int c = getCost(vList, i, pos) + getCost(kList, j, pos) + getCost(xList, k, pos);
                                dp[i][j][k+1][0] = Math.min(dp[i][j][k+1][0], cost + c);
                            }
                        }
                    }
                }
            }

            long res = Math.min(dp[vLen][kLen][xLen][0], dp[vLen][kLen][xLen][1]);
            out.println(res);
        }
    }

    private int getCost(List<Integer> list, int idx, int val) {
        int count = 0;
        for (int i = 0; i < idx; i++) {
            if (list.get(i) < val) count++;
        }
        return count;
    }

