            int INF = 1_000_000_000;
            for (int i = 0; i <= nv; i++) {
                for (int j = 0; j <= nk; j++) {
                    Arrays.fill(dp[0][i][j], INF);
                    Arrays.fill(dp[1][i][j], INF);
                    Arrays.fill(dp[2][i][j], INF);
                }
            }
            dp[2][0][0][0] = 0;

            int[][][][] positions = new int[3][nv+1][nk+1][ne+1];
            for (int i = 0; i <= nv; i++) {
                for (int j = 0; j <= nk; j++) {
                    for (int k = 0; k <= ne; k++) {
                        for (int t = 0; t < 3; t++) {
                            positions[t][i][j][k] = findPos(s, i, j, k, t);
                        }
                    }
                }
            }

            for (int i = 0; i <= nv; i++) {
                for (int j = 0; j <= nk; j++) {
                    for (int k = 0; k <= ne; k++) {
                        if (i + 1 <= nv && positions[0][i][j][k] != -1) {
                            int cost = positions[0][i][j][k];
                            dp[0][i+1][j][k] = Math.min(dp[0][i+1][j][k], dp[0][i][j][k] + cost);
                            dp[0][i+1][j][k] = Math.min(dp[0][i+1][j][k], dp[1][i][j][k] + cost);
                            dp[0][i+1][j][k] = Math.min(dp[0][i+1][j][k], dp[2][i][j][k] + cost);
                        }
                        if (j + 1 <= nk && positions[1][i][j][k] != -1) {
                            int cost = positions[1][i][j][k];
                            dp[1][i][j+1][k] = Math.min(dp[1][i][j+1][k], dp[1][i][j][k] + cost);
                            dp[1][i][j+1][k] = Math.min(dp[1][i][j+1][k], dp[2][i][j][k] + cost);
                        }
                        if (k + 1 <= ne && positions[2][i][j][k] != -1) {
                            int cost = positions[2][i][j][k];
                            dp[2][i][j][k+1] = Math.min(dp[2][i][j][k+1], dp[0][i][j][k] + cost);
                            dp[2][i][j][k+1] = Math.min(dp[2][i][j][k+1], dp[1][i][j][k] + cost);
                            dp[2][i][j][k+1] = Math.min(dp[2][i][j][k+1], dp[2][i][j][k] + cost);
                        }
                    }
                }
            }

            int result = Math.min(dp[0][nv][nk][ne], Math.min(dp[1][nv][nk][ne], dp[2][nv][nk][ne]));
            System.out.println(result);
        }
    }

    int findPos(String s, int a, int b, int c, int type) {
        int pos = 0;
        for (char ch : s.toCharArray()) {
            if (ch == 'V') {
                if (a == 0) {
                    if (type == 0) return pos;
                    pos++;
                } else {
                    a--;
                }
            } else if (ch == 'K') {
                if (b == 0) {
                    if (type == 1) return pos;
                    pos++;
                } else {
                    b--;
                }
            } else {
                if (c == 0) {
                    if (type == 2) return pos;
                    pos++;
                } else {
                    c--;
                }
            }
        }
        return -1;
    }
}

import java.io.*;
