public class CodeforcesRound405C {
    public static void main(String[] args) throws Exception {
        new CodeforcesRound405C().mainLogic();
    }

    private void mainLogic() throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine();
        int n = Integer.parseInt(br.readLine());

        char[] seq = input.toCharArray();
        int cntV = 0, cntK = 0, cntE = 0;
        for (char c : seq) {
            if (c == 'V') cntV++;
            else if (c == 'K') cntK++;
            else cntE++;
        }

        final int INF = Integer.MAX_VALUE / 2;
        int[][][][] dp = new int[3][cntV + 1][cntK + 1][cntE + 1];
        for (int i = 0; i <= cntV; i++) {
            for (int j = 0; j <= cntK; j++) {
                for (int k = 0; k <= cntE; k++) {
                    Arrays.fill(dp[0][i][j], INF);
                    Arrays.fill(dp[1][i][j], INF);
                    Arrays.fill(dp[2][i][j], INF);
                }
            }
        }
        dp[2][0][0][0] = 0;

        int[][][][] poss = new int[3][cntV + 1][cntK + 1][cntE + 1];
        for (int a = 0; a <= cntV; a++) {
            for (int b = 0; b <= cntK; b++) {
                for (int c = 0; c <= cntE; c++) {
                    for (int t = 0; t < 3; t++) {
                        poss[t][a][b][c] = findFirstIndex(seq, a, b, c, t);
                    }
                }
            }
        }

        for (int a = 0; a <= cntV; a++) {
            for (int b = 0; b <= cntK; b++) {
                for (int c = 0; c <= cntE; c++) {
                    if (a + 1 <= cntV && poss[0][a][b][c] != -1) {
                        int cost = poss[0][a][b][c];
                        dp[0][a + 1][b][c] = min(dp[0][a + 1][b][c], dp[0][a][b][c] + cost, dp[1][a][b][c] + cost, dp[2][a][b][c] + cost);
                    }
                    if (b + 1 <= cntK && poss[1][a][b][c] != -1) {
                        int cost = poss[1][a][b][c];
                        dp[1][a][b + 1][c] = min(dp[1][a][b + 1][c], dp[1][a][b][c] + cost, dp[2][a][b][c] + cost);
                    }
                    if (c + 1 <= cntE && poss[2][a][b][c] != -1) {
                        int cost = poss[2][a][b][c];
                        dp[2][a][b][c + 1] = min(dp[2][a][b][c + 1], dp[0][a][b][c] + cost, dp[1][a][b][c] + cost, dp[2][a][b][c] + cost);
                    }
                }
            }
        }

        System.out.println(min(dp[0][cntV][cntK][cntE], dp[1][cntV][cntK][cntE], dp[2][cntV][cntK][cntE]));
    }

    private int min(int... values) {
        int m = Integer.MAX_VALUE;
        for (int v : values) {
            if (v < m) m = v;
        }
        return m;
    }

    private int findFirstIndex(char[] seq, int needV, int needK, int needE, int kind) {
        int idx = 0;
        for (char ch : seq) {
            if (ch == 'V') {
                if (needV == 0) {
                    if (kind == 0) return idx;
                    idx++;
                } else {
                    needV--;
                }
            } else if (ch == 'K') {
                if (needK == 0) {
                    if (kind == 1) return idx;
                    idx++;
                } else {
                    needK--;
                }
            } else {
                if (needE == 0) {
                    if (kind == 2) return idx;
                    idx++;
                } else {
                    needE--;
                }
            }
        }
        return -1;
    }
}

import java.io.*;
import java.util.*;

public class EducationalRoundC {
    public static void main(String[] args) {
        EducationalRoundC solver = new EducationalRoundC();
        solver.solve();
    }

    private void solve() {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int n = sc.nextInt();

        int vCount = 0, kCount = 0, eCount = 0;
        for (char c : s.toCharArray()) {
            switch (c) {
                case 'V': vCount++; break;
                case 'K': kCount++; break;
                default: eCount++; break;
            }
        }

        final int INF = 99999999;
        int[][][][] dp = new int[3][vCount + 1][kCount + 1][eCount + 1];
        for (int t = 0; t < 3; t++) {
            for (int i = 0; i <= vCount; i++) {
                for (int j = 0; j <= kCount; j++) {
                    Arrays.fill(dp[t][i][j], INF);
                }
            }
        }
        dp[2][0][0][0] = 0;

        int[][][][] posTable = new int[3][vCount + 1][kCount + 1][eCount + 1];
        for (int i = 0; i <= vCount; i++) {
            for (int j = 0; j <= kCount; j++) {
                for (int k = 0; k <= eCount; k++) {
                    for (int t = 0; t < 3; t++) {
                        posTable[t][i][j][k] = findTargetPosition(s, i, j, k, t);
                    }
                }
            }
        }

        for (int i = 0; i <= vCount; i++) {
            for (int j = 0; j <= kCount; j++) {
                for (int k = 0; k <= eCount; k++) {
                    if (i + 1 <= vCount && posTable[0][i][j][k] != -1) {
                        int p = posTable[0][i][j][k];
                        dp[0][i + 1][j][k] = Math.min(dp[0][i + 1][j][k], Math.min(dp[0][i][j][k], Math.min(dp[1][i][j][k], dp[2][i][j][k])) + p);
                    }
                    if (j + 1 <= kCount && posTable[1][i][j][k] != -1) {
                        int p = posTable[1][i][j][k];
                        dp[1][i][j + 1][k] = Math.min(dp[1][i][j + 1][k], Math.min(dp[1][i][j][k], dp[2][i][j][k]) + p);
                    }
                    if (k + 1 <= eCount && posTable[2][i][j][k] != -1) {
                        int p = posTable[2][i][j][k];
                        dp[2][i][j][k + 1] = Math.min(dp[2][i][j][k + 1], Math.min(dp[0][i][j][k], Math.min(dp[1][i][j][k], dp[2][i][j][k])) + p);
                    }
                }
            }
        }

        int answer = Math.min(dp[0][vCount][kCount][eCount], Math.min(dp[1][vCount][kCount][eCount], dp[2][vCount][kCount][eCount]));
        System.out.println(answer);
    }

    private int findTargetPosition(String seq, int needV, int needK, int needE, int kind) {
        int pos = 0;
        for (char c : seq.toCharArray()) {
            if (c == 'V') {
                if (needV == 0) {
                    if (kind == 0) return pos;
                    pos++;
                } else {
                    needV--;
                }
            } else if (c == 'K') {
                if (needK == 0) {
                    if (kind == 1) return pos;
                    pos++;
                } else {
                    needK--;
                }
            } else {
                if (needE == 0) {
                    if (kind == 2) return pos;
                    pos++;
                } else {
                    needE--;
                }
            }
        }
        return -1;
    }
}

import java.io.*;
import java.util.*;

public class C {

	BufferedReader br;
	PrintWriter out;
	StringTokenizer st;
	boolean eof;

	void submit() throws IOException {
		nextInt();
		String s = nextToken();
		out.println(fast(s));
//		out.println(slow(s));
	}

	static final String BAD = "VK";

	String prepare(String s) {
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < s.length(); i++) {
			char c = s.charAt(i);
			if (BAD.indexOf(c) != -1) {
				sb.append(c);
			} else {
				sb.append('A');
			}
		}
		return sb.toString();
	}

	int slow(String s) {
		s = prepare(s);
		HashMap<String, Integer> map = new HashMap<>();
		ArrayDeque<String> que = new ArrayDeque<>();
		que.add(s);
		map.put(s, 0);

		while (true) {
			s = que.poll();
			int curD = map.get(s);
			if (s.indexOf(BAD) == -1) {
				// System.err.println(s);
				return curD;
			}

			for (int i = 0; i < s.length() - 1; i++) {
				String nxt = swap(s, i, i + 1);
				if (nxt != null && !map.containsKey(nxt)) {
					map.put(nxt, curD + 1);
					que.add(nxt);
				}
			}
		}
	}

	String swap(String s, int i, int j) {
		if (s.charAt(i) == s.charAt(j)) {
			return null;
		}
		char[] buf = s.toCharArray();
		char tmp = buf[i];
		buf[i] = buf[j];
		buf[j] = tmp;
		return new String(buf);
	}

	static final String STR = "VKA";

	int fast(String s) {

		s = prepare(s);

		int n = s.length();

		int[] a = new int[n];
		int[][] pos = new int[3][n];
		int[] sz = new int[3];

		int[][][] cntHere = new int[3][n][3];

		int[][] pref = new int[n + 1][];

		pref[0] = new int[] { 0, 0, 0 };

		for (int i = 0; i < n; i++) {
			a[i] = STR.indexOf(s.charAt(i));
			int c = a[i];
			cntHere[c][sz[c]] = pref[i].clone();
			pos[c][sz[c]++] = i;

			pref[i + 1] = pref[i].clone();
			pref[i + 1][c]++;
		}

		int[][][][] dp = new int[2][sz[0] + 1][sz[1] + 1][sz[2] + 1];

		for (int i = 0; i < 2; i++) {
			for (int j0 = 0; j0 <= sz[0]; j0++) {
				for (int j1 = 0; j1 <= sz[1]; j1++) {
					Arrays.fill(dp[i][j0][j1], INF);
				}
			}
		}

		int ans = INF;

		dp[0][0][0][0] = 0;
		for (int j0 = 0; j0 <= sz[0]; j0++) {
			for (int j1 = 0; j1 <= sz[1]; j1++) {
				for (int j2 = 0; j2 <= sz[2]; j2++) {
					for (int last = 0; last < 2; last++) {
						//
						// if (j0 == 2 && j1 == 0 && j2 == 1) {
						// System.err.println(dp[last][j0][j1][j2]);
						// }

						int idx = j0 + j1 + j2;
						int curVal = dp[last][j0][j1][j2];
						if (curVal == INF) {
							continue;
						}

						if (idx == n) {
							ans = Math.min(ans, curVal);
							continue;
						}

						if (j0 < sz[0]) {
							int cost = Math.max(j1 - cntHere[0][j0][1], 0)
									+ Math.max(j2 - cntHere[0][j0][2], 0);
							dp[1][j0 + 1][j1][j2] = Math.min(
									dp[1][j0 + 1][j1][j2], curVal + cost);
						}

						if (j1 < sz[1] && last == 0) {
							int cost = Math.max(j0 - cntHere[1][j1][0], 0)
									+ Math.max(j2 - cntHere[1][j1][2], 0);
							dp[0][j0][j1 + 1][j2] = Math.min(
									dp[0][j0][j1 + 1][j2], curVal + cost);
						}

						if (j2 < sz[2]) {
							int cost = Math.max(j0 - cntHere[2][j2][0], 0)
									+ Math.max(j1 - cntHere[2][j2][1], 0);
							dp[0][j0][j1][j2 + 1] = Math.min(
									dp[0][j0][j1][j2 + 1], curVal + cost);
						}
					}
				}
			}
		}

		return ans;
	}

	static final int INF = 1_000_000;

	static final Random rng = new Random();

	String genStr() {
		int n = rng.nextInt(15) + 1;
		// int n = 6;
		char[] buf = new char[n];
		for (int i = 0; i < n; i++) {
			buf[i] = STR.charAt(rng.nextInt(3));
		}
		return new String(buf);
	}

	void stress() {
		for (int tst = 0;; tst++) {
			String s = genStr();
			int fast = fast(s);
			int slow = slow(s);
			if (fast != slow) {
				System.err.println(s);
				System.err.println(fast);
				System.err.println(slow);
				throw new AssertionError();
			}
			System.err.println(tst);
		}
	}

	C() throws IOException {
		br = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);
		submit();
		// stress();
		out.close();
	}

	public static void main(String[] args) throws IOException {
		new C();
	}

	String nextToken() {
		while (st == null || !st.hasMoreTokens()) {
			try {
				st = new StringTokenizer(br.readLine());
			} catch (Exception e) {
				eof = true;
				return null;
			}
		}
		return st.nextToken();
	}

	String nextString() {
		try {
			return br.readLine();
		} catch (IOException e) {
			eof = true;
			return null;
		}
	}

	int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	long nextLong() throws IOException {
		return Long.parseLong(nextToken());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}
}

