            String candidate = Integer.toString(n);

            if (candidate.length() != pattern.length()) continue;

            char xPlaceholder = 0;
            boolean xFound = false;
            boolean match = true;

            for (int pos = 0; pos < pattern.length(); pos++) {
                char pc = pattern.charAt(pos);
                char cc = candidate.charAt(pos);

                if (pc == 'X') {
                    if (!xFound) {
                        xPlaceholder = cc;
                        xFound = true;
                    } else if (cc != xPlaceholder) {
                        match = false;
                        break;
                    }
                } else if (pc != '_') {
                    if (cc != pc) {
                        match = false;
                        break;
                    }
                }
            }

            if (match) count++;
        }

        System.out.println(count);
    }

