        private long[] z;
        private long[] z1;
        private long[] z2;
        private long mod;

        public Combinations(long N, long mod) {
            this.mod = mod;
            z = new long[(int) N + 1];
            z1 = new long[(int) N + 1];
            z[0] = 1;
            for (int i = 1; i <= N; i++) z[i] = (z[i - 1] * i) % mod;
            z2 = new long[(int) N + 1];
            z2[0] = z2[1] = 1;
            for (int i = 2; i <= N; i++)
                z2[i] = z2[(int) (mod % i)] * (mod - mod / i) % mod;
            z1[0] = z1[1] = 1;
            for (int i = 2; i <= N; i++)
                z1[i] = (z2[i] * z1[i - 1]) % mod;
        }

        long fac(long n) {
