        }

        long invrsNum(long n) {
            return z2[(int) n];
        }

        long invrsFac(long n) {
            return invrsFac((int) n);
        }

        long ncr(long N, long R) {
            if (R < 0 || R > N) return 0;
            long ans = ((z[(int) N] * z1[(int) R]) % mod * z1[(int) (N - R)]) % mod;
            return ans;
        }
    }

