public class div25_v1 {
    public static char[] str;
    public static int S;

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        str = in.readLine().toCharArray();
        S = str.length;
        int ans = 0;
        if (S == 1) {
            char c = str[0];
            if (c == 'X' || c == '_' || (c >= '0' && c <= '9' && c == '0')) ans = 1;
        } else {
            ans += countPossibilities(2, 5);
            ans += countPossibilities(5, 0);
            ans += countPossibilities(7, 5);
            ans += countPossibilities(0, 0);
        }
        System.out.println(ans);
    }

    static int countPossibilities(int end1, int end2) {
        if (S == 2 && end1 == 0) return 0;
        int X_val = -1;
        if (str[S - 2] == 'X') {
            X_val = end1;
        } else if (str[S - 2] != '_') {
            if (getValue(S - 2) != end1) return 0;
        }
        if (str[S - 1] == 'X') {
            if (X_val != -1 && end2 != X_val) return 0;
            else X_val = end2;
        } else if (str[S - 1] != '_') {
            if (getValue(S - 1) != end2) return 0;
        }
        long total = 1;
        for (int i = 0; i < S - 2; i++) {
            if (i == 0) {
                if (str[i] == 'X' && X_val == 0) return 0;
                if (getValue(0) == 0) return 0;
            }
            if (str[i] == '_') {
                total *= (i == 0) ? 9 : 10;
            } else if (str[i] == 'X') {
                if (X_val != -1) continue;
                X_val = 10;
                total *= (i == 0) ? 9 : 10;
            }
        }
        return (int) total;
    }

    static boolean isDigit(int pos) {
        char c = str[pos];
        return c != '_' && c != 'X';
    }

