				boolean shit = (s[n - 1] != '_' && s[n - 1] != 'X' && s[n - 1] != '0');
				shit |= s[n - 2] != '_' && s[n - 2] != 'X' && s[n - 2] != '5';
				shit |= (s[n - 1] == 'X' && s[n - 2] == 'X');
				
				if (!shit) {
					
					if (s[n - 1] == 'X') {
						
						// replace each by 0
						for (int i = 0; i < n; i++)
							if (s[i] == 'X')
								s[i] = '0';
						
					} else if (s[n - 2] == 'X') {
						
						// replace each by 5
						for (int i = 0; i < n; i++)
							if (s[i] == 'X')
								s[i] = '5';
					}
					
					s[n - 1] = '0';
					s[n - 2] = '5';
					
					answer += check("50".toCharArray(), s);
					
					for (int num = 0; num < 1e6; num++) {
						char[] tgt = (Integer.toString(num) + "50").toCharArray();
						answer += check(tgt, s);
					}
				}
			}
			
			{
				// 75
				char[] s = sOG.clone();
				
				boolean shit = (s[n - 1] != '_' && s[n - 1] != 'X' && s[n - 1] != '5');
				shit |= s[n - 2] != '_' && s[n - 2] != 'X' && s[n - 2] != '7';
				shit |= (s[n - 1] == 'X' && s[n - 2] == 'X');
				
				if (!shit) {
					
					if (s[n - 1] == 'X') {
						
						// replace each by 5
						for (int i = 0; i < n; i++)
							if (s[i] == 'X')
								s[i] = '5';
						
					} else if (s[n - 2] == 'X') {
						
						// replace each by 7
						for (int i = 0; i < n; i++)
							if (s[i] == 'X')
								s[i] = '7';
					}
					
					s[n - 1] = '5';
					s[n - 2] = '7';
					
					answer += check("75".toCharArray(), s);
					
					for (int num = 0; num < 1e6; num++) {
						char[] tgt = (Integer.toString(num) + "75").toCharArray();
						answer += check(tgt, s);
					}
				}
			}
			
			out.println(answer);
			
			// out.println(check("34593925".toCharArray(), sOG));
		}
		out.close();
	}
	
	static int check(char[] tgt, char[] src) {
		int n = tgt.length;
		if (src.length != n) return 0;
		
		
		// 'X' check
		char xDig = 0;
		for (int i = 0; i < n; i++)
			if (src[i] == 'X') {
				if (xDig == 0) {
					xDig = tgt[i];
				} else {
					if (tgt[i] != xDig) return 0;
				}
			}
		// assert all 'X's have same digit;
		
		
		
		// no leading zeroes plz
		if (tgt[0] == '0') return 0;
		
		// all non _s have to be equal
		for (int i = 0; i < n; i++)
			if (src[i] != '_' && src[i] != 'X' && tgt[i] != src[i]) return 0;
		
		return 1;
	}
	
