import java.io.*;
import java.util.*;
public class Main {
    public static void main(String args[])
    {
        FastReader input=new FastReader();
        PrintWriter out=new PrintWriter(System.out);
        int T=1;
        while(T-->0)
        {
            String s=input.next();
            if(s.length()==1)
            {
                if(s.charAt(0)=='0' || s.charAt(0)=='_' || s.charAt(0)=='X') out.println(1);
                else out.println(0);
            }
            else
            {
                int f=0;
                for(int i=0;i<s.length();i++)
                {
                    if(s.charAt(i)=='X')
                    {
                        f=1;
                        break;
                    }
                }
                if(f==0)
                {
                    out.println(fun(s));
                }
                else
                {
                    int sum=0;
                    for(int i=0;i<10;i++)
                    {
                        char ch[]=s.toCharArray();
                        for(int j=0;j<s.length();j++)
                        {
                            if(ch[j]=='X')
                            {
                                ch[j]=(char)(i+'0');
                            }
                        }
                        String str=String.copyValueOf(ch);
                        sum+=fun(str);
                    }
                    out.println(sum);
                }
            }
        }
        out.close();
    }
    public static int fun(String s)
    {
        int n=s.length();
        int p=0;
        if(s.charAt(0)!='0')p=1;
        for(int i=0;i<n-2;i++)
        {
            if(s.charAt(i)=='_')
            {
                if(i==0) p*=9;
                else p*=10;
            }
        }
        int p1=0;
        if(s.charAt(n-1)=='_' && s.charAt(n-2)=='_')
        {
            p1=4;
            if(n==2) p1=3;
        }
        else if(s.charAt(n-1)=='_')
        {
            if(s.charAt(n-2)=='0' || s.charAt(n-2)=='5' || s.charAt(n-2)=='2' || s.charAt(n-2)=='7') p1=1;
        }
        else if(s.charAt(n-2)=='_')
        {
            if(s.charAt(n-1)=='0')
            {
                p1=2;
                if(n==2) p1=1;
            }
            else if(s.charAt(n-1)=='5')
            {
                p1=2;
            }
        }
        else
        {
            int val=Integer.valueOf(s.substring(n-2));
            if(val%25==0) p1=1;
        }
        int pro=p*p1;
        return pro;
    }
    static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;
        public FastReader()
        {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt()
        {
            return Integer.parseInt(next());
        }
        long nextLong()
        {
            return Long.parseLong(next());
        }
        double nextDouble()
        {
            return Double.parseDouble(next());
        }
        String nextLine()
        {
            String str="";
            try
            {
                str=br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader input = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        int T = 1;
        while (T-- > 0) {
            String s = input.next();
            if (s.length() == 1) {
                char c = s.charAt(0);
                if (c == '0' || c == '_' || c == 'X') {
                    out.println(1);
                } else {
                    out.println(0);
                }
            } else {
                boolean hasX = false;
                for (int i = 0; i < s.length(); i++) {
                    if (s.charAt(i) == 'X') {
                        hasX = true;
                        break;
                    }
                }
                if (!hasX) {
                    out.println(computeValue(s));
                } else {
                    int total = 0;
                    for (int digit = 0; digit < 10; digit++) {
                        char[] chars = s.toCharArray();
                        for (int j = 0; j < chars.length; j++) {
                            if (chars[j] == 'X') {
                                chars[j] = (char) ('0' + digit);
                            }
                        }
                        total += computeValue(new String(chars));
                    }
                    out.println(total);
                }
            }
        }
        out.close();
    }

    public static int computeValue(String s) {
        int n = s.length();
        int ways = 0;
        if (s.charAt(0) != '0') {
            ways = 1;
        }
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                if (i == 0) {
                    ways *= 9;
                } else {
                    ways *= 10;
                }
            }
        }
        int suffixWays = 0;
        if (s.charAt(n - 1) == '_' && s.charAt(n - 2) == '_') {
            suffixWays = 4;
            if (n == 2) {
                suffixWays = 3;
            }
        } else if (s.charAt(n - 1) == '_') {
            char prev = s.charAt(n - 2);
            if (prev == '0' || prev == '5' || prev == '2' || prev == '7') {
                suffixWays = 1;
            }
        } else if (s.charAt(n - 2) == '_') {
            char last = s.charAt(n - 1);
            if (last == '0') {
                suffixWays = 2;
                if (n == 2) {
                    suffixWays = 1;
                }
            } else if (last == '5') {
                suffixWays = 2;
            }
        } else {
            int lastTwo = Integer.parseInt(s.substring(n - 2));
            if (lastTwo % 25 == 0) {
                suffixWays = 1;
            }
        }
        return ways * suffixWays;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
