import java.util.*;
import java.io.*;

public class E {

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int l = s.length();

        if (l < 2) {
            System.out.println(s.equals("0") || s.equals("_") || s.equals("X") ? 1 : 0);
            sc.close();
            return;
        }

        if (l == 2) {
            int count = 0;
            for (int i = 10; i <= 95; i += 5) {
                if (i % 25 != 0) continue;
                String str = String.valueOf(i);
                if (matchTwoCharPattern(s, str)) count++;
            }
            System.out.println(count);
            sc.close();
            return;
        }

        int start = (int) Math.pow(10, l - 1);
        int end = (int) Math.pow(10, l);
        int count = 0;

        for (int num = start; num < end; num += 25) {
            String numStr = String.valueOf(num);
            if (matchesPattern(s, numStr)) count++;
        }

        System.out.println(count);
        sc.close();
    }

    private static boolean matchTwoCharPattern(String pattern, String candidate) {
        char c0 = pattern.charAt(0), c1 = pattern.charAt(1);
        char s0 = candidate.charAt(0), s1 = candidate.charAt(1);

        if (Character.isDigit(c0)) {
            if (Character.isDigit(c1)) {
                return pattern.equals(candidate);
            } else if (c1 == '_') {
                return c0 == s0;
            }
        } else if (c0 == '_') {
            if (Character.isDigit(c1)) {
                return c1 == s1;
            } else if (c1 == '_') {
                return true;
            }
        } else if (c0 == 'X') {
            if (Character.isDigit(c1)) {
                return c1 == s1;
            } else if (c1 == '_') {
                return true;
            }
        }
        return false;
    }

    private static boolean matchesPattern(String pattern, String candidate) {
        Set<Character> seenDigits = new HashSet<>();
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            char c = candidate.charAt(i);
            if (p == '_') continue;
            if (p == 'X') {
                seenDigits.add(c);
                if (seenDigits.size() > 1) return false;
            } else if (p != c) {
                return false;
            }
        }
        return seenDigits.size() <= 1;
    }
}

import java.util.*;
import java.io.*;

public class E {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int n = s.length();

        if (n == 1) {
            System.out.println(isSingleCharValid(s) ? 1 : 0);
            return;
        }

        if (n == 2) {
            System.out.println(countTwoDigitMatches(s));
            return;
        }

        int low = (int) Math.pow(10, n - 1);
        int high = (int) Math.pow(10, n);
        int cnt = 0;

        for (int num = low; num < high; num += 25) {
            String numStr = Integer.toString(num);
            if (isValidPattern(s, numStr)) cnt++;
        }

        System.out.println(cnt);
    }

    private static boolean isSingleCharValid(String s) {
        return s.equals("0") || s.equals("_") || s.equals("X");
    }

    private static int countTwoDigitMatches(String pat) {
        int cnt = 0;
        for (int i = 25; i <= 95; i += 25) {
            String cand = String.format("%02d", i);
            if (matchTwo(pat, cand)) cnt++;
        }
        return cnt;
    }

    private static boolean matchTwo(String p, String c) {
        char a = p.charAt(0), b = p.charAt(1);
        char x = c.charAt(0), y = c.charAt(1);

        if (Character.isDigit(a)) {
            if (Character.isDigit(b)) return p.equals(c);
            if (b == '_') return a == x;
        } else if (a == '_') {
            if (Character.isDigit(b)) return b == y;
            if (b == '_') return true;
        } else if (a == 'X') {
            if (Character.isDigit(b)) return b == y;
            if (b == '_') return true;
        }
        return false;
    }

    private static boolean isValidPattern(String pat, String cand) {
        Set<Character> digits = new HashSet<>();
        for (int i = 0; i < pat.length(); i++) {
            char pc = pat.charAt(i);
            char cc = cand.charAt(i);
            if (pc == '_') continue;
            if (pc == 'X') {
                digits.add(cc);
                if (digits.size() > 1) return false;
            } else if (pc != cc) {
                return false;
            }
        }
        return digits.size() <= 1;
    }
}

