public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader bu = new BufferedReader(new InputStreamReader(System.in));
        String input = bu.readLine();
        char[] s = input.toCharArray();
        boolean hasX = false;
        int n = s.length;
        for (int i = 0; i < n; i++) {
            if (s[i] == 'X') hasX = true;
        }

        int ans = 0;
        char[] s2 = new char[n];

        for (int digit = 0; digit <= 9; digit++) {
            for (int i = 0; i < n; i++) {
                if (s[i] == 'X') {
                    s2[i] = (char) ('0' + digit);
                } else {
                    s2[i] = s[i];
                }
            }

            if (s2[0] == '0') continue;

            int[][] dp = new int[2][25];
            int cur = 0;
            dp[cur][0] = 1;

            for (int i = 0; i < n; i++) {
                int nextCur = cur ^ 1;
                for (int k = 0; k < 25; k++) dp[nextCur][k] = 0;

                int lo = 0, hi = 9;
                if (s2[i] != '_') {
                    lo = hi = s2[i] - '0';
                } else if (i == 0) {
                    lo = 1;
                }

                for (int k = 0; k < 25; k++) {
                    if (dp[cur][k] == 0) continue;
                    for (int d = lo; d <= hi; d++) {
                        int rem = (k * 10 + d) % 25;
                        dp[nextCur][rem] += dp[cur][k];
                    }
                }
                cur = nextCur;
            }

            ans += dp[cur][0];
            if (!hasX) break;
        }

        if (n == 1 && (s[0] == '_' || s[0] == 'X' || s[0] == '0')) ans++;
        System.out.println(ans);
    }
