public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int len = line.length();
        char[] input = line.toCharArray();

        boolean containsX = false;
        for (char c : input) {
            if (c == 'X') containsX = true;
        }

        int result = 0;
        char[] temp = new char[len];

        for (int d = 0; d <= 9; d++) {
            for (int i = 0; i < len; i++) {
                temp[i] = (input[i] == 'X') ? (char)('0' + d) : input[i];
            }

            if (temp[0] == '0') continue;

            int[][] memo = new int[2][25];
            int idx = 0;
            memo[idx][0] = 1;

            for (int i = 0; i < len; i++) {
                int nextIdx = idx ^ 1;
                Arrays.fill(memo[nextIdx], 0);

                int minDigit = 0, maxDigit = 9;
                if (temp[i] != '_') {
                    minDigit = maxDigit = temp[i] - '0';
                } else if (i == 0) {
                    minDigit = 1;
                }

                for (int r = 0; r < 25; r++) {
                    if (memo[idx][r] == 0) continue;
                    for (int digit = minDigit; digit <= maxDigit; digit++) {
                        int newRem = (r * 10 + digit) % 25;
                        memo[nextIdx][newRem] += memo[idx][r];
                    }
                }
                idx = nextIdx;
            }

            result += memo[idx][0];
            if (!containsX) break;
        }

        if (len == 1 && (input[0] == '_' || input[0] == 'X' || input[0] == '0')) {
            result++;
        }
        System.out.println(result);
    }
}

