public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        int length = line.length();
        char[] original = line.toCharArray();

        boolean hasX = false;
        for (char c : original) {
            if (c == 'X') hasX = true;
        }

        int count = 0;
        char[] replacement = new char[length];

        for (int value = 0; value <= 9; value++) {
            for (int i = 0; i < length; i++) {
                replacement[i] = (original[i] == 'X') ? (char)('0' + value) : original[i];
            }

            if (replacement[0] == '0') continue;

            int[][] state = new int[2][25];
            int current = 0;
            state[current][0] = 1;

            for (int i = 0; i < length; i++) {
                int next = current ^ 1;
                for (int r = 0; r < 25; r++) state[next][r] = 0;

                int low = 0, high = 9;
                if (replacement[i] != '_') {
                    low = high = replacement[i] - '0';
                } else if (i == 0) {
                    low = 1;
                }

                for (int r = 0; r < 25; r++) {
                    if (state[current][r] == 0) continue;
                    for (int digit = low; digit <= high; digit++) {
                        int remainder = (r * 10 + digit) % 25;
                        state[next][remainder] += state[current][r];
                    }
                }
                current = next;
            }

            count += state[current][0];
            if (!hasX) break;
        }

        if (length == 1 && (original[0] == '_' || original[0] == 'X' || original[0] == '0')) {
            count++;
        }
        System.out.println(count);
    }
}

