public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        double threshold = Double.parseDouble(parts[1]);

        int result = n;
        for (int i = 0; i <= n; i++) {
            if (probability(n, i) >= threshold) {
                result = i;
                break;
            }
        }
        System.out.println(result);
    }

    static int combination(int total, int choose) {
        if (choose > total || choose < 0) return 0;
        if (choose == 0 || choose == total) return 1;
        choose = Math.min(choose, total - choose);
        long res = 1;
        for (int i = 0; i < choose; i++) {
            res = res * (total - i) / (i + 1);
        }
        return (int) res;
    }

    static double probability(int n, int x) {
        int term1 = combination(x, 3) * combination(n - x, 0);
        int term2 = combination(x, 2) * combination(n - x, 1);
        int term3 = combination(x, 1) * combination(n - x, 2);
        double numerator = (3.0 / 6.0) * term3 + term1 + term2;
        return numerator / combination(n, 3);
    }
}

