public class Codeforces {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        double p = sc.nextDouble();
        sc.close();

        int ans = n;
        for (int i = 0; i <= n; i++) {
            if (calcProb(n, i) >= p) {
                ans = i;
                break;
            }
        }
        System.out.println(ans);
    }

    static int nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        if (r == 0 || r == n) return 1;
        int[] C = new int[r + 1];
        C[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = Math.min(i, r); j > 0; j--) {
                C[j] += C[j - 1];
            }
        }
        return C[r];
    }

    static double calcProb(int n, int x) {
        int c1 = nCr(x, 3) * nCr(n - x, 0);
        int c2 = nCr(x, 2) * nCr(n - x, 1);
        int c3 = nCr(x, 1) * nCr(n - x, 2);
        return (0.5 * c3 + c1 + c2) / (double) nCr(n, 3);
    }
}

