public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] input = reader.readLine().trim().split("\\s+");
        int total = Integer.parseInt(input[0]);
        double limit = Double.parseDouble(input[1]);
        reader.close();

        int answer = total;
        for (int k = 0; k <= total; k++) {
            if (chance(total, k) >= limit) {
                answer = k;
                break;
            }
        }
        System.out.println(answer);
    }

    static int choose(int n, int k) {
        if (k < 0 || k > n) return 0;
        if (k == 0 || k == n) return 1;
        k = Math.min(k, n - k);
        int result = 1;
        for (int i = 1; i <= k; i++) {
            result = result * (n - i + 1) / i;
        }
        return result;
    }

    static double chance(int n, int x) {
        int a = choose(x, 3) * choose(n - x, 0);
        int b = choose(x, 2) * choose(n - x, 1);
        int c = choose(x, 1) * choose(n - x, 2);
        return (a + b + 0.5 * c) / (double) choose(n, 3);
    }
}

