    static int comb(int n, int r) {
        if (r < 0 || r > n) return 0;
        if (r == 0 || r == n) return 1;
        r = Math.min(r, n - r);
        int val = 1;
        for (int i = 0; i < r; i++) {
            val = val * (n - i) / (i + 1);
        }
        return val;
    }

    static double getProbability(int n, int x) {
        int term1 = comb(x, 3) * comb(n - x, 0);
        int term2 = comb(x, 2) * comb(n - x, 1);
        int term3 = comb(x, 1) * comb(n - x, 2);
        return (term1 + term2 + term3 * 0.5) / (double) comb(n, 3);
    }
