import java.io.*;
import java.util.*;

public class I {

    private static final boolean DEBUG = true;
    private static final String INPUT_BASE = "I";

    public static void main(String[] args) throws Exception {
        FastScanner scanner = DEBUG ? new FastScanner(System.in) : new FastScanner(INPUT_BASE + ".in");
        PrintWriter writer = DEBUG ? new PrintWriter(System.out) : new PrintWriter(new FileWriter(INPUT_BASE + ".out"));

        double n = Double.parseDouble(scanner.nextString());
        double p = Double.parseDouble(scanner.nextString());

        outer: for (int i = 0; i <= n; ++i) {
            double numerator = (double)i * (i - 1) * (i - 2) / 6;
            numerator += (double)i * (i - 1) * (n - i) / 2;
            numerator += (double)i * (n - i) * (n - i - 1) / 4;
            double denominator = n * (n - 1) * (n - 2) / 6;
            double ratio = numerator / denominator;

            if (ratio >= p) {
                writer.println(i);
                break outer;
            }
        }

        writer.close();
    }

    static class BIT {
        final int[] fenwick;

        BIT(int size) {
            fenwick = new int[size + 8];
        }

        void add(int idx, int value) {
            for (++idx; idx < fenwick.length; idx += idx & -idx) {
                fenwick[idx] ^= value;
            }
        }

        int prefix(int idx) {
            int res = 0;
            for (++idx; idx > 0; idx -= idx & -idx) {
                res ^= fenwick[idx];
            }
            return res;
        }

        int interval(int left, int right) {
            return prefix(right) ^ prefix(left - 1);
        }
    }

    static ArrayList<Integer>[] graph;
    static int[] entry, exit;
    static int[][] ancestorTable;
    static int timestamp;

    static void setupLCA(int root) {
        timestamp = 0;
        entry = new int[graph.length];
        exit = new int[graph.length];
        int height = (int)(Math.log(graph.length) / Math.log(2)) + 1;
        ancestorTable = new int[graph.length][height];

        dfsLCA(root, root);
    }

    static void dfsLCA(int node, int parent) {
        entry[node] = ++timestamp;
        ancestorTable[node][0] = parent;
        for (int level = 1; level < ancestorTable[node].length; ++level) {
            ancestorTable[node][level] = ancestorTable[ancestorTable[node][level - 1]][level - 1];
        }
        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                dfsLCA(neighbor, node);
            }
        }
        exit[node] = ++timestamp;
    }

    static boolean isAncestor(int u, int v) {
        return entry[u] <= entry[v] && exit[u] >= exit[v];
    }

    static int lowestCommonAncestor(int a, int b) {
        if (isAncestor(a, b)) return a;
        if (isAncestor(b, a)) return b;

        int log = ancestorTable[0].length - 1;
        while (log >= 0) {
            if (!isAncestor(ancestorTable[a][log], b)) {
                a = ancestorTable[a][log];
            }
            --log;
        }
        return ancestorTable[a][0];
    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1 << 16];
        private int cur, len;

        public FastScanner(InputStream input) throws IOException {
            stream = input;
        }

        public FastScanner(String file) throws IOException {
            stream = new FileInputStream(file);
        }

        private int read() throws IOException {
            if (cur >= len) {
                len = stream.read(buf);
                cur = 0;
                if (len <= 0) return -1;
            }
            return buf[cur++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') c = read();
            boolean neg = c == '-';
            if (neg) c = read();
            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + c - '0';
                c = read();
            }
            return neg ? -val : val;
        }

        public long nextLong() throws IOException {
            int c = read();
            while (c <= ' ') c = read();
            boolean neg = c == '-';
            if (neg) c = read();
            long val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + c - '0';
                c = read();
            }
            return neg ? -val : val;
        }

        public String nextString() throws IOException {
            int c = read();
            while (c <= ' ') c = read();
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char)c);
                c = read();
            }
            return sb.toString();
        }
    }
}

