public class I {
    private static final boolean DEBUG_MODE = true;
    private static final String BASE_NAME = "I";

    public static void main(String[] args) throws Exception {
        var scanner = DEBUG_MODE ? new MyScanner(System.in) : new MyScanner(BASE_NAME + ".in");
        var writer = DEBUG_MODE ? new PrintWriter(System.out, true) : new PrintWriter(new FileWriter(BASE_NAME + ".out"));

        double N = Double.parseDouble(scanner.next());
        double P = Double.parseDouble(scanner.next());

        outer:
        for (int i = 0; i <= N; i++) {
            double comb = (double)i * (i - 1) * (i - 2) / 6;
            comb += (double)i * (i - 1) * (N - i) / 2;
            comb += (double)i * (N - i) * (N - i - 1) / 4;
            double total = N * (N - 1) * (N - 2) / 6;
            if (comb / total >= P) {
                writer.println(i);
                break outer;
            }
        }

        writer.close();
    }

    static class Fenwick {
        private final int[] arr;

        Fenwick(int n) {
            arr = new int[n + 10];
        }

        void update(int pos, int val) {
            for (pos++; pos < arr.length; pos += pos & -pos) {
                arr[pos] ^= val;
            }
        }

        int get(int pos) {
            int res = 0;
            for (pos++; pos > 0; pos -= pos & -pos) {
                res ^= arr[pos];
            }
            return res;
        }

        int getRange(int l, int r) {
            return get(r) ^ get(l - 1);
        }
    }

    static class LCA {
        static int[][] up;
        static int[] startTime, endTime;
        static int timer;
        static ArrayList<Integer>[] adj;

        static void init(int root) {
            timer = 0;
            int n = adj.length;
            startTime = new int[n];
            endTime = new int[n];
            int k = 32 - Integer.numberOfLeadingZeros(n);
            up = new int[n][k];
            dfs(root, root);
        }

        static void dfs(int v, int parent) {
            startTime[v] = ++timer;
            up[v][0] = parent;
            for (int j = 1; j < up[v].length; j++)
                up[v][j] = up[up[v][j - 1]][j - 1];
            for (int u : adj[v])
                if (u != parent) dfs(u, v);
            endTime[v] = ++timer;
        }

        static boolean isAncestor(int u, int v) {
            return startTime[u] <= startTime[v] && endTime[u] >= endTime[v];
        }

        static int query(int a, int b) {
            if (isAncestor(a, b)) return a;
            if (isAncestor(b, a)) return b;
            for (int i = up[0].length - 1; i >= 0; i--)
                if (!isAncestor(up[a][i], b)) a = up[a][i];
            return up[a][0];
        }
    }

    static class MyScanner {
        private final InputStream in;
        private final byte[] buf = new byte[1 << 16];
        private int ptr, len;

        MyScanner(InputStream is) { in = is; }
        MyScanner(String path) throws IOException { in = new FileInputStream(path); }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buf);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        String next() throws IOException {
            int c;
            while ((c = read()) <= 32);
            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char)c);
                c = read();
            }
            return sb.toString();
        }
    }
}

import java.io.*;
