public class I {
    public static final boolean isDebug = true;
    public static final String FILE_ROOT = "I";

    public static void main(String[] args) throws Exception {
        Scanner scanner;
        PrintWriter writer;
        if (isDebug) {
            scanner = new Scanner(System.in);
            writer = new PrintWriter(System.out);
        } else {
            scanner = new Scanner(new File(FILE_ROOT + ".in"));
            writer = new PrintWriter(new BufferedWriter(new FileWriter(FILE_ROOT + ".out")));
        }

        double n = Double.parseDouble(scanner.next());
        double p = Double.parseDouble(scanner.next());

        int result = 0;
        for (int i = 0; i <= n; i++) {
            double numer = i * (i - 1.0) * (i - 2.0) / 6.0;
            numer += i * (i - 1.0) * (n - i) / 2.0;
            numer += i * (n - i) * (n - i - 1.0) / 4.0;
            double denom = n * (n - 1.0) * (n - 2.0) / 6.0;
            double fraction = numer / denom;

            if (fraction >= p) {
                result = i;
                break;
            }
        }

        writer.println(result);
        writer.close();
    }

    static class FenwickTree {
        private final int[] data;

        FenwickTree(int size) {
            data = new int[size + 12];
        }

        void pointAdd(int idx, int delta) {
            for (int i = idx + 1; i < data.length; i += i & -i)
                data[i] ^= delta;
        }

        int prefixXor(int idx) {
            int res = 0;
            for (int i = idx + 1; i > 0; i -= i & -i)
                res ^= data[i];
            return res;
        }

        int rangeXor(int l, int r) {
            return prefixXor(r) ^ prefixXor(l - 1);
        }
    }

    static class TreeTools {
        static ArrayList<Integer>[] tree;
        static int[][] jmp;
        static int[] enter, leave;
        static int timer;

        static void prepare(int root) {
            int n = tree.length;
            enter = new int[n];
            leave = new int[n];
            int depth = 32 - Integer.numberOfLeadingZeros(n - 1);
            jmp = new int[n][depth];
            timer = 0;
            explore(root, root);
        }

        static void explore(int u, int parent) {
            enter[u] = ++timer;
            jmp[u][0] = parent;
            for (int j = 1; j < jmp[u].length; ++j)
                jmp[u][j] = jmp[jmp[u][j - 1]][j - 1];
            for (int v : tree[u])
                if (v != parent) explore(v, u);
            leave[u] = ++timer;
        }

        static boolean ancestor(int a, int b) {
            return enter[a] <= enter[b] && leave[a] >= leave[b];
        }

        static int getLCA(int x, int y) {
            if (ancestor(x, y)) return x;
            if (ancestor(y, x)) return y;
            for (int k = jmp[0].length - 1; k >= 0; --k)
                if (!ancestor(jmp[x][k], y))
                    x = jmp[x][k];
            return jmp[x][0];
        }
    }

    static class Scanner {
        private final BufferedReader reader;

        Scanner(InputStream is) {
            reader = new BufferedReader(new InputStreamReader(is));
        }

        Scanner(File f) throws FileNotFoundException {
            reader = new BufferedReader(new FileReader(f));
        }

        String next() throws IOException {
            String line;
            while ((line = reader.readLine()) != null) {
                StringTokenizer st = new StringTokenizer(line);
                if (st.hasMoreTokens()) return st.nextToken();
            }
            return "";
        }
    }
}

