class ST {
    int n;
    Node[] st;
    ST(int n) { this.n = n; st = new Node[4 * (Integer.highestOneBit(n) << 1)]; }
    void build(Node[] nodes) { build(0, 0, n - 1, nodes); }
    private void build(int id, int l, int r, Node[] nodes) {
        if (l == r) { st[id] = nodes[l]; return; }
        int mid = (l + r) >>> 1;
        build((id << 1) + 1, l, mid, nodes);
        build((id << 1) + 2, mid + 1, r, nodes);
        st[id] = merge(st[(id << 1) + 1], st[(id << 1) + 2]);
    }
    void update(int i, Node node) { update(0, 0, n - 1, i, node); }
    private void update(int id, int l, int r, int i, Node node) {
        if (i < l || r < i) return;
        if (l == r) { st[id] = node; return; }
        int mid = (l + r) >>> 1;
        update((id << 1) + 1, l, mid, i, node);
        update((id << 1) + 2, mid + 1, r, i, node);
        st[id] = merge(st[(id << 1) + 1], st[(id << 1) + 2]);
    }
    Node query(int x, int y) { return query(0, 0, n - 1, x, y); }
    private Node query(int id, int l, int r, int x, int y) {
        if (x > r || y < l) return new Node();
        if (x <= l && r <= y) return st[id];
        int mid = (l + r) >>> 1;
        return merge(query((id << 1) + 1, l, mid, x, y), query((id << 1) + 2, mid + 1, r, x, y));
    }
    Node merge(Node a, Node b) {
        if (a == null) return b;
        if (b == null) return a;
        int overlap = Math.min(a.open, b.close);
        return new Node(a.data + b.data + 2 * overlap, a.open + b.open - overlap, a.close + b.close - overlap);
    }
}

