        long total = (long) n * (n - 1) * (n - 2) / 6;
        double favorable = 0.0;
        if (m >= 3) favorable += (long) m * (m - 1) * (m - 2) / 6;
        if (m >= 2) favorable += (long) m * (m - 1) / 2 * (n - m);
        if (m >= 1 && n - m >= 2) favorable += 0.5 * m * (long) (n - m) * (n - m - 1) / 2;
        return favorable / total;
    }

