import java.util.*;
import java.io.*;

public class LuckyTickets {
    private static final int MOD = 998244353;
    private static final int ROOT = 15311432;
    private static final int INVROOT = 469870224;

    private static int bitReverse(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long modPow(int base, int exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static long modInverse(int a) {
        return modPow(a, MOD - 2);
    }

    private static void performNTT(long[] data, int logN, boolean isInverse) {
        int root = isInverse ? INVROOT : ROOT;
        long omega = modPow(root, 1 << (23 - logN));
        long[] omegaPowers = new long[logN];
        omegaPowers[logN - 1] = omega;
        for (int i = logN - 1; i > 0; i--) {
            omegaPowers[i - 1] = (omegaPowers[i] * omegaPowers[i]) % MOD;
        }
        for (int level = 0; level < logN; level++) {
            int segmentLength = 1 << level;
            for (int start = 0; start < data.length; start += 2 * segmentLength) {
                long currentOmega = 1;
                for (int offset = 0; offset < segmentLength; offset++) {
                    long even = data[start + offset];
                    long odd = (currentOmega * data[start + offset + segmentLength]) % MOD;
                    data[start + offset] = (even + odd) % MOD;
                    data[start + offset + segmentLength] = ((even - odd) % MOD + MOD) % MOD;
                    currentOmega = (currentOmega * omegaPowers[level]) % MOD;
                }
            }
        }
        if (isInverse) {
            long invLen = modInverse(data.length);
            for (int i = 0; i < data.length; i++) {
                data[i] = (data[i] * invLen) % MOD;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int halfSum = scanner.nextInt() / 2;
        int count = scanner.nextInt();
        int[] values = new int[count];
        for (int i = 0; i < count; i++) {
            values[i] = scanner.nextInt();
        }
        Arrays.sort(values);
        int requiredSize = halfSum * values[count - 1] + 2;
        int logSize = 0;
        int size = 1;
        while (size < requiredSize) {
            size <<= 1;
            logSize++;
        }
        long[] polynomial = new long[size];
        for (int val : values) {
            polynomial[bitReverse(val, logSize)] = 1;
        }
        performNTT(polynomial, logSize, false);
        for (int i = 0; i < size; i++) {
            polynomial[i] = modPow((int) polynomial[i], halfSum);
        }
        long[] temp = new long[size];
        for (int i = 0; i < size; i++) {
            temp[bitReverse(i, logSize)] = (polynomial[i] % MOD + MOD) % MOD;
        }
        polynomial = temp;
        performNTT(polynomial, logSize, true);
        long answer = 0;
        for (int i = 0; i < size; i++) {
            answer = (answer + polynomial[i] * polynomial[i]) % MOD;
        }
        long invSize = modInverse(size);
        System.out.println((answer * invSize % MOD) * invSize % MOD);
    }
}

