public class LuckyTickets {
    static final int MOD = 998244353;
    static final int ROOT = 15311432;
    static final int INVROOT = 469870224;

    static int bitReverse(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    static long modPow(int b, int e) {
        long r = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return r;
    }

    static long modInv(int x) {
        return modPow(x, MOD - 2);
    }

    static void ntt(long[] a, int lg, boolean inv) {
        int br = inv ? INVROOT : ROOT;
        long w = modPow(br, 1 << (23 - lg));
        long[] ws = new long[lg];
        ws[lg - 1] = w;
        for (int i = lg - 1; i > 0; i--) ws[i - 1] = (ws[i] * ws[i]) % MOD;
        for (int s = 0; s < lg; s++) {
            int len = 1 << s;
            for (int st = 0; st < a.length; st += 2 * len) {
                long cur = 1;
                for (int j = st; j < st + len; j++) {
                    long t = (cur * a[j + len]) % MOD;
                    long u = a[j];
                    a[j] = (u + t) % MOD;
                    a[j + len] = ((u - t) % MOD + MOD) % MOD;
                    cur = (cur * ws[s]) % MOD;
                }
            }
        }
        if (inv) {
            long invN = modInv(a.length);
            for (int i = 0; i < a.length; i++) a[i] = (a[i] * invN) % MOD;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] arr = new int[m];
        for (int i = 0; i < m; i++) arr[i] = sc.nextInt();
        Arrays.sort(arr);
        int minLen = n * arr[m - 1] + 2;
        int lg = 0, len = 1;
        while (len < minLen) {
            len <<= 1;
            lg++;
        }
        long[] poly = new long[len];
        for (int v : arr) poly[bitReverse(v, lg)] = 1;
        ntt(poly, lg, false);
        for (int i = 0; i < len; i++) poly[i] = modPow((int) poly[i], n);
        long[] buf = new long[len];
        for (int i = 0; i < len; i++) buf[bitReverse(i, lg)] = (poly[i] % MOD + MOD) % MOD;
        poly = buf;
        ntt(poly, lg, true);
        long sum = 0;
        for (int i = 0; i < len; i++) sum = (sum + poly[i] * poly[i]) % MOD;
        long invLen = modInv(len);
        System.out.println((sum * invLen % MOD) * invLen % MOD);
    }
}

import java.util.*;
import java.io.*;

public class LuckyTickets {
    private static final int MOD = 998244353;
    private static final int ROOT = 15311432;
    private static final int INVROOT = 469870224;

    private static int bitReverse(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long modPow(int base, int exponent) {
        long result = 1;
        base %= MOD;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    private static long modInverse(int value) {
        return modPow(value, MOD - 2);
    }

    private static void performNTT(long[] input, int log2Length, boolean isInverse) {
        int baseRoot = isInverse ? INVROOT : ROOT;
        long omega = modPow(baseRoot, 1 << (23 - log2Length));
        long[] omegaTable = new long[log2Length];
        omegaTable[log2Length - 1] = omega;
        for (int i = log2Length - 1; i > 0; i--) {
            omegaTable[i - 1] = (omegaTable[i] * omegaTable[i]) % MOD;
        }
        for (int level = 0; level < log2Length; level++) {
            int segmentSize = 1 << level;
            for (int blockStart = 0; blockStart < input.length; blockStart += 2 * segmentSize) {
                long currentOmega = 1;
                for (int offset = 0; offset < segmentSize; offset++) {
                    long evenComponent = input[blockStart + offset];
                    long oddComponent = (currentOmega * input[blockStart + offset + segmentSize]) % MOD;
                    input[blockStart + offset] = (evenComponent + oddComponent) % MOD;
                    input[blockStart + offset + segmentSize] = ((evenComponent - oddComponent) % MOD + MOD) % MOD;
                    currentOmega = (currentOmega * omegaTable[level]) % MOD;
                }
            }
        }
        if (isInverse) {
            long inverseLength = modInverse(input.length);
            for (int i = 0; i < input.length; i++) {
                input[i] = (input[i] * inverseLength) % MOD;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int halfSum = scanner.nextInt() / 2;
        int numberOfValues = scanner.nextInt();
        int[] values = new int[numberOfValues];
        for (int i = 0; i < numberOfValues; i++) {
            values[i] = scanner.nextInt();
        }
        Arrays.sort(values);
        int minimumSize = halfSum * values[numberOfValues - 1] + 2;
        int log2Size = 0;
        int size = 1;
        while (size < minimumSize) {
            size <<= 1;
            log2Size++;
        }
        long[] polynomial = new long[size];
        for (int value : values) {
            polynomial[bitReverse(value, log2Size)] = 1;
        }
        performNTT(polynomial, log2Size, false);
        for (int i = 0; i < size; i++) {
            polynomial[i] = modPow((int) polynomial[i], halfSum);
        }
        long[] buffer = new long[size];
        for (int i = 0; i < size; i++) {
            buffer[bitReverse(i, log2Size)] = (polynomial[i] % MOD + MOD) % MOD;
        }
        polynomial = buffer;
        performNTT(polynomial, log2Size, true);
        long total = 0;
        for (int i = 0; i < size; i++) {
            total = (total + polynomial[i] * polynomial[i]) % MOD;
        }
        long inverseSize = modInverse(size);
        System.out.println((total * inverseSize % MOD) * inverseSize % MOD);
    }
}

