public class CF1096G {
    static final int MD = 998244353;
    static long[] roots, rootsInv;

    static long modPow(long base, int exp) {
        long result = 1;
        base %= MD;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % MD;
            base = (base * base) % MD;
            exp >>= 1;
        }
        return result;
    }

    static void initialize() {
        roots = new long[21];
        rootsInv = new long[21];
        for (int h = 0; h <= 20; h++) {
            int exp = (MD - 1) >> h;
            roots[h] = modPow(3, exp);
            rootsInv[h] = modPow(3, MD - 1 - exp);
        }
    }

    static void ntt(int[] a, int n, boolean invert) {
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n;
            while ((j ^= bit) < bit) bit >>= 1;
            if (i < j) {
                int temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }

        for (int len = 2, h = 0; len <= n; len <<= 1, h++) {
            long w = invert ? rootsInv[h + 1] : roots[h + 1];
            for (int i = 0; i < n; i += len) {
                long wj = 1;
                for (int j = 0; j < len / 2; j++) {
                    int u = a[i + j];
                    int v = (int)((a[i + j + len / 2] * wj) % MD);
                    a[i + j] = (int)((u + v) % MD);
                    a[i + j + len / 2] = (int)((u - v + MD) % MD);
                    wj = (wj * w) % MD;
                }
            }
        }

        if (invert) {
            long invN = modPow(n, MD - 2);
            for (int i = 0; i < n; i++)
                a[i] = (int)((a[i] * invN) % MD);
        }
    }

    public static void main(String[] args) throws IOException {
        initialize();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken()) / 2;
        int k = Integer.parseInt(st.nextToken());

        int size = 1;
        while (size < n * 9 + 1) size *= 2;

        int[] poly = new int[size];
        st = new StringTokenizer(br.readLine());
        while (k-- > 0) {
            int d = Integer.parseInt(st.nextToken());
            poly[d] = 1;
        }

        ntt(poly, size, false);
        for (int i = 0; i < size; i++)
            poly[i] = (int)modPow(poly[i], n);
        ntt(poly, size, true);

        long result = 0;
        for (int i = 0; i <= n * 9; i++) {
            long val = poly[i];
            result = (result + val * val) % MD;
        }
        System.out.println(result);
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class CF1096G {
    private static final int MOD = 998244353;
    private static long[] w, w_inv;

    private static long fastPow(long base, int exp) {
        long res = 1;
        base %= MOD;
        while (exp != 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>>= 1;
        }
        return res;
    }

    private static void setup() {
        w = new long[21];
        w_inv = new long[21];
        for (int i = 0; i <= 20; i++) {
            int e1 = (MOD - 1) >>> i;
            int e2 = (MOD - 1) - e1;
            w[i] = fastPow(3, e1);
            w_inv[i] = fastPow(3, e2);
        }
    }

    private static void transform(int[] arr, int len, boolean inverse) {
        for (int i = 1, rev = 0; i < len; i++) {
            int bit = len >> 1;
            for (; (rev ^= bit) < bit; bit >>= 1);
            if (i < rev) {
                int tmp = arr[i];
                arr[i] = arr[rev];
                arr[rev] = tmp;
            }
        }

        for (int step = 1; step < len; step <<= 1) {
            long omega = inverse ? w_inv[Integer.numberOfTrailingZeros(step + 1)] : w[Integer.numberOfTrailingZeros(step + 1)];
            for (int i = 0; i < len; i += step << 1) {
                long wj = 1;
                for (int j = 0; j < step; j++) {
                    int x = arr[i + j];
                    int y = (int)((arr[i + j + step] * wj) % MOD);
                    arr[i + j] = (int)((x + y) % MOD);
                    arr[i + j + step] = (int)((x - y + MOD) % MOD);
                    wj = (wj * omega) % MOD;
                }
            }
        }

        if (inverse) {
            long invLen = fastPow(len, MOD - 2);
            for (int i = 0; i < len; i++) arr[i] = (int)((arr[i] * invLen) % MOD);
        }
    }

    public static void main(String[] args) throws Exception {
        setup();
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(in.readLine());
        int halfN = Integer.parseInt(tokenizer.nextToken()) / 2;
        int k = Integer.parseInt(tokenizer.nextToken());

        int polySize = 1;
        while (polySize < halfN * 9 + 1) polySize <<= 1;

        int[] coefficients = new int[polySize];
        tokenizer = new StringTokenizer(in.readLine());
        while (k-- > 0) {
            int digit = Integer.parseInt(tokenizer.nextToken());
            coefficients[digit] = 1;
        }

        transform(coefficients, polySize, false);
        IntStream.range(0, polySize).forEach(i -> coefficients[i] = (int)fastPow(coefficients[i], halfN));
        transform(coefficients, polySize, true);

        long answer = 0;
        for (int i = 0; i <= halfN * 9; i++) {
            long val = coefficients[i];
            answer = (answer + val * val) % MOD;
        }
        System.out.println(answer);
    }
}

import java.io.*;
