public class CF1096G {
    static final int MOD = 998244353;
    static long[] omega, omegaInv;

    static long modExp(long b, int e) {
        long r = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return r;
    }

    static void precompute() {
        omega = new long[21];
        omegaInv = new long[21];
        for (int i = 0; i <= 20; i++) {
            int e1 = (MOD - 1) >> i;
            int e2 = (MOD - 1) - e1;
            omega[i] = modExp(3, e1);
            omegaInv[i] = modExp(3, e2);
        }
    }

    static void performNTT(int[] data, int size, boolean isInverse) {
        for (int i = 1, j = 0; i < size; i++) {
            int bit = size;
            do {
                j ^= (bit >>= 1);
            } while ((j & bit) == 0);
            if (i < j) {
                int temp = data[i];
                data[i] = data[j];
                data[j] = temp;
            }
        }

        for (int len = 2, level = 0; len <= size; len <<= 1, level++) {
            long w = isInverse ? omegaInv[level + 1] : omega[level + 1];
            for (int i = 0; i < size; i += len) {
                long wCurrent = 1;
                for (int j = 0; j < len / 2; j++) {
                    int even = data[i + j];
                    int odd = (int)((data[i + j + len / 2] * wCurrent) % MOD);
                    data[i + j] = (int)((even + odd) % MOD);
                    data[i + j + len / 2] = (int)((even - odd + MOD) % MOD);
                    wCurrent = (wCurrent * w) % MOD;
                }
            }
        }

        if (isInverse) {
            long invSize = modExp(size, MOD - 2);
            for (int i = 0; i < size; i++) {
                data[i] = (int)((data[i] * invSize) % MOD);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        precompute();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = reader.readLine().split("\\s+");
        int n = Integer.parseInt(firstLine[0]) / 2;
        int k = Integer.parseInt(firstLine[1]);

        int polyLength = 1;
        while (polyLength < n * 9 + 1) polyLength *= 2;

        int[] poly = new int[polyLength];
        String[] secondLine = reader.readLine().split("\\s+");
        for (int i = 0; i < k; i++) {
            int d = Integer.parseInt(secondLine[i]);
            poly[d] = 1;
        }

        performNTT(poly, polyLength, false);
        for (int i = 0; i < polyLength; i++) {
            poly[i] = (int)modExp(poly[i], n);
        }
        performNTT(poly, polyLength, true);

        long total = 0;
        for (int i = 0; i <= n * 9; i++) {
            long x = poly[i];
            total = (total + x * x) % MOD;
        }
        System.out.println(total);
    }
}

