    static class TaskG {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int mod = 998244353;
            int n = in.nextInt();
            int k = in.nextInt();
            int[] v = new int[10];
            for (int i = 0; i < k; i++) {
                int x = in.nextInt();
                v[x] = 1;
            }
            int[] ans = {1};
            int p = n / 2;
            while (true) {
                if (p % 2 != 0) {
                    ans = multiplyMod(ans, v, mod);
                }
