        int[] d = na(K);
        long[] f = new long[20];
        for (int i = 0; i < K; i++) {
            for (int j = 0; j < K; j++) {
                f[10 + d[i] - d[j]]++;
            }
        }

        n /= 2;
        long[] g = new long[]{1L};
        for (int D = 17; D >= 0; D--) {
            g = clean(polySquare(g));
            if ((n << ~D) < 0) {
                g = clean(polyMultiply(g, f));
            }
        }
        out.println(n * 10 < g.length ? g[n * 10] % MOD : 0);
    }

    long[] clean(long[] a) {
        int last = a.length - 1;
        while (last >= 0 && a[last] == 0) last--;
        return last < 0 ? new long[0] : Arrays.copyOf(a, last + 1);
    }

    long[] polySquare(long[] a) {
        int len = a.length;
        long[] res = new long[2 * len - 1];
        for (int i = 0; i < len; i++) {
            for (int j = i; j < len; j++) {
                long prod = a[i] * a[j];
                if (i == j) {
                    res[i + j] = (res[i + j] + prod) % MOD;
                } else {
                    res[i + j] = (res[i + j] + 2 * prod) % MOD;
                }
            }
        }
        return res;
    }

    long[] polyMultiply(long[] a, long[] b) {
        int lenA = a.length, lenB = b.length;
        long[] res = new long[lenA + lenB - 1];
        for (int i = 0; i < lenA; i++) {
            for (int j = 0; j < lenB; j++) {
                res[i + j] = (res[i + j] + a[i] * b[j]) % MOD;
            }
        }
        return res;
    }

