                    double vi = re[i + j + len / 2] * wi + im[i + j + len / 2] * wr;
                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + len / 2] = ur - vr;
                    im[i + j + len / 2] = ui - vi;
                    double tmp = wr * wRe - wi * wIm;
                    wi = wr * wIm + wi * wRe;
                    wr = tmp;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream in) { this.in = in; }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[ptr++] & 0xFF;
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int s = 1;
            if (c == '-') { s = -1; c = read(); }
            int x = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                x = x * 10 + c - '0';
                c = read();
            } while (c > 32);
            return x * s;
        }
    }
}

