        permute(x, size);
        for (int block = 2; block <= size; block <<= 1) {
            long omega = power(ROOT, (MOD - 1) / block);
            if (direction == -1) omega = power(omega, MOD - 2);
            for (int start = 0; start < size; start += block) {
