        for (int i = 0; i < size; i++) {
            if (poly[i] != 0) {
                poly[i] = pow(poly[i], halfN);
            }
        }
        transform(poly, size, -1);

        long ans = 0;
        for (int i = 0; i < size; i++) {
            ans = (ans + poly[i] * poly[i]) % MOD;
        }
        System.out.println((ans + MOD) % MOD);
    }
}

