import java.io.*;
import java.util.*;

public class Main {
    private static final int MOD = 998244353;
    private static final int ROOT = 3;

    private static long modExp(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static void permute(long[] arr, int size) {
        for (int i = 1, j = size >> 1; i < size - 1; i++) {
            if (i < j) {
                long temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
            int k = size >> 1;
            while (j >= k) {
                j -= k;
                k >>= 1;
            }
            if (j < k) j += k;
        }
    }

    private static void transform(long[] data, int n, int direction) {
        permute(data, n);
        for (int step = 2; step <= n; step <<= 1) {
            long omega = modExp(ROOT, (MOD - 1) / step);
            if (direction == -1) omega = modExp(omega, MOD - 2);
            for (int start = 0; start < n; start += step) {
                long w = 1;
                int half = step >> 1;
                for (int idx = start; idx < start + half; idx++) {
                    long even = data[idx];
                    long odd = (w * data[idx + half]) % MOD;
                    data[idx] = (even + odd) % MOD;
                    data[idx + half] = ((even - odd) % MOD + MOD) % MOD;
                    w = (w * omega) % MOD;
                }
            }
        }
        if (direction == -1) {
            long invN = modExp(n, MOD - 2);
            for (int i = 0; i < n; i++) {
                data[i] = (data[i] * invN) % MOD;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = reader.readLine().split("\\s+");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);

        int size = 1;
        int halfN = n / 2;
        while (size < 9 * halfN + 1) size <<= 1;

        long[] polyA = new long[size];
        long[] polyB = new long[size];
        polyA[0] = 1;

        String[] secondLine = reader.readLine().split("\\s+");
        for (int i = 0; i < m; i++) {
            int val = Integer.parseInt(secondLine[i]);
            polyB[val] = 1;
        }

        transform(polyA, size, 1);
        transform(polyB, size, 1);

        for (int i = 0; i < size; i++) {
            if (polyA[i] != 0 && polyB[i] != 0) {
                polyA[i] = (polyA[i] * modExp(polyB[i], halfN)) % MOD;
            } else {
                polyA[i] = 0;
            }
        }

        transform(polyA, size, -1);

        long result = 0;
        for (int i = 0; i < size; i++) {
            result = (result + polyA[i] * polyA[i]) % MOD;
        }
        System.out.println((result % MOD + MOD) % MOD);
    }
}

