        return result;
    }

    static void reorder(long[] array, int length) {
        for (int i = 1, j = length >> 1; i < length - 1; i++) {
            if (i < j) {
                long temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
            int k = length >> 1;
            while (j >= k) {
                j -= k;
                k >>= 1;
            }
            if (j < k) {
                j += k;
            }
        }
    }

    static void numberTheoreticTransform(long[] input, int size, int mode) {
        reorder(input, size);
        for (int segment = 2; segment <= size; segment <<= 1) {
            long omega = power(PRIMITIVE_ROOT, (MOD - 1) / segment);
            if (mode == -1) omega = power(omega, MOD - 2);
            for (int start = 0; start < size; start += segment) {
                long w = 1;
                int half = segment >> 1;
                for (int pos = start; pos < start + half; pos++) {
                    long x = input[pos];
                    long y = (w * input[pos + half]) % MOD;
                    input[pos] = (x + y) % MOD;
                    input[pos + half] = ((x - y) % MOD + MOD) % MOD;
                    w = (w * omega) % MOD;
                }
            }
        }
        if (mode == -1) {
            long invSize = power(size, MOD - 2);
            for (int i = 0; i < size; i++) {
                input[i] = (input[i] * invSize) % MOD;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
