    private static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static void bitReversePermutation(long[] arr, int n) {
        for (int i = 1, j = n >> 1; i < n - 1; i++) {
            if (i < j) {
                long temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
            int k = n >> 1;
            while (j >= k) {
                j -= k;
                k >>= 1;
            }
            if (j < k) j += k;
        }
    }

    private static void ntt(long[] data, int size, int sign) {
        bitReversePermutation(data, size);
        for (int block = 2; block <= size; block <<= 1) {
            long w = modPow(G, (MOD - 1) / block);
            if (sign == -1) w = modPow(w, MOD - 2);
