                    data[idx] = (even + odd) % MOD;
                    data[idx + halfBlock] = ((even - odd) % MOD + MOD) % MOD;
                    currentW = (currentW * w) % MOD;
                }
            }
        }
        if (sign == -1) {
            long invSize = modPow(size, MOD - 2);
            for (int i = 0; i < size; i++) {
                data[i] = (data[i] * invSize) % MOD;
