    static {
        BigInteger modBI = BigInteger.valueOf(MOD);
        BigInteger rootBI = BigInteger.valueOf(PRIMITIVE_ROOT);
        BigInteger sizeBI = BigInteger.valueOf(N);
        W[0] = 1;
        W_INV[0] = 1;
        for (int i = 1; i < N; i++) {
            W[i] = W[i - 1] * PRIMITIVE_ROOT % MOD;
            W_INV[i] = W_INV[i - 1] * PRIMITIVE_ROOT % MOD;
        }
        N_INV = sizeBI.modInverse(modBI).longValue();
    }

    private BufferedReader reader;
    private PrintWriter writer;
    private boolean isSystemIO = true;

    static class Coefficients {
        final long[] data = new long[N];

        Coefficients(long[] input) {
            System.arraycopy(input, 0, data, 0, input.length);
        }

        long[] evaluate(boolean forward) {
            return recursiveTransform(0, 1, forward);
        }

        private long[] recursiveTransform(int start, int step, boolean forward) {
            if (step == N) {
                return new long[]{data[start]};
            }
            long[] even = recursiveTransform(start, step << 1, forward);
            long[] odd = recursiveTransform(start + step, step << 1, forward);
            int half = even.length;
            long[] result = new long[half << 1];
            for (int i = 0; i < half; i++) {
                long w = forward ? W[i * step] : W_INV[i * step];
                result[i] = (even[i] + w * odd[i]) % MOD;
            }
            for (int i = 0; i < half; i++) {
                long w = forward ? W[i * step] : W_INV[i * step];
                result[half + i] = ((even[i] - w * odd[i]) % MOD + MOD) % MOD;
            }
            return result;
        }
    }

    long[] directDFT(long[] input) {
        long[] output = new long[N];
        long wPower = 1;
        for (int i = 0; i < N; i++) {
            long x = 1;
            for (int j = 0; j < input.length; j++) {
                output[i] = (output[i] + input[j] * x) % MOD;
                x = x * wPower % MOD;
            }
            wPower = wPower * PRIMITIVE_ROOT % MOD;
        }
        return output;
    }

