        MyScanner sc = new MyScanner();
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt() * 2;
        int k = sc.nextInt();
        int[] l = new int[k + 1];
        int[] r = new int[k + 1];
        SparseTable[][] seg = new SparseTable[2][2];

        for (int i = 0; i < k; i++) {
            l[i] = sc.nextInt();
            r[i] = sc.nextInt();
        }
        l[k] = n;

        for (int j = 0; j < 2; j++) {
            int[] a = new int[n / 2 + 2];
            Arrays.fill(a, inf);
            a[n / 2] = 0;
            seg[1][j] = new SparseTable(a);
        }

        int p = 1;
        for (int i = k - 1; i >= 0; i--) {
            p ^= 1;
            for (int j = 0; j < 2; j++) {
                int[] a = new int[n / 2 + 2];
                Arrays.fill(a, inf);
                for (int c = 0; c <= l[i] && c < a.length; c++) {
                    int best = seg[p ^ 1][j].query(c + l[i + 1] - l[i], c + l[i + 1] - l[i]);
                    int alt = l[i + 1] - (c + r[i] - l[i]);
                    int alt2 = l[i + 1] - c;
                    best = Math.min(best, 1 + seg[p ^ 1][1 - j].query(alt, alt2));
                    if (r[i] > l[i]) {
                        best = Math.min(best, 2 + seg[p ^ 1][j].query(c + l[i + 1] - r[i], c + l[i + 1] - l[i] - 1));
                    }
                    a[c] = best;
                }
                seg[p][j] = new SparseTable(a);
            }
        }

        int ans = Math.min(seg[p][0].query(l[0], l[0]), seg[p][1].query(l[0], l[0]));
        if (ans > 2 * k) {
            pw.println("Hungry");
        } else {
            pw.println("Full");
            pw.println(ans);
        }
        pw.flush();
        pw.close();
    }

    static int inf = (int) 1e7;

    static class SparseTable {
        int[] a;
        int[][] st;

        SparseTable(int[] a) {
            int n = a.length;
            this.a = a;
            int k = (int) Math.floor(Math.log(n) / Math.log(2)) + 1;
            st = new int[n][k];
            for (int i = 0; i < n; i++) {
                st[i][0] = i;
            }
            for (int j = 1; (1 << j) <= n; j++) {
                for (int i = 0; i + (1 << j) - 1 < n; i++) {
                    if (a[st[i][j - 1]] < a[st[i + (1 << (j - 1))][j - 1]]) {
                        st[i][j] = st[i][j - 1];
                    } else {
                        st[i][j] = st[i + (1 << (j - 1))][j - 1];
                    }
                }
            }
        }

        int query(int i, int j) {
            if (i >= a.length) return inf;
            j = Math.min(j, a.length - 1);
            int k = (int) Math.floor(Math.log(j - i + 1) / Math.log(2));
            return Math.min(a[st[i][k]], a[st[j - (1 << k) + 1][k]]);
        }
    }

