import java.io.DataInputStream;
import java.io.IOException;

public class Task939F {

    public static class FastScanner {

        protected DataInputStream dataInputStream;
        protected byte[] buffer = new byte[0x10000];
        protected int bufferOffset;
        protected int bufferLength;
        protected boolean isEndOfFile;

        public FastScanner() throws IOException {
            dataInputStream = new DataInputStream(System.in);
            Read();
        }

        protected void Read() throws IOException {
            final int length = dataInputStream.read(buffer);
            if (length > 0) {
                bufferLength = length;
            } else {
                bufferLength = 0;
                isEndOfFile = true;
            }
            bufferOffset = 0;
        }

        protected byte nextByte() throws IOException {
            if (bufferOffset == bufferLength) {
                if (!isEndOfFile) Read();
                if (isEndOfFile) return 0;
            }
            return buffer[bufferOffset++];
        }

        public int nextInt() throws IOException {
            int a = 0;
            boolean isNegative = false;

            byte b = nextByte();
            while (b <= ' ') b = nextByte();
            if (b == '-') {
                isNegative = true;
                b = nextByte();
            }
            while (b > ' ') {
                a = a * 10 + (b - '0');
                b = nextByte();
            }
            return isNegative ? -a : a;
        }

    }

    public static void SaveRotates(final int num) {
        if (minNumRotates == 0) minNumRotates = num;
        else minNumRotates = Math.min(minNumRotates, num);
    }

    public static void CalcRotates(int side, final int[] tmin, final int[] tmax,
                                  int noffset, int koffset, boolean isInterval) {
        if (tmin[0] > n || tmin[1] > n) return;
        else if ((tmin[0] <= n && tmax[0] >= n) || (tmin[1] <= n && tmax[1] >= n)) {
            if ((tmax[0] < n && side == 1) || (tmax[1] < n && side == 0)) {
                SaveRotates(numRotates + 1);
            } else {
                SaveRotates(numRotates);
            }
            return;
        } else if (koffset == k) return;

        if (isInterval) {
            if (kbeg[koffset] == kend[koffset]) {
                // no rotate
                CalcRotates(side, tmin, tmax, noffset, koffset + 1, false);

                // rotate
                numRotates++;
                CalcRotates(1 - side, tmin, tmax, noffset, koffset + 1, false);
                numRotates--;

            } else {
                // no rotate
                tmin[side] += kend[koffset] - kbeg[koffset];
                tmax[side] += kend[koffset] - kbeg[koffset];
                CalcRotates(side, tmin, tmax, kend[koffset], koffset + 1, false);
                tmin[side] -= kend[koffset] - kbeg[koffset];
                tmax[side] -= kend[koffset] - kbeg[koffset];

                // rotate once
                tmax[side] += kend[koffset] - kbeg[koffset];
                tmax[1 - side] += kend[koffset] - kbeg[koffset];
                numRotates++;
                CalcRotates(1 - side, tmin, tmax, kend[koffset], koffset + 1, false);
                numRotates--;
                tmax[side] -= kend[koffset] - kbeg[koffset];
                tmax[1 - side] -= kend[koffset] - kbeg[koffset];

                // rotate twice
                tmax[side] += kend[koffset] - kbeg[koffset];
                tmin[1 - side] += 1;
                tmax[1 - side] += kend[koffset] - kbeg[koffset] - 1;
                numRotates += 2;
                CalcRotates(side, tmin, tmax, kend[koffset], koffset + 1, false);
                numRotates -= 2;
                tmax[side] -= kend[koffset] - kbeg[koffset];
                tmin[1 - side] -= 1;
                tmax[1 - side] -= kend[koffset] - kbeg[koffset] - 1;

            }

        } else {
            tmin[side] += kbeg[koffset] - noffset;
            tmax[side] += kbeg[koffset] - noffset;
            CalcRotates(side, tmin, tmax, kbeg[koffset], koffset, true);
            tmin[side] -= kbeg[koffset] - noffset;
            tmax[side] -= kbeg[koffset] - noffset;
        }
    }

    public static int[] kbeg;
    public static int[] kend;
    public static int n = 0;
    public static int k = 0;
    public static int numRotates = 0;
    public static int minNumRotates = 0;

    public static void main(final String[] args) throws IOException {
        final FastScanner scanner = new FastScanner();
        n = scanner.nextInt();
        k = scanner.nextInt();

        kbeg = new int[k];
        kend = new int[k];

        for (int i = 0; i < k; i++) {
            kbeg[i] = scanner.nextInt();
            kend[i] = scanner.nextInt();
        }
        final int[] tmin = new int[2];
        final int[] tmax = new int[2];

        CalcRotates(0, tmin, tmax, 0, 0, false);
        if (minNumRotates > 0) {
            System.out.println("Full");
            System.out.println(minNumRotates);
        } else {
            System.out.println("Hungry");
        }
    }
}

import java.io.*;
import java.util.*;

public class Task939F {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[0x10000];
        private int ptr = 0;
        private int len = 0;

        public FastScanner() {
            in = System.in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private int skip() throws IOException {
            int c;
            while ((c = read()) <= 32 && c != -1) {}
            return c;
        }

        public int nextInt() throws IOException {
            int c = skip();
            if (c == -1) throw new EOFException();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > 32) {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }

    static int[] kbeg, kend;
    static int n, k;
    static int minRotates;

    static void updateMin(int val) {
        if (minRotates == 0) minRotates = val;
        else minRotates = Math.min(minRotates, val);
    }

    static void dfs(int side, int[] tmin, int[] tmax, int curPos, int idx, boolean inInterval) {
        if (tmin[0] > n || tmin[1] > n) return;
        else if ((tmin[0] <= n && tmax[0] >= n) || (tmin[1] <= n && tmax[1] >= n)) {
            if ((tmax[0] < n && side == 1) || (tmax[1] < n && side == 0)) {
                updateMin(curRotates + 1);
            } else {
                updateMin(curRotates);
            }
            return;
        } else if (idx == k) return;

        if (inInterval) {
            if (kbeg[idx] == kend[idx]) {
                dfs(side, tmin, tmax, curPos, idx + 1, false);
                curRotates++;
                dfs(1 - side, tmin, tmax, curPos, idx + 1, false);
                curRotates--;
            } else {
                // no rotate
                tmin[side] += kend[idx] - kbeg[idx];
                tmax[side] += kend[idx] - kbeg[idx];
                dfs(side, tmin, tmax, kend[idx], idx + 1, false);
                tmin[side] -= kend[idx] - kbeg[idx];
                tmax[side] -= kend[idx] - kbeg[idx];

                // rotate once
                tmax[side] += kend[idx] - kbeg[idx];
                tmax[1 - side] += kend[idx] - kbeg[idx];
                curRotates++;
                dfs(1 - side, tmin, tmax, kend[idx], idx + 1, false);
                curRotates--;
                tmax[side] -= kend[idx] - kbeg[idx];
                tmax[1 - side] -= kend[idx] - kbeg[idx];

                // rotate twice
                tmax[side] += kend[idx] - kbeg[idx];
                tmin[1 - side] += 1;
                tmax[1 - side] += kend[idx] - kbeg[idx] - 1;
                curRotates += 2;
                dfs(side, tmin, tmax, kend[idx], idx + 1, false);
                curRotates -= 2;
                tmax[side] -= kend[idx] - kbeg[idx];
                tmin[1 - side] -= 1;
                tmax[1 - side] -= kend[idx] - kbeg[idx] - 1;
            }
        } else {
            int delta = kbeg[idx] - curPos;
            tmin[side] += delta;
            tmax[side] += delta;
            dfs(side, tmin, tmax, kbeg[idx], idx, true);
            tmin[side] -= delta;
            tmax[side] -= delta;
        }
    }

    static int curRotates = 0;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        n = fs.nextInt();
        k = fs.nextInt();
