public class Task939F {

    static class Reader {
        BufferedReader br;
        StringTokenizer st;

        public Reader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int n, k;
    static int[] beg, end;
    static int best;

    static void tryUpdate(int val) {
        best = (best == 0) ? val : Math.min(best, val);
    }

    static void explore(int side, int[] lo, int[] hi, int pos, int idx, boolean inSeg) {
        if (lo[0] > n || lo[1] > n) return;
        if ((lo[0] <= n && hi[0] >= n) || (lo[1] <= n && hi[1] >= n)) {
            if ((hi[0] < n && side == 1) || (hi[1] < n && side == 0)) {
                tryUpdate(curRot + 1);
            } else {
                tryUpdate(curRot);
            }
            return;
        }
        if (idx == k) return;

        if (inSeg) {
            if (beg[idx] == end[idx]) {
                explore(side, lo, hi, pos, idx + 1, false);
                curRot++;
                explore(1 - side, lo, hi, pos, idx + 1, false);
                curRot--;
            } else {
                int span = end[idx] - beg[idx];

                // no rotate
                lo[side] += span;
                hi[side] += span;
                explore(side, lo, hi, end[idx], idx + 1, false);
                lo[side] -= span;
                hi[side] -= span;

                // rotate once
                hi[side] += span;
                hi[1 - side] += span;
                curRot++;
                explore(1 - side, lo, hi, end[idx], idx + 1, false);
                curRot--;
                hi[side] -= span;
                hi[1 - side] -= span;

                // rotate twice
                hi[side] += span;
                lo[1 - side] += 1;
                hi[1 - side] += span - 1;
                curRot += 2;
                explore(side, lo, hi, end[idx], idx + 1, false);
                curRot -= 2;
                hi[side] -= span;
                lo[1 - side] -= 1;
                hi[1 - side] -= span - 1;
            }
        } else {
            int delta = beg[idx] - pos;
            lo[side] += delta;
            hi[side] += delta;
            explore(side, lo, hi, beg[idx], idx, true);
            lo[side] -= delta;
            hi[side] -= delta;
        }
    }

    static int curRot = 0;

    public static void main(String[] args) throws IOException {
        Reader rd = new Reader();
        n = rd.nextInt();
        k = rd.nextInt();
        beg = new int[k];
        end = new int[k];
        for (int i = 0; i < k; i++) {
            beg[i] = rd.nextInt();
            end[i] = rd.nextInt();
        }
        best = 0;
        int[] lo = new int[2];
        int[] hi = new int[2];
        explore(0, lo, hi, 0, 0, false);
        if (best > 0) {
            System.out.println("Full");
            System.out.println(best);
        } else {
            System.out.println("Hungry");
        }
    }
}

import java.io.*;
