public class Task939F {

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (numChars == -1) throw new IOException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buf);
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= 32) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            while (c > 32) {
                res = res * 10 + c - '0';
                c = read();
            }
            return res * sgn;
        }
    }

    static int N, K;
    static int[] L, R;
    static int minAnswer;

    static void record(int x) {
        if (minAnswer == 0) minAnswer = x;
        else minAnswer = Math.min(minAnswer, x);
    }

    static void traverse(int side, int[] low, int[] high, int cur, int pos, boolean inside) {
        if (low[0] > N || low[1] > N) return;
        if ((low[0] <= N && high[0] >= N) || (low[1] <= N && high[1] >= N)) {
            if ((high[0] < N && side == 1) || (high[1] < N && side == 0)) {
                record(rotCount + 1);
            } else {
                record(rotCount);
            }
            return;
        }
        if (pos == K) return;

        if (inside) {
            if (L[pos] == R[pos]) {
                traverse(side, low, high, cur, pos + 1, false);
                rotCount++;
                traverse(1 - side, low, high, cur, pos + 1, false);
                rotCount--;
            } else {
                int span = R[pos] - L[pos];

                // no rotation
                low[side] += span;
                high[side] += span;
                traverse(side, low, high, R[pos], pos + 1, false);
                low[side] -= span;
                high[side] -= span;

                // one rotation
                high[side] += span;
                high[1 - side] += span;
                rotCount++;
                traverse(1 - side, low, high, R[pos], pos + 1, false);
                rotCount--;
                high[side] -= span;
                high[1 - side] -= span;

                // two rotations
                high[side] += span;
                low[1 - side] += 1;
                high[1 - side] += span - 1;
                rotCount += 2;
                traverse(side, low, high, R[pos], pos + 1, false);
                rotCount -= 2;
                high[side] -= span;
                low[1 - side] -= 1;
                high[1 - side] -= span - 1;
            }
        } else {
            int diff = L[pos] - cur;
            low[side] += diff;
            high[side] += diff;
            traverse(side, low, high, L[pos], pos, true);
            low[side] -= diff;
            high[side] -= diff;
        }
    }

    static int rotCount = 0;

    public static void main(String[] args) throws IOException {
        InputReader in = new InputReader(System.in);
        N = in.nextInt();
        K = in.nextInt();
        L = new int[K];
        R = new int[K];
        for (int i = 0; i < K; i++) {
            L[i] = in.nextInt();
            R[i] = in.nextInt();
        }
        minAnswer = 0;
        int[] lo = new int[2];
        int[] hi = new int[2];
        traverse(0, lo, hi, 0, 0, false);
        if (minAnswer > 0) {
            System.out.println("Full");
            System.out.println(minAnswer);
        } else {
            System.out.println("Hungry");
        }
    }
}

