public class Task939F {

    static class Scanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public Scanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        private void fill() throws IOException {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        public int nextInt() throws IOException {
            fill();
            return Integer.parseInt(tokenizer.nextToken());
        }
    }

    static int totalN, totalK;
    static int[] starts, ends;
    static int optimal;

    static void consider(int count) {
        if (optimal == 0) optimal = count;
        else optimal = Math.min(optimal, count);
    }

    static void search(int orientation, int[] minBound, int[] maxBound, int currentPos, int segmentIdx, boolean inSegment) {
        if (minBound[0] > totalN || minBound[1] > totalN) return;
        if ((minBound[0] <= totalN && maxBound[0] >= totalN) || (minBound[1] <= totalN && maxBound[1] >= totalN)) {
            if ((maxBound[0] < totalN && orientation == 1) || (maxBound[1] < totalN && orientation == 0)) {
                consider(currentRotations + 1);
            } else {
                consider(currentRotations);
            }
            return;
        }
        if (segmentIdx == totalK) return;

        if (inSegment) {
            if (starts[segmentIdx] == ends[segmentIdx]) {
                search(orientation, minBound, maxBound, currentPos, segmentIdx + 1, false);
                currentRotations++;
                search(1 - orientation, minBound, maxBound, currentPos, segmentIdx + 1, false);
                currentRotations--;
            } else {
                int range = ends[segmentIdx] - starts[segmentIdx];

                // no rotation
                minBound[orientation] += range;
                maxBound[orientation] += range;
                search(orientation, minBound, maxBound, ends[segmentIdx], segmentIdx + 1, false);
                minBound[orientation] -= range;
                maxBound[orientation] -= range;

                // one rotation
                maxBound[orientation] += range;
                maxBound[1 - orientation] += range;
                currentRotations++;
                search(1 - orientation, minBound, maxBound, ends[segmentIdx], segmentIdx + 1, false);
                currentRotations--;
                maxBound[orientation] -= range;
                maxBound[1 - orientation] -= range;

                // two rotations
                maxBound[orientation] += range;
                minBound[1 - orientation] += 1;
                maxBound[1 - orientation] += range - 1;
                currentRotations += 2;
                search(orientation, minBound, maxBound, ends[segmentIdx], segmentIdx + 1, false);
                currentRotations -= 2;
                maxBound[orientation] -= range;
                minBound[1 - orientation] -= 1;
                maxBound[1 - orientation] -= range - 1;
            }
        } else {
            int offset = starts[segmentIdx] - currentPos;
            minBound[orientation] += offset;
            maxBound[orientation] += offset;
            search(orientation, minBound, maxBound, starts[segmentIdx], segmentIdx, true);
            minBound[orientation] -= offset;
            maxBound[orientation] -= offset;
        }
    }

    static int currentRotations = 0;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextInt();
        totalK = sc.nextInt();
        starts = new int[totalK];
        ends = new int[totalK];
        for (int i = 0; i < totalK; i++) {
            starts[i] = sc.nextInt();
            ends[i] = sc.nextInt();
        }
        optimal = 0;
        int[] lower = new int[2];
        int[] upper = new int[2];
        search(0, lower, upper, 0, 0, false);
        if (optimal > 0) {
            System.out.println("Full");
            System.out.println(optimal);
        } else {
            System.out.println("Hungry");
        }
    }
}

