/*
TASK: cutlet
LANG: JAVA
 */
public class cutlet {
    static int n , k , lo , hi;
    static int[][] segs;
    static int[] l , delt;
    static int[][][] dp;
    static ArrayList<int[]> finSeg = new ArrayList<int[]>();
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        n = in.nextInt();
        k = in.nextInt();
        segs = new int[k][2];
        for(int i = 0;i < k; i++){
            segs[i][0] = in.nextInt();
            segs[i][1] = in.nextInt();
        }
        Arrays.sort(segs, new Comparator<int[]>() {
            @Override
            public int compare(int[] o1, int[] o2) {
                return o1[0] - o2[0];
            }
        });
        for(int i = 0;i < k; i++){
            lo = segs[i][0];
            hi = segs[i][0];
            while(i < k && segs[i][0] <= hi)hi = Math.max(hi , segs[i++][1]);
            int[] add = {lo , hi};
            finSeg.add(add);
            i--;
        }
        k = finSeg.size();
        segs = new int[k][2];
        l = new int[k];
        delt = new int[k];
        for(int i = 0;i < k; i++)segs[i] = finSeg.get(i);
        for(int i = 0;i < k; i++){
            l[i] = segs[i][1] - segs[i][0];
            delt[i] = i < k-1 ? segs[i+1][0] - segs[i][1] : 2*n - segs[i][1];
        }
        dp = new int[2][k+1][2*n+1];
        for(int i = 0;i < 2*n+1; i++){
            dp[0][k][i] = n;
            dp[1][k][i] = n;
        }
        dp[0][k][n] = 0;
        dp[1][k][n] = 0;
        RMQ[] rmq = new RMQ[2];
        rmq[0] = new RMQ(dp[0][k]);
        rmq[1] = new RMQ(dp[1][k]);
        for(int i = k-1; i >= 0; i--){
            for(int j = 0;j <= 2*n; j++){
                dp[0][i][j] = j+l[i]+delt[i] <= 2*n ? dp[0][i+1][j+l[i]+delt[i]] : n;
                dp[1][i][j] = dp[1][i+1][j];
                dp[0][i][j] = Math.min(dp[0][i][j] , 1 + rmq[1].min(j , Math.min(j+l[i] , 2*n)));
                if(j + delt[i] <= 2*n)dp[1][i][j] = Math.min(dp[1][i][j] , 1 + rmq[0].min(j + delt[i] , Math.min(j+l[i] + delt[i] , 2*n)));
                if(j + delt[i] <= 2*n)dp[0][i][j] = Math.min(dp[0][i][j] , 2 + rmq[0].min(j + delt[i] , Math.min(j+l[i] + delt[i] , 2*n)));
                dp[1][i][j] = Math.min(dp[1][i][j] , 2 + rmq[1].min(j , Math.min(j+l[i] , 2*n)));
            }
            rmq[0] = new RMQ(dp[0][i]);
            rmq[1] = new RMQ(dp[1][i]);
        }
        int ans = dp[1][0][0];
        if(ans == n)System.out.println("Hungry");
        else {
            System.out.println("Full");
            System.out.println(ans);
        }

    }
    public static class RMQ{
        int n , k;
        int[][] min;
        public RMQ(int[] a){
            n = a.length;
            k = Integer.numberOfTrailingZeros(Integer.highestOneBit(n))+1;
            min = new int[k][n];
            for(int i = 0;i < n; i++)
                min[0][i] = a[i];
            for(int i = 1; i < k; i++){
                for(int j = 0;j + (1 << i-1) < n; j++){
                    min[i][j] = Math.min(min[i-1][j] , min[i-1][j + (1 << i-1)]);
                }
            }
        }
        public int min(int a , int b){
            int z = Integer.numberOfTrailingZeros(Integer.highestOneBit(b-a+1));
            return Math.min(min[z][a] , min[z][b - (1<<z) + 1]);
        }
    }
    private static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskF {
        int MAX = (int) (1e9);

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int k = in.nextInt();
            ArrayList<int[]> interval = new ArrayList<>();
            for (int i = 0; i < k; i++) {
                interval.add(new int[]{in.nextInt(), in.nextInt()});
            }
            interval.add(new int[]{2 * N, 2 * N});
            int cur = 0;
            SegmentTree[] dp = new SegmentTree[2]; //how many sides are fried on the front, 0 is currently on front, 1 is currently on back
            dp[0] = new SegmentTree(N + 1);
            dp[1] = new SegmentTree(N + 1);
            dp[0].assign(0, 0);
            for (int i = 0; i < interval.size(); i++) {
                for (int j = N; j >= 0; j--) {
                    dp[0].assign(j, dp[0].getVal(j - (interval.get(i)[0] - cur)));
                }
                cur = interval.get(i)[1];
                int sz = interval.get(i)[1] - interval.get(i)[0];
                for (int j = N; j >= 0; j--) {
                    int[] put = new int[2];
                    for (int z = 0; z <= 1; z++) {
                        int twoSwaps = dp[z].query(j - sz, j);
                        int oneSwap = dp[(z + 1) % 2].query(j - sz, j);
                        int noSwap;
                        if (z == 1) {
                            noSwap = dp[z].getVal(j);
                        } else {
                            noSwap = dp[z].getVal(j - sz);
                        }
                        put[z] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                    }
                    dp[0].assign(j, put[0]);
//                out.println(j + " " + put[0] + " " + put[1]);
                    dp[1].assign(j, put[1]);
                }
            }
            int ans = Math.min(dp[0].query(N, N), dp[1].query(N, N));
            if (ans >= MAX) {
                out.println("Hungry");
            } else {
                out.println("Full");
                out.println(ans);
            }
        }

        class SegmentTree {
            int[] tree;
            int[] arr;
            int size = 0;

            public SegmentTree(int N) {
                tree = new int[4 * N];
                arr = new int[N];
                Arrays.fill(arr, MAX);
                size = N;
                for (int i = 0; i < 4 * N; i++) {
                    tree[i] = MAX;
                }
            }

            public int query(int l, int r) {
                if (r < 0) {
                    return MAX;
                }
                return queryUtil(1, 0, size - 1, Math.max(0, l), r);
            }

            public int queryUtil(int n, int tl, int tr, int l, int r) {
                //node number, cur range of node, cur range of query
                if (l > r) {
                    return MAX;
                }
                if (tl == l && tr == r) {
                    return tree[n];
                }
                int tm = (tl + tr) / 2;
                return Math.min(queryUtil(2 * n, tl, tm, l, Math.min(r, tm)), queryUtil(2 * n + 1, tm + 1, tr, Math.max(tm + 1, l), r));
            }

            public void assign(int n, int val) {
                arr[n] = val;
                int tl = 0;
                int tr = size - 1;
                int a = 1;
                while (tl < tr) {
                    int tm = (tl + tr) >> 1;
                    if (n <= tm) {
                        tr = tm;
                        a = 2 * a;
                    } else {
                        tl = tm + 1;
                        a = 2 * a + 1;
                    }
                }
                tree[a] = val;
                a >>= 1;
                while (a > 0) {
                    tree[a] = Math.min(tree[2 * a], tree[2 * a + 1]);
                    a >>= 1;
                }
            }

            int getVal(int i) {
                if (i < 0) {
                    return MAX;
                }
                return arr[i];
            }

        }

    }

