                    candidates[side] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                }
                nextDp[0].set(j, candidates[0]);
                nextDp[1].set(j, candidates[1]);
            }

            dp = nextDp;
        }

