    static class SegmentTree {
        private final int[] tree;
        private final int[] arr;
        private final int size;

        public SegmentTree(int n) {
            size = n;
            arr = new int[n];
            tree = new int[4 * n];
            Arrays.fill(arr, (int)(1e9));
            Arrays.fill(tree, (int)(1e9));
        }

        public void set(int idx, int val) {
            arr[idx] = val;
            int node = 1, l = 0, r = size - 1;
            while (l < r) {
                int mid = (l + r) / 2;
                if (idx <= mid) {
                    r = mid;
                    node *= 2;
                } else {
                    l = mid + 1;
                    node = node * 2 + 1;
                }
            }
            tree[node] = val;
            while (node > 1) {
                node /= 2;
                tree[node] = Math.min(tree[node * 2], tree[node * 2 + 1]);
            }
        }

        public int get(int idx) {
            return idx < 0 ? (int)(1e9) : arr[idx];
        }

        public int rangeMin(int l, int r) {
            if (r < 0) return (int)(1e9);
            return query(1, 0, size - 1, Math.max(0, l), r);
        }

        private int query(int node, int tl, int tr, int l, int r) {
            if (l > r) return (int)(1e9);
            if (tl == l && tr == r) return tree[node];
            int mid = (tl + tr) / 2;
            return Math.min(
                query(node * 2, tl, mid, l, Math.min(r, mid)),
                query(node * 2 + 1, mid + 1, tr, Math.max(mid + 1, l), r)
            );
        }
    }

