    static class SegmentTree {
        private final int[] seg;
        private final int[] base;
        private final int n;

        public SegmentTree(int size) {
            n = size;
            base = new int[n];
            seg = new int[4 * n];
            Arrays.fill(base, (int)(1e9));
            Arrays.fill(seg, (int)(1e9));
        }

        public void update(int idx, int val) {
            base[idx] = val;
            int node = 1, l = 0, r = n - 1;
            while (l < r) {
                int mid = (l + r) >>> 1;
                if (idx <= mid) {
                    r = mid;
                    node <<= 1;
                } else {
                    l = mid + 1;
                    node = (node << 1) | 1;
                }
            }
            seg[node] = val;
            for (node >>= 1; node > 0; node >>= 1) {
                seg[node] = Math.min(seg[node << 1], seg[(node << 1) | 1]);
            }
        }

        public int getValue(int idx) {
            return idx < 0 ? (int)(1e9) : base[idx];
        }

        public int minQuery(int ql, int qr) {
            if (qr < 0) return (int)(1e9);
            return query(1, 0, n - 1, Math.max(0, ql), qr);
        }

        private int query(int node, int tl, int tr, int l, int r) {
            if (l > r) return (int)(1e9);
            if (l == tl && r == tr) return seg[node];
            int mid = (tl + tr) >>> 1;
            return Math.min(
                query(node << 1, tl, mid, l, Math.min(r, mid)),
                query((node << 1) | 1, mid + 1, tr, Math.max(l, mid + 1), r)
            );
        }
    }

