      reader = new BufferedReader(new InputStreamReader(in));
    }

    private void fillBuffer() throws IOException {
      String line = reader.readLine();
      if (line != null) {
        buffer = line.split(" +");
        index = 0;
      }
    }

    private String nextToken() throws IOException {
      if (buffer == null || index >= buffer.length) {
        fillBuffer();
      }
      return buffer[index++];
    }

    long nextLong() throws IOException {
      return Long.parseLong(nextToken());
    }
  }

  static final long[] ONES = new long[17];

  static {
    for (int i = 0; i < ONES.length; i++) {
      if (i == 0) ONES[i] = 0;
      else ONES[i] = ONES[i-1] * 10 + 1;
    }
  }

  public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    long n = sc.nextLong();
    System.out.println(process(n));
  }

  static long process(long value) {
    if (value <= 6) return value;
    int len = String.valueOf(value).length();
    long rep = ONES[len];
    if (value == rep) return len;
    long lower = rep;
    long upper = ONES[len + 1];
    long option1 = process(value % lower) + (value / lower) * len;
    long option2 = Long.MAX_VALUE;
    if (upper - value < value) {
      option2 = process(upper - value) + (len + 1);
    }
    return Math.min(option1, option2);
  }
