public class x440C_v1 {
    private static final long[] powers = new long[16];

    static {
        powers[0] = 1L;
        for (int i = 1; i < 16; i++) {
            powers[i] = powers[i - 1] * 10;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine().trim();
        int length = line.length();
        int[] digits = new int[length];
        for (int i = 0; i < length; i++) {
            digits[i] = Character.getNumericValue(line.charAt(i));
        }
        long value = Long.parseLong(line);
        System.out.println(computeMinSteps(value));
    }

    private static int computeMinSteps(long n) {
        if (n <= 11) {
            if (n == 11) return 2;
            if (n == 10) return 3;
            if (n == 9) return 4;
            if (n == 8) return 5;
            if (n == 7) return 6;
            return (int) n;
        }
        int digitCount = String.valueOf(n).length();
        long sumOfPowers = 0;
        for (int i = 0; i <= digitCount; i++) {
            sumOfPowers += powers[i];
        }
        int minSteps = Integer.MAX_VALUE;
        long candidate = sumOfPowers - n;
        if (n > candidate) {
            minSteps = Math.min(minSteps, digitCount + 1 + computeMinSteps(candidate));
        }
        sumOfPowers -= powers[digitCount];
        long firstDigitValue = n / powers[digitCount - 1];
        for (int digit = 1; digit <= 9; digit++) {
            long transformed = sumOfPowers * digit;
            if (digit == firstDigitValue || digit == firstDigitValue - 1) {
                minSteps = Math.min(minSteps, digit * digitCount + computeMinSteps(Math.abs(transformed - n)));
            }
        }
        return minSteps;
    }
}

