        int len = (num == 0) ? 1 : (int)(Math.log10(Math.abs(num))) + 1;
        System.out.println(computeResult(num, len));
    }

    private static long repunit(int k) {
        return (long)((Math.pow(10, k) - 1) / 9);
    }

    private static long computeResult(long value, int length) {
        if (value == 0) return 0;
        long rep = repunit(length);
        long multiples = value / rep * length;
        value %= rep;
        if (value == 0) return multiples;
        long alt1 = length + computeResult(rep - value, length - 1);
        long alt2 = computeResult(value, length - 1);
        return multiples + Math.min(alt1, alt2);
    }
}

