    }

    private static long generateRepunit(int digits) {
        return (long)((Math.pow(10, digits) - 1) / 9);
    }

    private static long solve(long n, int d) {
        if (n == 0) return 0;
        long repunit = generateRepunit(d);
        long count = (n / repunit) * d;
        n %= repunit;
        if (n == 0) return count;
        long pathA = d + solve(repunit - n, d - 1);
        long pathB = solve(n, d - 1);
        return count + Math.min(pathA, pathB);
    }
}

