        return (long)((Math.pow(10, count) - 1) / 9);
    }

    private static long process(long x, int len) {
        if (x == 0) return 0;
        long ones = makeOnes(len);
        long base = (x / ones) * len;
        x %= ones;
        if (x == 0) return base;
