        long n = scan.nextLong();
        int m = (n == 0) ? 1 : (int)(Math.log10(Math.abs(n))) + 1;
        System.out.println(f(n, m));
    }

    private static long g(int k) {
        return (long)((Math.pow(10, k) - 1) / 9);
    }

    private static long f(long x, int y) {
        if (x == 0) return 0;
        long r = g(y);
        long t = (x / r) * y;
        x %= r;
        if (x == 0) return t;
        long a = y + f(r - x, y - 1);
        long b = f(x, y - 1);
        return t + Math.min(a, b);
    }
}

