public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());
        System.out.println(computeOnes(n));
    }

    private static int countDigits(long num) {
        if (num == 0) return 1;
        return (int) Math.log10(num) + 1;
    }

    private static long constructRepunit(int length) {
        long result = 1;
        for (int i = 1; i < length; i++) {
            result = result * 10 + 1;
        }
        return result;
    }

    private static long computeOnes(long n) {
        if (n <= 6) return n;
        int digits = countDigits(n);
        long repunit = constructRepunit(digits);
        long base = repunit;
        long remainder = n;
        int count = 0;

        while (repunit < n) {
            count++;
            remainder = n - repunit;
            repunit += base;
        }

        long option1 = Long.MAX_VALUE, option2 = Long.MAX_VALUE;
        if (count > 0) {
            option1 = (long) count * digits + computeOnes(remainder);
            option2 = (long) (count + 1) * digits + computeOnes(repunit - n);
        } else {
            option2 = (long) (count + 1) * digits + computeOnes(repunit - n);
        }

        long option3 = Long.MAX_VALUE;
        long nextRepunit = constructRepunit(digits + 1);
        if (nextRepunit - n < n) {
            option3 = (long) (digits + 1) + computeOnes(nextRepunit - n);
        }

        return Math.min(Math.min(option1, option2), option3);
    }
}

