public class OneBasedArithmetic {
    public static void main(String[] args) {
        FastReader sc = new FastReader();
        long n = sc.nextLong();
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = ones[i-1] * 10 + 1;
        }
        long result = solve(ones, n, 16);
        System.out.println(result);
    }

    private static long solve(long[] ones, long n, int idx) {
        long quotient = n / ones[idx];
        n %= ones[idx];
        long count = quotient * idx;
        if (n == 0) {
            return count;
        }
        long option1 = count + solve(ones, n, idx - 1);
        long option2 = count + idx + solve(ones, ones[idx] - n, idx - 1);
        return Math.min(option1, option2);
    }

    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        public String next() {
            try {
                return nextToken();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

