public class OneBasedArithmetic {
    public static void main(String[] args) {
        FastReader sc = new FastReader();
        long n = sc.nextLong();
        long[] ones = new long[17];
        for (int i = 1; i < 17; ++i) {
            ones[i] = (i == 1) ? 1 : (ones[i-1] * 10 + 1);
        }
        long answer = compute(ones, n, 16);
        System.out.println(answer);
    }

    private static long compute(long[] ones, long value, int position) {
        long base = ones[position];
        long multiples = value / base;
        long remainder = value % base;
        long contribution = multiples * position;
        if (remainder == 0) {
            return contribution;
        }
        long forward = contribution + compute(ones, remainder, position - 1);
        long backward = contribution + position + compute(ones, base - remainder, position - 1);
        return Math.min(forward, backward);
    }

    private static class FastReader {
        private BufferedReader reader;
        private String[] buffer;
        private int index;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            buffer = new String[0];
            index = 0;
        }

        private String readNext() throws IOException {
            if (index >= buffer.length) {
                buffer = reader.readLine().split("\\s+");
                index = 0;
            }
            return buffer[index++];
        }

        public String next() {
            try {
                return readNext();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class OneBasedArithmetic {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine().trim());
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = ones[i-1] * 10 + 1;
        }
        long result = calculate(ones, n, 16);
        System.out.println(result);
    }

    private static long calculate(long[] ones, long num, int level) {
        long unit = ones[level];
        long times = num / unit;
        long leftover = num % unit;
        long steps = times * level;
        if (leftover == 0) {
            return steps;
        }
        long pathA = steps + calculate(ones, leftover, level - 1);
        long pathB = steps + level + calculate(ones, unit - leftover, level - 1);
        return Math.min(pathA, pathB);
    }

    private static class FastReader {
        private final BufferedReader br;
        private String[] tokens;
        private int tokenIndex;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
            tokens = new String[0];
            tokenIndex = 0;
        }

        private String fetchToken() throws IOException {
            while (tokenIndex >= tokens.length) {
                tokens = br.readLine().split("\\s+");
                tokenIndex = 0;
            }
            return tokens[tokenIndex++];
        }

        public String next() {
            try {
                return fetchToken();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class OneBasedArithmetic {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        long target = Long.parseLong(in.readLine());
        long[] repUnits = new long[17];
        for (int k = 1; k < 17; k++) {
            repUnits[k] = repUnits[k-1] * 10 + 1;
        }
        long answer = process(repUnits, target, 16);
        System.out.println(answer);
    }

    private static long process(long[] units, long remaining, int depth) {
        long unitValue = units[depth];
        long count = remaining / unitValue;
        long residue = remaining % unitValue;
        long cost = count * depth;
        if (residue == 0) {
            return cost;
        }
        long cost1 = cost + process(units, residue, depth - 1);
        long cost2 = cost + depth + process(units, unitValue - residue, depth - 1);
        return Math.min(cost1, cost2);
    }

    private static class FastReader {
        private final BufferedReader reader;
        private Iterator<String> tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = Collections.emptyIterator();
        }

        private String advance() throws IOException {
            while (!tokenizer.hasNext()) {
                tokenizer = Arrays.asList(reader.readLine().split("\\s+")).iterator();
            }
            return tokenizer.next();
        }

        public String next() {
            try {
                return advance();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class OneBasedArithmetic {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long input = Long.parseLong(br.readLine());
        long[] sequence = new long[17];
        for (int pos = 1; pos < 17; pos++) {
            sequence[pos] = sequence[pos-1] * 10 + 1;
        }
        long output = evaluate(sequence, input, 16);
        System.out.println(output);
    }

    private static long evaluate(long[] seq, long val, int lvl) {
        long unit = seq[lvl];
        long factor = val / unit;
        long rem = val % unit;
        long steps = factor * lvl;
        if (rem == 0) {
            return steps;
        }
        long alt1 = steps + evaluate(seq, rem, lvl - 1);
        long alt2 = steps + lvl + evaluate(seq, unit - rem, lvl - 1);
        return Math.min(alt1, alt2);
    }

    private static class FastReader {
        private final BufferedReader input;
        private String[] buffer;
        private int pos;

        public FastReader() {
            input = new BufferedReader(new InputStreamReader(System.in));
            buffer = new String[0];
            pos = 0;
        }

        private String pull() throws IOException {
            if (pos >= buffer.length) {
                buffer = input.readLine().split(" +");
                pos = 0;
            }
            return buffer[pos++];
        }

        public String next() {
            try {
                return pull();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return input.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

