public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class Reader {
        private final byte[] buf = new byte[1 << 15];
        private int pos = 0, len = 0;
        private final InputStream stream;

        Reader(InputStream is) { stream = is; }

        private int nextByte() throws IOException {
            if (pos >= len) {
                len = stream.read(buf);
                pos = 0;
                if (len <= 0) return -1;
            }
            return buf[pos++];
        }

        int nextInt() throws IOException {
            int b;
            while ((b = nextByte()) <= 32) if (b == -1) return -1;
            int n = 0;
            while (b > 32) {
                n = n * 10 + (b - '0');
                b = nextByte();
            }
            return n;
        }
    }

    Reader rd;

    public static void main(String[] args) {
        CF1187G solver = new CF1187G();
        solver.rd = new Reader(System.in);
        solver.solve();
        solver.flush();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] adjList;
    int nodeCount, edgeCount;
    int[] pi, d, prev;
    int[] u, v, uv, c;
    int[] cap;

    void setup(int nodes, int edges) {
        adjList = new ArrayList[nodes];
        for (int i = 0; i < nodes; i++) adjList[i] = new ArrayList<>();
        pi = new int[nodes];
        d = new int[nodes];
        prev = new int[nodes];
        u = new int[edges];
        v = new int[edges];
        uv = new int[edges];
        c = new int[edges];
        cap = new int[edges * 2];
        edgeCount = 0;
    }

    void connect(int from, int to, int capacity, int cost) {
        int idx = edgeCount++;
        u[idx] = from;
        v[idx] = to;
        uv[idx] = from ^ to;
        c[idx] = cost;
        cap[idx * 2] = capacity;
        adjList[from].add(idx * 2);
        adjList[to].add(idx * 2 + 1);
    }

    int[] q;
    int qHead, qTail, qLen;
    boolean[] inQ;

    void enqueue(int x) {
        if (inQ[x]) return;
        if (qHead + qTail == q.length) {
            if (qLen * 2 <= q.length) {
                System.arraycopy(q, qHead, q, 0, qLen);
            } else {
                int[] nq = new int[q.length * 2];
                System.arraycopy(q, qHead, nq, 0, qLen);
                q = nq;
            }
            qHead = 0;
        }
        q[qHead + qTail++] = x;
        inQ[x] = true;
    }

    int dequeue() {
        int x = q[qHead++];
        qLen--;
        inQ[x] = false;
        return x;
    }

    boolean findShortestPath(int src, int dst) {
        Arrays.fill(pi, INF);
        pi[src] = 0;
        qHead = qTail = 0;
        enqueue(src);

        while (qLen > 0) {
            int cur = dequeue();
            int nd = d[cur] + 1;

            for (int e : adjList[cur]) {
                if (cap[e] > 0) {
                    int idx = e >> 1;
                    int cost = (e & 1) == 0 ? c[idx] : -c[idx];
                    int np = pi[cur] + cost;
                    int to = cur ^ uv[idx];

                    if (pi[to] > np || (pi[to] == np && d[to] > nd)) {
                        pi[to] = np;
                        d[to] = nd;
                        prev[to] = e;
                        enqueue(to);
                    }
                }
            }
        }
        return pi[dst] != INF;
    }

    void augment(int src, int dst) {
        int minCap = INF;
        for (int node = dst; node != src; node ^= uv[prev[node] >> 1]) {
            minCap = Math.min(minCap, cap[prev[node]]);
        }
        for (int node = dst; node != src; node ^= uv[prev[node] >> 1]) {
            int e = prev[node];
            cap[e] -= minCap;
            cap[e ^ 1] += minCap;
        }
    }

    void augmentUnit(int src, int dst) {
        for (int node = dst; node != src; node ^= uv[prev[node] >> 1]) {
            int e = prev[node];
            cap[e]--;
            cap[e ^ 1]++;
        }
    }

    int computeMinCostFlow(int src, int dst) {
        while (findShortestPath(src, dst)) {
            augmentUnit(src, dst);
        }
        int total = 0;
        for (int i = 0; i < edgeCount; i++) {
            total += c[i] * cap[i * 2 + 1];
        }
        return total;
    }

    void solve() {
        try {
            int n = rd.nextInt();
            int m = rd.nextInt();
            int k = rd.nextInt();
            int c = rd.nextInt();
            int d = rd.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) {
                special[i] = rd.nextInt() - 1;
            }

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int a = rd.nextInt() - 1;
                int b = rd.nextInt() - 1;
                g[a].add(b);
                g[b].add(a);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);

            setup(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int w : g[i]) {
                        int v = w * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            connect(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    connect(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                connect(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(computeMinCostFlow(totalNodes - 1, 0 * T + T - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

