                    int np = pi[u] + c;
                    int v = u ^ xorVal[idx];

                    if (pi[v] > np || (pi[v] == np && dist[v] > nd)) {
                        pi[v] = np;
                        dist[v] = nd;
                        prevEdge[v] = e;
                        push(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void augment(int s, int t) {
        int minCap = INF;
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            minCap = Math.min(minCap, cap[prevEdge[v]]);
        }
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            cap[e] -= minCap;
            cap[e ^ 1] += minCap;
        }
    }

    void augmentUnit(int s, int t) {
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            cap[e]--;
            cap[e ^ 1]++;
        }
    }

    int minCostFlow(int s, int t) {
        while (spfa(s, t)) {
            augmentUnit(s, t);
        }
        int total = 0;
        for (int i = 0; i < M; i++) {
            total += cost[i] * cap[i * 2 + 1];
        }
        return total;
    }

    void process() {
        try {
            int n = input.nextInt();
            int m = input.nextInt();
            int k = input.nextInt();
            int c = input.nextInt();
            int d = input.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) {
                special[i] = input.nextInt() - 1;
            }

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = input.nextInt() - 1;
                int v = input.nextInt() - 1;
                g[u].add(v);
                g[v].add(u);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);

            build(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int w : g[i]) {
                        int v = w * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            add(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    add(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                add(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(minCostFlow(totalNodes - 1, 0 * T + T - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class FastInput {
        private final byte[] buffer = new byte[1 << 15];
        private int pos = 0, size = 0;
        private final InputStream stream;

        FastInput(InputStream is) { stream = is; }

        private int fetch() throws IOException {
            if (pos >= size) {
                size = stream.read(buffer);
                pos = 0;
                if (size <= 0) return -1;
            }
            return buffer[pos++];
        }

        int nextInt() throws IOException {
            int ch;
            while ((ch = fetch()) <= 32) if (ch == -1) return -1;
            int num = 0;
            while (ch > 32) {
                num = num * 10 + ch - '0';
                ch = fetch();
            }
            return num;
        }
    }

    FastInput in;

    public static void main(String[] args) {
        CF1187G solver = new CF1187G();
        solver.in = new FastInput(System.in);
        solver.run();
        solver.flush();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] graph;
    int nodeCount, edgeCount;
    int[] potential, level, prevEdge;
    int[] src, dst, xorEdge, weight;
    int[] capacity;

    void setup(int n, int m) {
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        potential = new int[n];
        level = new int[n];
        prevEdge = new int[n];
        src = new int[m];
        dst = new int[m];
        xorEdge = new int[m];
        weight = new int[m];
        capacity = new int[m * 2];
        edgeCount = 0;
    }

    void link(int u, int v, int cap, int c) {
        int idx = edgeCount++;
        src[idx] = u;
        dst[idx] = v;
        xorEdge[idx] = u ^ v;
        weight[idx] = c;
        capacity[idx * 2] = cap;
        graph[u].add(idx * 2);
        graph[v].add(idx * 2 + 1);
    }

    int[] queue;
    int queueStart, queueEnd, queueLength;
    boolean[] inQueue;

    void offer(int v) {
        if (inQueue[v]) return;
        if (queueStart + queueEnd == queue.length) {
            if (queueLength * 2 <= queue.length) {
                System.arraycopy(queue, queueStart, queue, 0, queueLength);
            } else {
                int[] newQueue = new int[queue.length * 2];
                System.arraycopy(queue, queueStart, newQueue, 0, queueLength);
                queue = newQueue;
            }
            queueStart = 0;
        }
        queue[queueStart + queueEnd++] = v;
        inQueue[v] = true;
    }

    int poll() {
        int v = queue[queueStart++];
        queueLength--;
        inQueue[v] = false;
        return v;
    }

    boolean findPath(int source, int sink) {
        Arrays.fill(potential, INF);
        potential[source] = 0;
        queueStart = queueEnd = 0;
        offer(source);

        while (queueLength > 0) {
            int u = poll();
            int newLevel = level[u] + 1;

            for (int edge : graph[u]) {
                if (capacity[edge] > 0) {
                    int idx = edge >> 1;
                    int c = (edge & 1) == 0 ? weight[idx] : -weight[idx];
                    int newPotential = potential[u] + c;
                    int v = u ^ xorEdge[idx];

                    if (potential[v] > newPotential || 
                        (potential[v] == newPotential && level[v] > newLevel)) {
                        potential[v] = newPotential;
                        level[v] = newLevel;
                        prevEdge[v] = edge;
                        offer(v);
                    }
                }
            }
        }
        return potential[sink] != INF;
    }

    void augment(int source, int sink) {
        int minCap = INF;
        for (int v = sink; v != source; v ^= xorEdge[prevEdge[v] >> 1]) {
            minCap = Math.min(minCap, capacity[prevEdge[v]]);
        }
        for (int v = sink; v != source; v ^= xorEdge[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            capacity[e] -= minCap;
            capacity[e ^ 1] += minCap;
        }
    }

    void augmentUnit(int source, int sink) {
        for (int v = sink; v != source; v ^= xorEdge[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            capacity[e]--;
            capacity[e ^ 1]++;
        }
    }

    int minCostMaxFlow(int source, int sink) {
        while (findPath(source, sink)) {
            augmentUnit(source, sink);
        }
        int total = 0;
        for (int i = 0; i < edgeCount; i++) {
            total += weight[i] * capacity[i * 2 + 1];
        }
        return total;
    }

    void run() {
        try {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();
            int c = in.nextInt();
            int d = in.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) {
                special[i] = in.nextInt() - 1;
            }

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                g[u].add(v);
                g[v].add(u);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);

            setup(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int neighbor : g[i]) {
                        int v = neighbor * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            link(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    link(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                link(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(minCostMaxFlow(totalNodes - 1, 0 * T + T - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

