    static class TaskE {
        class MinCostMaxFlow {
            ArrayList<Edge>[] al;
            Edge[][] ja;
            int[] d;
            int N, S, T, maxFlow, minCost;
            final int gmax = Integer.MAX_VALUE / 100;
            int edges = 0;

            class Edge {
                int u, flow, rid, cost;
                Edge(int a, int b, int c, int d) {
                    u = a;
                    flow = b;
                    cost = c;
                    rid = d;
                }
            }

            void addEdge(int u, int v, int flow, int cost) {
                int lu = al[u].size(), lv = al[v].size();
                al[u].add(new Edge(v, flow, cost, lv));
                al[v].add(new Edge(u, 0, -cost, lu));
            }

            void convertToArray() {
                ja = new Edge[N][];
                for (int i = 0; i < N; i++) {
                    int sz = al[i].size();
                    ja[i] = new Edge[sz];
                    for (int j = 0; j < sz; j++) {
                        ja[i][j] = al[i].get(j);
                    }
                    al[i].clear();
                }
            }

            MinCostMaxFlow(int n, int source, int sink) {
                N = n;
                S = source;
                T = sink;
                maxFlow = 0;
                minCost = 0;
                al = new ArrayList[N];
                d = new int[N];
                for (int i = 0; i < N; i++) {
                    al[i] = new ArrayList<>();
                }
            }

            boolean BellmanFord(boolean check) {
                Arrays.fill(d, gmax);
                d[S] = 0;
                for (int i = 0; i < N - 1; i++) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : ja[j]) {
                            if (e.flow == 0) continue;
                            if (d[j] != gmax && d[e.u] > d[j] + e.cost) {
                                d[e.u] = d[j] + e.cost;
                            }
                        }
                    }
                }
                if (check) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : ja[j]) {
                            if (e.flow == 0) continue;
                            if (d[j] != gmax && d[j] + e.cost < d[e.u]) return false;
                        }
                    }
                }
                return true;
            }

            int[] node, visit, prv, prve, dist;

            boolean simple() {
                node = new int[N];
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, gmax);

                node[0] = S;
                dist[S] = 0;
                int front = 1, back = 0;
                while (front != back) {
                    int u = node[back++];
                    if (back == N) back = 0;
                    visit[u] = 2;
                    for (int i = 0; i < ja[u].length; i++) {
                        Edge e = ja[u][i];
                        if (e.flow == 0) continue;
                        int cdist = dist[u] + e.cost;
                        if (cdist < dist[e.u]) {
                            if (visit[e.u] == 0) {
                                node[front] = e.u;
                                if (++front == N) front = 0;
                            } else if (visit[e.u] == 2) {
                                if (--back == -1) back += N;
                                node[back] = e.u;
                            }
                            visit[e.u] = 1;
                            prve[e.u] = i;
                            prv[e.u] = u;
                            dist[e.u] = cdist;
                        }
                    }
                }
                return visit[T] != 0;
