                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, gmax);
                PriorityQueue<pair> pq = new PriorityQueue<>((A, B) -> Integer.compare(A.S, B.S));

                pq.add(new pair(S, 0));
                dist[S] = 0;
                outer: while (!pq.isEmpty()) {
                    pair p = pq.poll();
                    while (dist[p.F] < p.S) {
                        if (pq.isEmpty()) break outer;
                        p = pq.poll();
                    }
                    visit[p.F] = 2;
                    for (int i = 0; i < ja[p.F].length; i++) {
                        Edge e = ja[p.F][i];
                        if (e.flow == 0) continue;
                        int cdist = p.S + (e.cost + d[p.F] - d[e.u]);
                        if (cdist < dist[e.u]) {
                            if (visit[e.u] == 2) return false;
                            pq.add(new pair(e.u, cdist));
                            dist[e.u] = cdist;
                            prv[e.u] = p.F;
                            prve[e.u] = i;
                            visit[e.u] = 1;
                        }
                    }
                }
                return visit[T] != 0;
            }

            int augment() {
