            void convertToArray() {
                ja = new Edge[N][];
                for (int i = 0; i < N; i++) {
                    int sz = al[i].size();
                    ja[i] = new Edge[sz];
                    for (int j = 0; j < sz; j++) {
                        ja[i][j] = al[i].get(j);
                    }
                    al[i].clear();
                }
