            boolean BellmanFord(boolean check) {
                Arrays.fill(d, INF);
                d[S] = 0;
                for (int i = 0; i < N - 1; i++) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : ja[j]) {
                            if (e.flow == 0) continue;
                            if (d[j] != INF && d[e.u] > d[j] + e.cost) {
                                d[e.u] = d[j] + e.cost;
                            }
                        }
                    }
                }
                if (check) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : ja[j]) {
                            if (e.flow == 0) continue;
                            if (d[j] != INF && d[j] + e.cost < d[e.u]) return false;
                        }
                    }
                }
                return true;
            }

            int[] node, visit, prv, prve, dist;

            boolean simple() {
                node = new int[N];
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, INF);

                node[0] = S;
                dist[S] = 0;
                int front = 1, back = 0;
                while (front != back) {
                    int u = node[back++];
                    if (back == N) back = 0;
                    visit[u] = 2;
                    for (int i = 0; i < ja[u].length; i++) {
                        Edge e = ja[u][i];
                        if (e.flow == 0) continue;
                        int cdist = dist[u] + e.cost;
                        if (cdist < dist[e.u]) {
                            if (visit[e.u] == 0) {
                                node[front] = e.u;
                                if (++front == N) front = 0;
                            } else if (visit[e.u] == 2) {
                                if (--back == -1) back += N;
                                node[back] = e.u;
                            }
                            visit[e.u] = 1;
                            prve[e.u] = i;
                            prv[e.u] = u;
                            dist[e.u] = cdist;
                        }
                    }
                }
                return visit[T] != 0;
            }

            static class Pair implements Comparable<Pair> {
                final int F, S;
                Pair(int a, int b) {
                    F = a;
                    S = b;
                }
                @Override
                public int compareTo(Pair other) {
                    return Integer.compare(this.S, other.S);
                }
            }

            boolean dijkstra() {
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, INF);
                PriorityQueue<Pair> pq = new PriorityQueue<>();

                pq.add(new Pair(S, 0));
                dist[S] = 0;
                outer: while (!pq.isEmpty()) {
                    Pair p = pq.poll();
                    while (dist[p.F] < p.S) {
                        if (pq.isEmpty()) break outer;
                        p = pq.poll();
                    }
                    visit[p.F] = 2;
                    for (int i = 0; i < ja[p.F].length; i++) {
                        Edge e = ja[p.F][i];
                        if (e.flow == 0) continue;
                        int cdist = p.S + (e.cost + d[p.F] - d[e.u]);
                        if (cdist < dist[e.u]) {
                            if (visit[e.u] == 2) return false;
                            pq.add(new Pair(e.u, cdist));
                            dist[e.u] = cdist;
                            prv[e.u] = p.F;
                            prve[e.u] = i;
                            visit[e.u] = 1;
                        }
                    }
                }
                return visit[T] != 0;
            }

            int augment() {
                int p = T;
                int min = INF;
                while (p != S) {
                    int pp = prv[p], pe = prve[p];
                    int val = ja[pp][pe].flow;
                    min = Math.min(min, val);
                    p = pp;
                }
                p = T;
                while (p != S) {
                    int pp = prv[p], pe = prve[p];
                    ja[pp][pe].flow -= min;
                    ja[p][ja[pp][pe].rid].flow += min;
                    p = pp;
                }
                maxFlow += min;
                return min;
            }

            boolean calSimple() {
                while (simple()) {
                    minCost += dist[T] * augment();
                }
                return true;
            }

            void updPotential() {
                for (int i = 0; i < N; i++) {
                    if (visit[i] != 0) {
                        d[i] += dist[i] - dist[S];
                    }
                }
            }

            boolean calWithPotential() {
                while (dijkstra()) {
                    int min = dist[T] + d[T] - d[S];
                    minCost += min * augment();
                    updPotential();
                }
                return true;
            }
        }

