        if(n < K) {
            qs.add(n<<32|prev);
            if(qs.size() % 100000 == 0)tr(qs.size());
            ct++;
            if(ct % 1000000 == 0)tr(ct);
        }else {
            int u = Arrays.binarySearch(primes, (int)Math.sqrt(n));
