        dfs1(n, 0, K, qs, primes);
        tr(qs.size());

        return null;
    }

    int ct = 0;

    void dfs1(long n, int prev, int K, List<Long> qs, int[] primes) {
        if(n < K) {
            qs.add((n << 32) | prev);
            if(qs.size() % 100000 == 0)tr(qs.size());
            ct++;
            if(ct % 1000000 == 0)tr(ct);
        }else {
            int limit = (int)Math.sqrt(n);
            int u = Arrays.binarySearch(primes, limit);
            if(u < 0)u = -u-2;
            for(int i = u; i >= 0; i--) {
