    long computePrimeCount(long n) {
        final int LIMIT = 400000;
        long[] piUpper = new long[LIMIT];
        long[] piLower = new long[LIMIT];

        for (int i = 1; i < LIMIT; i++) {
            piLower[i] = i;
            piUpper[i] = n / i;
        }

        boolean[] isPrime = new boolean[LIMIT];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;

        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i < LIMIT; i++) {
            if (isPrime[i]) {
                primes.add(i);
                for (int j = i * 2; j < LIMIT; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        for (int t = 0; t < primes.size(); t++) {
            int p = primes.get(t);
            for (int i = 1; i < LIMIT && n / i >= (long) p * p; i++) {
                long term = ((long) p * i < LIMIT) ? piUpper[p * i] : piLower[(int) (n / i / p)];
                piUpper[i] -= term - (t + 1);
            }
            for (int i = LIMIT - 1; i >= (long) p * p; i--) {
                piLower[i] -= piLower[i / p] - (t + 1);
            }
        }

        long result = 0;
        for (int p : primes) {
            if ((long) p * p > n) break;
            if ((long) p * p * p <= n && (long) p * p * p > 0) {
                result++;
            }
            if (n / p > p) {
                if (p < LIMIT) {
                    result += piUpper[p] - piLower[p];
                } else {
                    result += piLower[(int) (n / p)] - piLower[p];
                }
            }
        }
        return result;
    }
}

