    long calculatePi(long n) {
        int size = 400000;
        long[] upper = new long[size];
        long[] lower = new long[size];

        for (int idx = 1; idx < size; idx++) {
            lower[idx] = idx;
            upper[idx] = n / idx;
        }

        boolean[] primeFlags = new boolean[size];
        Arrays.fill(primeFlags, true);
        primeFlags[0] = false;
        primeFlags[1] = false;

        List<Integer> primes = new ArrayList<>();
        for (int num = 2; num < size; num++) {
            if (!primeFlags[num]) continue;
            primes.add(num);
            for (int multiple = num * 2; multiple < size; multiple += num) {
                primeFlags[multiple] = false;
            }
        }

        for (int index = 0; index < primes.size(); index++) {
            int prime = primes.get(index);
            for (int i = 1; i < size && n / i >= (long) prime * prime; i++) {
                long value = ((long) prime * i < size) ? upper[prime * i] : lower[(int) (n / i / prime)];
                upper[i] -= value - (index + 1);
            }
            for (int i = size - 1; i >= (long) prime * prime; i--) {
                lower[i] -= lower[i / prime] - (index + 1);
            }
        }

        long count = 0;
        for (int prime : primes) {
            if ((long) prime * prime > n) break;
            if ((long) prime * prime * prime <= n && (long) prime * prime * prime > 0) {
                count++;
            }
            if (n / prime > prime) {
                if (prime < size) {
                    count += upper[prime] - lower[prime];
                } else {
                    count += lower[(int) (n / prime)] - lower[prime];
                }
            }
        }
        return count;
    }
}

