        long[] piU = new long[LIMIT];
        long[] piL = new long[LIMIT];

        for (int i = 1; i < LIMIT; i++) {
            piL[i] = i;
            piU[i] = n / i;
        }

        boolean[] isComposite = new boolean[LIMIT];
        isComposite[0] = isComposite[1] = true;

        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i < LIMIT; i++) {
