        }

        for (int t = 0; t < primes.size(); t++) {
            int p = primes.get(t);
            for (int i = 1; i < LIMIT && n / i >= (long) p * p; i++) {
                long term = ((long) p * i < LIMIT) ? piU[p * i] : piL[(int) (n / i / p)];
                piU[i] -= term - (t + 1);
            }
            for (int i = LIMIT - 1; i >= (long) p * p; i--) {
                piL[i] -= piL[i / p] - (t + 1);
            }
        }

        long answer = 0;
        for (int p : primes) {
            if ((long) p * p > n) break;
            if ((long) p * p * p <= n && (long) p * p * p > 0) {
                answer++;
            }
            if (n / p > p) {
                if (p < LIMIT) {
                    answer += piU[p] - piL[p];
                } else {
                    answer += piL[(int) (n / p)] - piL[p];
                }
            }
        }
        return answer;
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        System.out.println(computeResult(n));
    }

    long computeResult(long n) {
        int SIZE = 400000;
        long[] upper = new long[SIZE];
        long[] lower = new long[SIZE];

        for (int i = 1; i < SIZE; i++) {
            lower[i] = i;
            upper[i] = n / i;
        }

        boolean[] prime = new boolean[SIZE];
        Arrays.fill(prime, true);
        prime[0] = false;
        prime[1] = false;

        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i < SIZE; i++) {
            if (prime[i]) {
                primes.add(i);
                for (int j = i * 2; j < SIZE; j += i) {
                    prime[j] = false;
                }
            }
        }

        for (int t = 0; t < primes.size(); t++) {
            int p = primes.get(t);
            for (int i = 1; i < SIZE && n / i >= (long) p * p; i++) {
                long val = ((long) p * i < SIZE) ? upper[p * i] : lower[(int) (n / i / p)];
                upper[i] -= val - (t + 1);
            }
            for (int i = SIZE - 1; i >= (long) p * p; i--) {
                lower[i] -= lower[i / p] - (t + 1);
            }
        }

        long result = 0;
        for (int p : primes) {
            if ((long) p * p > n) break;
            if ((long) p * p * p <= n && (long) p * p * p > 0) {
                result++;
            }
            if (n / p > p) {
                if (p < SIZE) {
                    result += upper[p] - lower[p];
                } else {
                    result += lower[(int) (n / p)] - lower[p];
                }
            }
        }
        return result;
    }
}

