			ret -= (long)(B-A)*(B+A-1)/2;
			return ret;
		}

		private long P3(long x, int A)
		{
			int C = (int)pi(Math.max(0, (int)cbrt(x)));
			long ret = 0;
			for(int i = A;i < C;i++){
