                int pos = h(x) & mask;
                while (allocated[pos] != NG) {
                    if (x == keys[pos]) return allocated[pos];
                    pos = pos + 1 & mask;
                }
                return NG;
            }

            public long put(long x, long v) {
                int pos = h(x) & mask;
                while (allocated[pos] != NG) {
                    if (x == keys[pos]) {
                        long oldval = allocated[pos];
                        allocated[pos] = v;
                        return oldval;
                    }
                    pos = pos + 1 & mask;
                }
                if (size == rscale) {
                    resizeAndPut(x, v);
                } else {
                    keys[pos] = x;
                    allocated[pos] = v;
                }
                size++;
                return 0;
            }

            private void resizeAndPut(long x, long v) {
                int nscale = scale << 1;
                int nrscale = rscale << 1;
                int nmask = nscale - 1;
                long[] nallocated = new long[nscale];
                Arrays.fill(nallocated, NG);
                long[] nkeys = new long[nscale];
                for (int i = next(0); i < scale; i = next(i + 1)) {
                    long y = keys[i];
                    int pos = h(y) & nmask;
                    while (nallocated[pos] != NG) pos = pos + 1 & nmask;
                    nkeys[pos] = y;
                    nallocated[pos] = allocated[i];
                }
                {
                    int pos = h(x) & nmask;
                    while (nallocated[pos] != NG) pos = pos + 1 & nmask;
                    nkeys[pos] = x;
                    nallocated[pos] = v;
                }
                allocated = nallocated;
                keys = nkeys;
                scale = nscale;
                rscale = nrscale;
                mask = nmask;
            }

            public int next(int itr) {
                while (itr < scale && allocated[itr] == NG) itr++;
                return itr;
            }

            private int h(long x) {
                x ^= x >>> 33;
                x *= 0xff51afd7ed558ccdL;
                x ^= x >>> 33;
                x *= 0xc4ceb9fe1a85ec53L;
                x ^= x >>> 33;
                return (int) x;
            }
        }
    }

    private static class FastReader {
        byte[] buffer = new byte[1024];
        int lenbuf = 0, ptrbuf = 0;
        InputStream is;

        FastReader(InputStream is) {
            this.is = is;
        }

        int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try { lenbuf = is.read(buffer); } catch (IOException e) { throw new InputMismatchException(); }
                if (lenbuf <= 0) return -1;
            }
            return buffer[ptrbuf++];
        }

        boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b));
            return b;
        }

        long readLong() {
            long num = 0;
            int b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }
    }

    private long readLong(InputStream is) {
        FastReader fr = new FastReader(is);
        return fr.readLong();
    }
}

