    }

    private static final int MOD = 998244353;

    private void process() {
        try {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            String[] tokens = reader.readLine().trim().split("\\s+");
            int n = Integer.parseInt(tokens[0]);
            int k = Integer.parseInt(tokens[1]);
            int l = Integer.parseInt(tokens[2]);

            long[] factorial = new long[n + 1];
            factorial[0] = 1;
            for (int i = 1; i <= n; i++) {
                factorial[i] = factorial[i - 1] * i % MOD;
            }

            long[][] table = new long[2 * n + 1][2 * n + 2];
            table[0][0] = 1;

            for (int step = 1; step <= 2 * n; step++) {
                for (int count = 0; count <= step; count++) {
                    if (count > 0) {
                        table[step][count] = (table[step][count] + table[step - 1][count - 1]) % MOD;
                    }
                    table[step][count] = (table[step][count] + table[step - 1][count + 1] * (count + 1) % MOD) % MOD;
                }
            }

            long total = 0;
            for (int i = k; i <= 2 * n; i++) {
                for (int j = k; j <= n; j++) {
                    total = (total + table[i][j] * table[2 * n - i][j] % MOD * factorial[j] % MOD) % MOD;
                }
            }

            long invBase1 = modExp(table[2 * n][0], MOD - 2);
            long invBase2 = modExp(2 * n + 1, MOD - 2);
            long finalAnswer = (long) l * total % MOD * invBase1 % MOD * invBase2 % MOD;
            System.out.println(finalAnswer);

        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    private long modExp(long base, long exponent) {
        long result = 1;
        base %= MOD;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }
}

