        new Main().go();
    }

    private static final int MOD = 998244353;

    private void go() {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            String[] parts = br.readLine().split(" +");
            int n = Integer.parseInt(parts[0]);
            int k = Integer.parseInt(parts[1]);
            int l = Integer.parseInt(parts[2]);

            long[] fact = new long[n + 1];
            fact[0] = 1;
            for (int idx = 1; idx <= n; idx++) {
                fact[idx] = fact[idx - 1] * idx % MOD;
            }

            long[][] memo = new long[2 * n + 1][2 * n + 2];
            memo[0][0] = 1;

            for (int step = 1; step <= 2 * n; step++) {
                for (int cnt = 0; cnt <= step; cnt++) {
                    if (cnt > 0) {
                        memo[step][cnt] = (memo[step][cnt] + memo[step - 1][cnt - 1]) % MOD;
                    }
                    memo[step][cnt] = (memo[step][cnt] + memo[step - 1][cnt + 1] * (cnt + 1) % MOD) % MOD;
                }
            }

            long sum = 0;
            for (int i = k; i <= 2 * n; i++) {
                for (int j = k; j <= n; j++) {
                    sum = (sum + memo[i][j] * memo[2 * n - i][j] % MOD * fact[j] % MOD) % MOD;
                }
            }

            long inv1 = fastPow(memo[2 * n][0], MOD - 2);
            long inv2 = fastPow(2 * n + 1, MOD - 2);
            long output = (long) l * sum % MOD * inv1 % MOD * inv2 % MOD;
            System.out.println(output);

        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    private long fastPow(long x, long y) {
        long res = 1;
        x %= MOD;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = (res * x) % MOD;
            }
            x = (x * x) % MOD;
            y >>= 1;
        }
        return res;
    }
}

