public class CF1153F {
    static final int MOD = 998244353;

    static long[][] binom;

    static void buildBinomial(int maxN) {
        binom = new long[maxN + 1][maxN + 1];
        for (int i = 0; i <= maxN; i++) {
            binom[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                binom[i][j] = (binom[i-1][j] + binom[i-1][j-1]) % MOD;
            }
        }
    }

    static long modExp(long base, int exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = br.readLine().split("\\s+");
        int n = Integer.parseInt(tokens[0]);
        int k = Integer.parseInt(tokens[1]);
        int L = Integer.parseInt(tokens[2]);

        buildBinomial(n);

        long[] polyP = new long[2 * n + 1];
        long[] polyQ = new long[2 * n + 1];

        polyP[n] = modExp(2, n);

        for (int step = 0; step < n; step++) {
            for (int deg = 2 * n; deg >= 1; deg--) {
                polyP[deg] = (polyP[deg] - polyP[deg - 1]) % MOD;
            }
        }

        long[] resultPoly = polyP.clone();
        long inv2 = (MOD + 1) / 2;

        for (int iter = 1; iter <= n - k; iter++) {
            // Divide by 2x: shift right and multiply by inv2
            for (int deg = 0; deg < 2 * n; deg++) {
                polyQ[deg] = polyP[deg + 1] * inv2 % MOD;
            }
            polyQ[2 * n] = 0;

            // Divide by (1 - x): prefix sums
            for (int deg = 1; deg <= 2 * n; deg++) {
                polyQ[deg] = (polyQ[deg] + polyQ[deg - 1]) % MOD;
            }

            // Update polyP = polyQ - polyP
            for (int deg = 0; deg <= 2 * n; deg++) {
                polyP[deg] = (polyQ[deg] - polyP[deg]) % MOD;
            }

            long coeff = binom[n][iter];
            for (int deg = 0; deg <= 2 * n; deg++) {
                resultPoly[deg] = (resultPoly[deg] + coeff * polyP[deg]) % MOD;
            }
        }

        // Integrate polynomial
        long integralValue = 0;
        for (int deg = 0; deg <= 2 * n; deg++) {
            integralValue = (integralValue + resultPoly[deg] * modExp(deg + 1, MOD - 2)) % MOD;
        }

        integralValue = (integralValue * L % MOD + MOD) % MOD;
        System.out.println(integralValue);
    }
}

