            for (int i = 0; i < 2 * n; i++) {
                q[i] = p[i + 1] * inv2 % MOD;
            }
            q[2 * n] = 0;

            // Divide by (1 - x): cumulative sum
            for (int i = 1; i <= 2 * n; i++) {
                q[i] = (q[i] + q[i - 1]) % MOD;
