        }

        long[] doubleFact = new long[n+1];
        doubleFact[0] = 1;
        for (int i = 1; i <= n; i++) {
            doubleFact[i] = (doubleFact[i-1] * (2*i - 1)) % MOD;
        }

        long[][] list = new long[2*n+2][n+1];

        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = 1; k <= n; k++) {
