                    num = (num * doubleFact[(r-k-1)/2]) % MOD;
                    num = (num * doubleFact[(2*n+1-r-k)/2]) % MOD;

                    long denom = (fact[r-k-1] * fact[2*n+1-r-k]) % MOD;
                    denom = (denom * fact[k]) % MOD;
                    long fullDenom = (denom * doubleFact[n]) % MOD;

                    list[r][k] = (num * modPow(fullDenom, MOD-2, MOD)) % MOD;
                }
            }
