public class Codeforces1153F {

    public static void main(String[] args) throws IOException {
        final int MOD = 998244353;

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = br.readLine().split("\\s+");
        int n = Integer.parseInt(tokens[0]);
        int real_k = Integer.parseInt(tokens[1]);
        int l = Integer.parseInt(tokens[2]);

        int[] factorial = new int[2*n+2];
        factorial[0] = 1;
        for (int i = 1; i <= 2*n+1; i++) {
            factorial[i] = intMul(factorial[i-1], i, MOD);
        }

        int[] doubleFactorial = new int[n+1];
        doubleFactorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            doubleFactorial[i] = intMul(doubleFactorial[i-1], 2*i-1, MOD);
        }

        int[][] countMatrix = new int[2*n+2][n+1];

        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = 1; k <= n; k++) {
                if ((r % 2 != k % 2) && (r - 1 >= k) && (2*n+1 - r >= k)) {
                    int top = intMul(intMul(factorial[r-1], factorial[2*n+1-r], MOD), 
                                     doubleFactorial[(r-k-1)/2], MOD);
                    top = intMul(top, doubleFactorial[(2*n+1-r-k)/2], MOD);

                    int bottom = intMul(intMul(factorial[r-k-1], factorial[2*n+1-r-k], MOD), 
                                        factorial[k], MOD);
                    bottom = intMul(bottom, doubleFactorial[n], MOD);

                    countMatrix[r][k] = intMul(top, modInv(bottom, MOD), MOD);
                }
            }
        }

        int result = 0;
        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = real_k; k <= n; k++) {
                result = (result + countMatrix[r][k]) % MOD;
            }
        }

        result = intMul(intMul(result, l, MOD), modInv(2*n+1, MOD), MOD);

        System.out.println(result);
    }

    static int intMul(int a, int b, int mod) {
        return (int) ((1L * a * b) % mod);
    }

    static int modInv(int a, int mod) {
        int originalMod = mod;
        int x = 0, lastX = 1;
        int y = 1, lastY = 0;

        while (mod != 0) {
            int q = a / mod;
            int temp = a % mod;
            a = mod;
            mod = temp;

            temp = x;
            x = lastX - q * x;
            lastX = temp;

            temp = y;
            y = lastY - q * y;
            lastY = temp;
        }

        if (lastX < 0) lastX += originalMod;
        return lastX;
    }

}

