public class Codeforces1153F {

    public static void main(String[] args) throws IOException {
        final int MOD = 998244353;

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int real_k = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken());

        int[] factorial = new int[2*n+2];
        factorial[0] = 1;
        for (int i = 1; i <= 2*n+1; i++) {
            factorial[i] = (int) (((long) factorial[i-1] * i) % MOD);
        }

        int[] oddDoubleFact = new int[n+1];
        oddDoubleFact[0] = 1;
        for (int i = 1; i <= n; i++) {
            oddDoubleFact[i] = (int) (((long) oddDoubleFact[i-1] * (2*i - 1)) % MOD);
        }

        int[][] coverage = new int[2*n+2][n+1];

        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = 1; k <= n; k++) {
                boolean parityMatch = (r % 2 != k % 2);
                boolean lowerBound = (r - 1 >= k);
                boolean upperBound = (2*n + 1 - r >= k);

                if (parityMatch && lowerBound && upperBound) {
                    long num = (long) factorial[r-1] * factorial[2*n+1-r];
                    num = (num * oddDoubleFact[(r-k-1)/2]) % MOD;
                    num = (num * oddDoubleFact[(2*n+1-r-k)/2]) % MOD;

                    long den = (long) factorial[r-k-1] * factorial[2*n+1-r-k];
                    den = (den * factorial[k]) % MOD;
                    den = (den * oddDoubleFact[n]) % MOD;

                    coverage[r][k] = (int) ((num * modInverse(den, MOD)) % MOD);
                }
            }
        }

        long total = 0;
        for (int r = 1; r <= 2*n+1; r++) {
            for (int k = real_k; k <= n; k++) {
                total += coverage[r][k];
                total %= MOD;
            }
        }

        total = (total * l) % MOD;
        total = (total * modInverse(2*n+1, MOD)) % MOD;

        System.out.println(total);
    }

    static long modInverse(long a, long mod) {
        long g = gcdExtended(a, mod, new long[2]);
        if (g != 1) return -1;
        long result = (a % mod + mod) % mod;
        return (result + mod) % mod;
    }

    static long gcdExtended(long a, long b, long[] xy) {
        if (a == 0) {
            xy[0] = 0;
            xy[1] = 1;
            return b;
        }
        long[] temp = new long[2];
        long gcd = gcdExtended(b % a, a, temp);
        xy[0] = temp[1] - (b / a) * temp[0];
        xy[1] = temp[0];
        return gcd;
    }

}

