public class Codeforces1153F {

    public static void main(String[] args) throws IOException {
        final int MOD = 998244353;

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int real_k = Integer.parseInt(input[1]);
        int l = Integer.parseInt(input[2]);

        int[] fact = new int[2 * n + 2];
        fact[0] = 1;
        for (int i = 1; i < fact.length; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        int[] dfact = new int[n + 1];
        dfact[0] = 1;
        for (int i = 1; i <= n; i++) {
            dfact[i] = (dfact[i - 1] * (2 * i - 1)) % MOD;
        }

        int[][] resultGrid = new int[2 * n + 2][n + 1];

        for (int r = 1; r < resultGrid.length; r++) {
            for (int k = 1; k <= n; k++) {
                int remR = r % 2;
                int remK = k % 2;
                boolean conditionsMet = (remR != remK) && (r - 1 >= k) && (2 * n + 1 - r >= k);

                if (conditionsMet) {
                    long upper = (long) fact[r - 1] * fact[2 * n + 1 - r];
                    upper = (upper * dfact[(r - k - 1) / 2]) % MOD;
                    upper = (upper * dfact[(2 * n + 1 - r - k) / 2]) % MOD;

                    long lower = (long) fact[r - k - 1] * fact[2 * n + 1 - r - k];
                    lower = (lower * fact[k]) % MOD;
                    lower = (lower * dfact[n]) % MOD;

                    resultGrid[r][k] = (int) ((upper * modInverse((int) lower, MOD)) % MOD);
                }
            }
        }

        long sum = 0;
        for (int r = 1; r < resultGrid.length; r++) {
            for (int k = real_k; k <= n; k++) {
                sum = (sum + resultGrid[r][k]) % MOD;
            }
        }

        sum = (sum * l) % MOD;
        sum = (sum * modInverse(2 * n + 1, MOD)) % MOD;

        System.out.println(sum);
    }

    static int modInverse(int a, int mod) {
        int originalMod = mod;
        int x0 = 1, x1 = 0;
        if (mod == 1) return 0;

        while (a > 1) {
            int q = a / mod;
            int t = mod;
            mod = a % mod;
            a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }

        if (x1 < 0) x1 += originalMod;
        return x1;
    }

}

