public class F_v2 {
    public static void main(String[] args) throws Exception {
        new F_v2().run();
    }

    void run() throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().trim().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int K = Integer.parseInt(parts[1]);
        int L = Integer.parseInt(parts[2]);

        int MOD = 998244353;
        int[][] fif = buildFactorialTables(10000, MOD);

        long[] contributions = new long[n + 1];

        for (int i = K; i <= n; i++) {
            long baseComb = comb(n, i, MOD, fif);
            for (int j = i; j <= n; j++) {
                long inner = comb(n - i, n - j, MOD, fif);
                long adjusted = (inner * baseComb) % MOD;
                if ((j - i) % 2 == 1) adjusted = (MOD - adjusted) % MOD;
                contributions[j] = (contributions[j] + adjusted) % MOD;
            }
        }

        long result = 0;
        for (int i = K; i <= n; i++) {
            long val = contributions[i];
            if (val == 0) continue;

            long t1 = fastPow(2, i, MOD);
            long t2 = fif[0][i];
            long t3 = fif[1][i];
            long t4 = fif[1][2 * i + 1];

            long term = t1 * t2 % MOD;
            term = term * t3 % MOD;
            term = term * t4 % MOD;
            term = term * val % MOD;

            result = (result + term) % MOD;
        }

        result = result * L % MOD;
        if (result < 0) result += MOD;
        System.out.println(result);
    }

    private static int[][] buildFactorialTables(int N, int MOD) {
        int[] fact = new int[N + 1];
        int[] invFact = new int[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % MOD);
        }
        invFact[N] = modInverse(fact[N], MOD);
        for (int i = N - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % MOD);
        }
        return new int[][] { fact, invFact };
    }

    private static int modInverse(int a, int MOD) {
        return fastPow(a, MOD - 2, MOD);
    }

    private static int fastPow(int base, int exp, int MOD) {
        int res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (int) ((long) res * base % MOD);
            base = (int) ((long) base * base % MOD);
            exp >>= 1;
        }
        return res;
    }

    private static long comb(int n, int k, int MOD, int[][] fif) {
        if (k < 0 || k > n) return 0;
        return (long) fif[0][n] * fif[1][k] % MOD * fif[1][n - k] % MOD;
    }
}

