        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int L = Integer.parseInt(st.nextToken());

        int[][] factorialTable = constructTables(10000, MOD);
        long[] coef = new long[n + 1];

        for (int i = K; i <= n; i++) {
            long C_n_i = comb(i, n, factorialTable);
            for (int j = i; j <= n; j++) {
                long C_nmi_nj = comb(n - j, n - i, factorialTable);
                long term = C_n_i * C_nmi_nj % MOD;
                if ((j - i & 1) == 1) term = MOD - term;
                coef[j] = (coef[j] + term) % MOD;
            }
        }

        long total = 0;
        for (int i = K; i <= n; i++) {
            long part = coef[i];
            if (part == 0) continue;

            long pow2i = modPow(2, i);
            long inv_i = factorialTable[1][i];
            long inv_2i1 = factorialTable[1][2 * i + 1];

            long cur = pow2i * inv_i % MOD;
            cur = cur * inv_i % MOD;
            cur = cur * inv_2i1 % MOD;
            cur = cur * part % MOD;
            total = (total + cur) % MOD;
        }

        total = total * L % MOD;
        if (total < 0) total += MOD;
        System.out.println(total);
    }

    int[][] constructTables(int max, int mod) {
        int[] fact = new int[max + 1];
        int[] invFact = new int[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }
        invFact[max] = modPow(fact[max], mod - 2);
        for (int i = max - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % mod);
        }
        return new int[][] { fact, invFact };
    }

    long comb(int r, int n, int[][] fif) {
        if (r < 0 || r > n) return 0;
        return (long) fif[0][n] * fif[1][r] % MOD * fif[1][n - r] % MOD;
    }

    int modPow(int base, int exp) {
        int res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (int) ((long) res * base % MOD);
            base = (int) ((long) base * base % MOD);
            exp >>= 1;
        }
        return res;
    }
}

