public class F_v4 {
    public static void main(String[] args) throws Exception {
        F_v4 solver = new F_v4();
        solver.execute();
    }

    private static final int MOD = 998244353;

    private void execute() throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int K = sc.nextInt();
        int L = sc.nextInt();

        int[][] tables = generateTables(10000);
        long[] weights = new long[n + 1];

        for (int i = K; i <= n; i++) {
            long c1 = choose(n, i);
            for (int j = i; j <= n; j++) {
                long c2 = choose(n - i, n - j);
                long contribution = c1 * c2 % MOD;
                if ((j - i) % 2 == 1) contribution = (MOD - contribution) % MOD;
                weights[j] = (weights[j] + contribution) % MOD;
            }
        }

        long total = 0;
        for (int i = K; i <= n; i++) {
            long w = weights[i];
            if (w == 0) continue;
            long factor = pow2(i) * invFact(i) % MOD;
            factor = factor * invFact(i) % MOD;
            factor = factor * invFact(2 * i + 1) % MOD;
            factor = factor * w % MOD;
            total = (total + factor) % MOD;
        }

        total = total * L % MOD;
        total = (total % MOD + MOD) % MOD;
        System.out.println(total);
    }

    private int[][] generateTables(int maxN) {
        int[] fact = new int[maxN + 1];
        int[] invFact = new int[maxN + 1];
        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % MOD);
        }
        invFact[maxN] = modPow(fact[maxN], MOD - 2);
        for (int i = maxN - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % MOD);
        }
        return new int[][] { fact, invFact };
    }

    private long choose(int n, int k) {
        if (k < 0 || k > n) return 0;
        int[][] tables = generateTables(10000);
        return (long) tables[0][n] * tables[1][k] % MOD * tables[1][n - k] % MOD;
    }

    private long pow2(int e) {
        return modPow(2, e);
    }

    private long invFact(int x) {
        int[][] tables = generateTables(10000);
        return tables[1][x];
    }

    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }

    static class Scanner {
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        String next() throws Exception {
            while (st == null || !st.hasMoreElements())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws Exception { return Integer.parseInt(next()); }
    }
}

