public class F_v5 {
    private static final int MOD = 998244353;

    public static void main(String[] args) throws Exception {
        new F_v5().start();
    }

    void start() throws Exception {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int K = fr.nextInt();
        int L = fr.nextInt();

        int[][] precomputed = computeFactorialArrays(10000);
        int[] factorials = precomputed[0];
        int[] invFactorials = precomputed[1];

        long[] contributionArr = new long[n + 1];

        for (int i = K; i <= n; i++) {
            long baseC = binomial(n, i, factorials, invFactorials);
            for (int j = i; j <= n; j++) {
                long inner = binomial(n - i, n - j, factorials, invFactorials);
                long product = (baseC * inner) % MOD;
                if (((j - i) & 1) == 1) product = (MOD - product) % MOD;
                contributionArr[j] = (contributionArr[j] + product) % MOD;
            }
        }

        long ans = 0;
        for (int i = K; i <= n; i++) {
            if (contributionArr[i] == 0) continue;

            long part1 = modExp(2, i, MOD);
            long part2 = factorials[i];
            long part3 = invFactorials[i];
            long part4 = invFactorials[2 * i + 1];

            long t = part1 * part3 % MOD;
            t = t * part3 % MOD;
            t = t * part4 % MOD;
            t = t * contributionArr[i] % MOD;

            ans = (ans + t) % MOD;
        }

        ans = ans * L % MOD;
        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }

    private int[][] computeFactorialArrays(int max) {
        int[] fact = new int[max + 1];
        int[] invFact = new int[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % MOD);
        }
        invFact[max] = modExp(fact[max], MOD - 2, MOD);
        for (int i = max - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % MOD);
        }
        return new int[][] { fact, invFact };
    }

    private long binomial(int n, int k, int[] fact, int[] invFact) {
        if (k < 0 || k > n) return 0;
        return (long) fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    private int modExp(long base, long exp, int mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return (int) res;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws Exception {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws Exception {
            return Integer.parseInt(next());
        }
    }
}

