public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String[] line = br.readLine().split("\\s+");
            int n = Integer.parseInt(line[0]);
            int k = Integer.parseInt(line[1]);
            int l = Integer.parseInt(line[2]);

            int mod = 998244353;
            long[] invs = precomputeInverses(2 * n + 3, mod);
            long[][] dp = new long[2 * n + 1][n + 1];
            dp[0][1] = 1;
            long result = 0;

            for (int step = 1; step < 2 * n; step++) {
                int prevMax = Math.min(2 * n - step, step);
                int currMax = Math.min(2 * n - step - 1, step + 1);

                for (int running = 0; running <= prevMax; running++) {
                    if (dp[step - 1][running] != 0) {
                        if (running > 0) {
                            long val = dp[step - 1][running] * running % mod;
                            val = val * invs[2 * n - step] % mod;
                            dp[step][running - 1] = (dp[step][running - 1] + val) % mod;
                        }
                        if (running < currMax) {
                            long val = dp[step - 1][running] * (2 * n - step - running) % mod;
                            val = val * invs[2 * n - step] % mod;
                            dp[step][running + 1] = (dp[step][running + 1] + val) % mod;
                        }
                        if (running >= k) {
                            result = (result + dp[step - 1][running]) % mod;
                        }
                    }
                }
            }

            if (k <= 1) {
                result = (result + dp[2 * n - 1][1]) % mod;
            }

            result = result * l % mod;
            result = result * invs[2 * n + 1] % mod;
            pw.println(result);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private long[] precomputeInverses(int size, int mod) {
        long[] inv = new long[size];
        inv[1] = 1;
        for (int i = 2; i < size; i++) {
            inv[i] = (mod - (mod / i) * inv[mod % i] % mod) % mod;
        }
        return inv;
    }
}

