        int k = Integer.parseInt(line[1]);
        int l = Integer.parseInt(line[2]);

        long[] fac = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % MOD;
        }

        long[][] dp = new long[2 * n + 1][2 * n + 2];
        dp[0][0] = 1;
        for (int i = 1; i <= 2 * n; i++) {
            for (int j = 0; j <= Math.min(i, n); j++) {
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
                }
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1) % MOD) % MOD;
            }
        }

        long ans = 0;
        for (int i = k; i <= 2 * n; i++) {
            for (int j = k; j <= n; j++) {
                ans = (ans + dp[i][j] * dp[2 * n - i][j] % MOD * fac[j] % MOD) % MOD;
            }
        }

        long invDenom = modPow(dp[2 * n][0] * (2 * n + 1) % MOD, MOD - 2);
