                factorial[i] = factorial[i - 1] * i % MOD;
            }

            long[][] table = new long[2 * n + 1][2 * n + 2];
            table[0][0] = 1;

            for (int row = 1; row <= 2 * n; ++row) {
                for (int col = 0; col <= Math.min(row, n); ++col) {
                    if (col > 0) table[row][col] = (table[row][col] + table[row - 1][col - 1]) % MOD;
                    table[row][col] = (table[row][col] + table[row - 1][col + 1] * (col + 1)) % MOD;
                }
            }

            long combinationSum = 0;
            for (int p = k; p <= 2 * n; ++p) {
                for (int q = k; q <= n; ++q) {
                    combinationSum = (combinationSum + table[p][q] * table[2 * n - p][q] % MOD * factorial[q]) % MOD;
                }
