            int sgn = 1;
            for (int s = 0; s <= n - i; s++) {
                long t = binom[s][n - i];
                t = t * twoPow[s] % MOD;
                t = t * factorial[s + i] % MOD;
                t = t * factorial[s + i] % MOD;
                t = t * invFact[2 * (s + i) + 1] % MOD;
                inner = (inner + sgn * t) % MOD;
                sgn = -sgn;
            }
            long part = inner * twoPow[i] % MOD;
            part = part * binom[i][n] % MOD;
            ans = (ans + part) % MOD;
        }
        ans = ans * L % MOD;
        if (ans < 0) ans += MOD;
        out.println(ans);
        out.close();
    }

    static void setup() {
        int N = 2000;
        binom = new long[N + 2][N + 2];
        for (int i = 0; i <= N + 1; i++) {
            binom[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % MOD;
            }
        }
        factorial = new long[4002];
        factorial[0] = 1;
        for (int i = 1; i < factorial.length; i++) {
            factorial[i] = factorial[i - 1] * i % MOD;
        }
        twoPow = new long[N + 2];
        twoPow[0] = 1;
        for (int i = 1; i < twoPow.length; i++) {
            twoPow[i] = (twoPow[i - 1] * 2) % MOD;
        }
        invFact = new long[4002];
        invFact[1] = 1;
        for (int i = 3; i < invFact.length; i += 2) {
            invFact[i] = modPow(factorial[i], MOD - 2, MOD);
        }
    }

    static long modPow(long b, long e, long m) {
        long res = 1;
        b %= m;
        while (e > 0) {
            if ((e & 1) == 1) res = res * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return res;
    }
}

