        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String[] line = br.readLine().split(" ");
            long N = Long.parseLong(line[0]);
            long M = Long.parseLong(line[1]);
            int K = Integer.parseInt(line[2]);

            long MOD = 998244353L;
            long modInverseM = modInverse(M, MOD);

            long[] expect = new long[K + 1];
            long[] poly = new long[K + 1];

            expect[0] = 1;
            poly[0] = 1;
            long curExpect = 1;

            for (int k = 1; k <= K; k++) {
                curExpect = (curExpect * ((N - (k - 1)) % MOD)) % MOD;
                curExpect = (curExpect * modInverseM) % MOD;

                for (int i = k; i >= 0; i--) {
                    long prev = (i > 0) ? poly[i - 1] : 0;
                    long term = ((-(k - 1)) * poly[i]) % MOD;
                    poly[i] = (prev + term) % MOD;
                    if (poly[i] < 0) poly[i] += MOD;
                }

                expect[k] = curExpect;
                for (int i = k - 1; i >= 0; i--) {
                    long subtract = (poly[i] * expect[i]) % MOD;
                    expect[k] = (expect[k] - subtract) % MOD;
                    if (expect[k] < 0) expect[k] += MOD;
                }
            }

            pw.println(expect[K]);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private long modInverse(long a, long mod) {
        long[] result = extendedGCD(a, mod);
        if (result[0] != 1) return 0;
        return ((result[1] % mod) + mod) % mod;
    }

    private long[] extendedGCD(long a, long b) {
        if (a == 0) {
            return new long[]{b, 0, 1};
        }
        long[] next = extendedGCD(b % a, a);
        long tempX = next[1];
        next[1] = next[2] - (b / a) * next[1];
        next[2] = tempX;
        return next;
    }
}

