            for (int j = step; j >= 0; j--) {
                long val = 0;
                if (j > 0) val = coeffs[j - 1];
                val = (val + ((- (step - 1)) * coeffs[j]) % MOD) % MOD;
                if (val < 0) val += MOD;
                coeffs[j] = val;
            }

            dp[step] = current;
            for (int j = step - 1; j >= 0; j--) {
                dp[step] = (dp[step] - (coeffs[j] * dp[j]) % MOD) % MOD;
