        long val = 1;
        long ans = 0;
        long prob = 1;
        for(int i = k; i > 0; i--){
            val*=(n-(k-i));
            val%=MOD;
            prob*=p;
            prob%=MOD;
            ans += (((val*prob)%MOD)*stirling[k][k-i+1])%MOD;
            ans%=MOD;
        }
        System.out.println(ans);


    }

