        int totalBeauty = 0;
        for (int i = 0; i < n; i++) {
            beauty[i] = Integer.parseInt(tokens[i]);
            totalBeauty += beauty[i];
        }

        int[] charCount = new int[26];
        int conflictCount = 0;
        for (int i = 0; i < n / 2; i++) {
            if (s[i] == s[n - i - 1]) {
                conflictCount++;
                charCount[s[i] - 'a']++;
                totalBeauty -= Math.min(beauty[i], beauty[n - i - 1]);
            }
        }

        int maxFreq = 0, mostFrequentChar = 0;
        for (int i = 0; i < 26; i++) {
            if (charCount[i] > maxFreq) {
                maxFreq = charCount[i];
                mostFrequentChar = i;
            }
