        int n = Integer.parseInt(br.readLine());
        char[] s = br.readLine().trim().toCharArray();
        String[] tokens = br.readLine().trim().split("\\s+");
        int[] beauty = new int[n];

        int sum = 0;
        for (int i = 0; i < n; i++) {
            beauty[i] = Integer.parseInt(tokens[i]);
            sum += beauty[i];
        }

        int[] cnt = new int[26];
        int conflicts = 0;
        for (int i = 0; i < n >> 1; i++) {
            if (s[i] == s[n - i - 1]) {
                conflicts++;
                cnt[s[i] - 'a']++;
                sum -= Math.min(beauty[i], beauty[n - i - 1]);
            }
        }

        int maxCount = 0, bestChar = 0;
        for (int i = 0; i < 26; i++) {
            if (cnt[i] > maxCount) {
                maxCount = cnt[i];
                bestChar = i;
            }
        }

        if (maxCount << 1 <= conflicts) {
            System.out.println(sum);
            return;
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 0; i < n >> 1; i++) {
            if ((s[i] - 'a' != bestChar) && (s[n - i - 1] - 'a' != bestChar) && (s[i] != s[n - i - 1])) {
                pq.offer(Math.min(beauty[i], beauty[n - i - 1]));
            }
        }

        int need = (maxCount << 1) - conflicts;
        while (need-- > 0 && !pq.isEmpty()) {
            sum -= pq.poll();
        }
        System.out.print(sum);
    }
}

