            link_(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ai = cc[i] - 'a';
            int aj = cc[j] - 'a';
            for (int a = 0; a < A; a++) {
                int b;
                if (a == ai && a == aj)
                    b = Math.max(bb[i], bb[j]);
                else if (a == ai)
                    b = bb[i];
                else if (a == aj)
                    b = bb[j];
                else
                    b = 0;
                link_(1 + i, 1 + n + a, 1, -b);
            }
        }
        int[] kk = new int[A];
        for (int i = 0; i < n * 2; i++) {
            int a = cc[i] - 'a';
            kk[a]++;
        }
        for (int a = 0; a < A; a++)
            link_(1 + n + a, n_ - 1, kk[a], 0);
        println(-edmonds_karp(0, n_ - 1));
    }
}

