public class CF884F extends PrintWriter {
    public static void main(String[] args) {
        new CF884F().execute();
    }

    CF884F() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);

    static final int ALPHABET_SIZE = 26;
    static final int INF = 0x3f3f3f3f;

    int[] head, to, next, cap, cost, rev;
    int edgeIndex;

    void setup(int nodes) {
        head = new int[nodes];
        Arrays.fill(head, -1);
        to = new int[10000];
        next = new int[10000];
        cap = new int[10000];
        cost = new int[10000];
        rev = new int[10000];
        edgeIndex = 0;
    }

    void connect(int u, int v, int c, int co) {
        to[edgeIndex] = v;
        cap[edgeIndex] = c;
        cost[edgeIndex] = co;
        next[edgeIndex] = head[u];
        rev[edgeIndex] = edgeIndex ^ 1;
        head[u] = edgeIndex++;

        to[edgeIndex] = u;
        cap[edgeIndex] = 0;
        cost[edgeIndex] = -co;
        next[edgeIndex] = head[v];
        rev[edgeIndex] = edgeIndex ^ 1;
        head[v] = edgeIndex++;
    }

    int minCostFlow(int src, int dst) {
        int nodes = head.length;
        int[] dist = new int[nodes];
        int[] prevv = new int[nodes];
        int[] preve = new int[nodes];
        int totalFlow = 0;
        int totalCost = 0;

        while (true) {
            Arrays.fill(dist, INF);
            dist[src] = 0;
            boolean[] visited = new boolean[nodes];
            PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
            pq.offer(new int[]{0, src});

            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int d = cur[0], u = cur[1];
                if (visited[u]) continue;
                visited[u] = true;

                for (int e = head[u]; e != -1; e = next[e]) {
                    if (cap[e] > 0 && dist[u] + cost[e] < dist[to[e]]) {
                        dist[to[e]] = dist[u] + cost[e];
                        prevv[to[e]] = u;
                        preve[to[e]] = e;
                        pq.offer(new int[]{dist[to[e]], to[e]});
                    }
                }
            }

            if (dist[dst] == INF) break;

            int f = INF;
            for (int v = dst; v != src; v = prevv[v]) {
                f = Math.min(f, cap[preve[v]]);
            }

            for (int v = dst; v != src; v = prevv[v]) {
                int e = preve[v];
                cap[e] -= f;
                cap[e ^ 1] += f;
                totalCost += f * cost[e];
            }
            totalFlow += f;
        }

        return totalCost;
    }

    void execute() {
        int n = sc.nextInt() / 2;
        int totalNodes = 1 + n + ALPHABET_SIZE + 1;
        setup(totalNodes);

        byte[] chars = sc.next().getBytes();
        int[] values = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            values[i] = sc.nextInt();
        }

        for (int i = 0; i < n; i++) {
            connect(0, 1 + i, 2, 0);
        }

        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ci = chars[i] - 'a';
            int cj = chars[j] - 'a';

            for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
                int val;
                if (letter == ci && letter == cj) {
                    val = Math.max(values[i], values[j]);
                } else if (letter == ci) {
                    val = values[i];
                } else if (letter == cj) {
                    val = values[j];
                } else {
                    val = 0;
                }
                connect(1 + i, 1 + n + letter, 1, -val);
            }
        }

        int[] letterCounts = new int[ALPHABET_SIZE];
        for (int i = 0; i < n * 2; i++) {
            int ch = chars[i] - 'a';
            letterCounts[ch]++;
        }

        for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
            connect(1 + n + letter, totalNodes - 1, letterCounts[letter], 0);
        }

        println(-minCostFlow(0, totalNodes - 1));
    }
}

