    CF884F() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);

    static final int ALPHABET_SIZE = 26;
    static final int INF = 0x3f3f3f3f;

    void work() {
        int n = sc.nextInt() / 2;
        int N = 1 + n + ALPHABET_SIZE + 1;

        int[][] capacity = new int[N][N];
        int[][] cost = new int[N][N];

        byte[] chars = sc.next().getBytes();
        int[] values = new int[n * 2];
        for (int i = 0; i < n * 2; i++) {
            values[i] = sc.nextInt();
        }

        // Source to positions
        for (int i = 0; i < n; i++) {
            capacity[0][1 + i] = 2;
        }

        // Positions to letters
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ci = chars[i] - 'a';
            int cj = chars[j] - 'a';

            for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
                int val;
                if (letter == ci && letter == cj) {
                    val = Math.max(values[i], values[j]);
                } else if (letter == ci) {
                    val = values[i];
                } else if (letter == cj) {
                    val = values[j];
                } else {
                    val = 0;
                }
                capacity[1 + i][1 + n + letter] = 1;
                cost[1 + i][1 + n + letter] = -val;
                cost[1 + n + letter][1 + i] = val;
            }
        }

        int[] letterCounts = new int[ALPHABET_SIZE];
        for (int i = 0; i < n * 2; i++) {
            int ch = chars[i] - 'a';
            letterCounts[ch]++;
        }

        for (int letter = 0; letter < ALPHABET_SIZE; letter++) {
            capacity[1 + n + letter][N - 1] = letterCounts[letter];
        }

        int result = minCostFlow(N, capacity, cost, 0, N - 1);
        println(-result);
    }

    int minCostFlow(int N, int[][] cap, int[][] cost, int src, int dst) {
        int[] potential = new int[N];
        Arrays.fill(potential, INF);
        potential[src] = 0;

        for (int iter = 0; iter < N; iter++) {
            boolean updated = false;
            for (int u = 0; u < N; u++) {
                if (potential[u] == INF) continue;
                for (int v = 0; v < N; v++) {
                    if (cap[u][v] > 0 && potential[u] + cost[u][v] < potential[v]) {
                        potential[v] = potential[u] + cost[u][v];
                        updated = true;
                    }
                }
            }
            if (!updated) break;
        }

        int totalCost = 0;

        while (true) {
            int[] dist = new int[N];
            int[] prev = new int[N];
            int[] prevedge = new int[N];
            Arrays.fill(dist, INF);
            dist[src] = 0;

            for (int iter = 0; iter < N; iter++) {
                boolean updated = false;
                for (int u = 0; u < N; u++) {
                    if (dist[u] == INF) continue;
                    for (int v = 0; v < N; v++) {
                        if (cap[u][v] > 0 && dist[u] + cost[u][v] + potential[u] - potential[v] < dist[v]) {
                            dist[v] = dist[u] + cost[u][v] + potential[u] - potential[v];
                            prev[v] = u;
                            prevedge[v] = v;
                            updated = true;
                        }
                    }
                }
                if (!updated) break;
            }

            if (dist[dst] == INF) break;

            for (int i = 0; i < N; i++) {
                if (dist[i] < INF) potential[i] += dist[i];
            }

            int flow = INF;
            for (int v = dst; v != src; v = prev[v]) {
                flow = Math.min(flow, cap[prev[v]][v]);
            }

            for (int v = dst; v != src; v = prev[v]) {
                int u = prev[v];
                cap[u][v] -= flow;
                cap[v][u] += flow;
                totalCost += flow * cost[u][v];
            }
        }

        return totalCost;
    }
}

