        int[] next = new int[n];
        Arrays.fill(next, -1);

        while (t % n != 0) {
            long rem = t % n;
            s = (s + (s < m ? rem : n - rem)) % n;
            t--;
        }

        long stepsLeft = t / n;
        int prev = s;
        while (stepsLeft > 0 && next[s] == -1) {
            int start = s;
            for (int i = n - 1; i > 0; i--) {
                s = (s + (s < m ? i : n - i)) % n;
            }
            next[start] = s;
            prev = s;
            stepsLeft--;
        }

        if (stepsLeft > 0) {
            long cycleLen = 1;
            int cur = s;
            while (next[cur] != s) {
                cycleLen++;
                cur = next[cur];
            }
            long finalSteps = stepsLeft % cycleLen;
            for (long i = 0; i < finalSteps; i++) {
                s = next[s];
            }
        }

        out.println(s + 1);
        out.flush();
    }

