public class Solution {
    static MyScanner sc;
    private static PrintWriter out;
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        StringBuilder sb = new StringBuilder();

        if (sb.length() == 0) {
            sc = new MyScanner(System.in);
        } else {
            sc = new MyScanner(new BufferedReader(new StringReader(sb.toString())));
        }

        out = new PrintWriter(new OutputStreamWriter(System.out));
        setupData();
        processInput();
        out.flush();
    }

    private static void setupData() {}

    private static void processInput() throws IOException {
        int a = sc.nextInt();
        int b = sc.nextInt();
        int left = sc.nextInt() - 1;
        int right = sc.nextInt() - 1;
        int segmentLength = right - left + 1;

        int minDistinct = segmentLength;
        for (char c1 = 'a'; c1 <= 'z'; c1++) {
            for (char c2 = 'a'; c2 <= 'z'; c2++) {
                for (char c3 = 'a'; c3 <= 'z'; c3++) {
                    char[] pattern = {c1, c2, c3};
                    minDistinct = Math.min(minDistinct, countDistinctInSegment(a, b, left, right, pattern));
                }
            }
        }
        out.println(minDistinct);
    }

    private static int countDistinctInSegment(int a, int b, int l, int r, char[] pattern) {
        int period = a + b;
        char[] fullPattern = new char[3 * period];

        for (int i = 0; i < 3; i++) {
            char[] prefix = generatePrefixPattern(fullPattern, i * period, a);
            System.arraycopy(prefix, 0, fullPattern, i * period, a);
            Arrays.fill(fullPattern, i * period + a, (i + 1) * period, pattern[i]);
        }

        int startOffset = l % period;
        int length = r - l + 1;
        char[] window = new char[length];
        System.arraycopy(fullPattern, startOffset, window, 0, Math.min(length, fullPattern.length - startOffset));

        boolean[] seen = new boolean[26];
        for (char ch : window) {
            seen[ch - 'a'] = true;
        }

        int count = 0;
        for (boolean s : seen) {
            if (s) count++;
        }
        return count;
    }

    private static char[] generatePrefixPattern(char[] buffer, int startIndex, int length) {
        boolean[] used = new boolean[26];
        for (int i = startIndex - 1; i >= startIndex - length && i >= 0; i--) {
            used[buffer[i] - 'a'] = true;
        }

        char[] result = new char[length];
        char current = 'a';
        int idx = 0;
        while (idx < length) {
            while (used[current - 'a']) {
                current++;
            }
            result[idx++] = current++;
        }
        return result;
    }

    static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner(BufferedReader br) {
            this.br = br;
        }

        public MyScanner(InputStream in) {
            this(new BufferedReader(new InputStreamReader(in)));
        }

        private void ensureToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        }

        String next() {
            ensureToken();
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

