    static int evaluateSegment(int a, int b, int L, int R, char[] pattern) {
        int period = a + b;
        char[] full = new char[3 * period];

        for (int i = 0; i < 3; i++) {
            System.arraycopy(buildPrefix(a, full, i * period), 0, full, i * period, a);
            Arrays.fill(full, i * period + a, (i + 1) * period, pattern[i]);
        }

        int start = L % period;
        int len = R - L + 1;
        char[] window = new char[len];
        System.arraycopy(full, start, window, 0, Math.min(len, full.length - start));

        boolean[] seen = new boolean[26];
        for (char c : window) {
            seen[c - 'a'] = true;
        }

        int count = 0;
        for (boolean b : seen) if (b) count++;
        return count;
    }

    static char[] buildPrefix(int len, char[] buffer, int idx) {
        boolean[] used = new boolean[26];
        for (int i = idx - 1; i >= idx - len && i >= 0; i--) {
            used[buffer[i] - 'a'] = true;
