public class Solution {
    private static BufferedReader br;
    private static StringTokenizer st;
    private static PrintWriter pw;

    public static void main(String[] args) throws Exception {
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(System.out);
        solve();
        pw.close();
    }

    private static void solve() throws IOException {
        int a = parseInt(), b = parseInt();
        int left = parseInt() - 1, right = parseInt() - 1;
        int len = right - left + 1;
        int best = len;

        for (char c1 = 'a'; c1 <= 'z'; c1++) {
            for (char c2 = 'a'; c2 <= 'z'; c2++) {
                for (char c3 = 'a'; c3 <= 'z'; c3++) {
                    best = Math.min(best, distinctInSegment(a, b, left, right, new char[]{c1, c2, c3}));
                }
            }
        }

        pw.println(best);
    }

    private static int distinctInSegment(int a, int b, int l, int r, char[] p) {
        int period = a + b;
        char[] full = new char[3 * period];
        for (int i = 0; i < 3; i++) {
            char[] prefix = prefixPattern(full, i * period, a);
            System.arraycopy(prefix, 0, full, i * period, a);
            Arrays.fill(full, i * period + a, (i + 1) * period, p[i]);
        }

        int start = l % period;
        int n = r - l + 1;
        char[] window = new char[n];
        System.arraycopy(full, start, window, 0, Math.min(n, full.length - start));

        int[] freq = new int[26];
        for (char c : window) freq[c - 'a']++;
        int d = 0;
        for (int f : freq) if (f > 0) d++;
        return d;
    }

    private static char[] prefixPattern(char[] buffer, int offset, int len) {
        boolean[] used = new boolean[26];
        for (int i = offset - 1; i >= offset - len && i >= 0; i--)
            used[buffer[i] - 'a'] = true;

        char[] res = new char[len];
        char cur = 'a';
        for (int i = 0; i < len; i++) {
            while (used[cur - 'a']) cur++;
            res[i] = cur++;
        }
        return res;
    }

    private static int parseInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static String next() throws IOException {
        while (st == null || !st.hasMoreTokens())
            st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    private static class StringTokenizer {
        private String[] tokens;
        private int index;

        public StringTokenizer(String s) {
            tokens = s.split("\\s+");
            index = 0;
        }

        public boolean hasMoreTokens() {
            return index < tokens.length;
        }

        public String nextToken() {
            return tokens[index++];
        }
    }
}

