        private InputStream stream;
        private byte[] buf = new byte[1 << 16];
        private int curChar, numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1)
                throw new RuntimeException("read error");
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpace(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new RuntimeException("input error");
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            return res * sgn;
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    private static int count(int[] cc, int l, int r) {
        boolean[] used = new boolean[24];
        int cnt = 0;
        for (int i = l; i <= r; i++) {
            int c = cc[i];
            if (!used[c]) {
                used[c] = true;
                cnt++;
            }
        }
        return cnt;
    }
}

