public class CF819A {
    static int count(int[] arr, int left, int right) {
        boolean[] seen = new boolean[24];
        int uniqueCount = 0;
        for (int idx = left; idx <= right; idx++) {
            int val = arr[idx];
            if (!seen[val]) {
                seen[val] = true;
                uniqueCount++;
            }
        }
        return uniqueCount;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokens = new StringTokenizer(reader.readLine());
        int a = Integer.parseInt(tokens.nextToken());
        int b = Integer.parseInt(tokens.nextToken());
        int l = Integer.parseInt(tokens.nextToken()) - 1;
        int r = Integer.parseInt(tokens.nextToken()) - 1;
        int total = a + b;
        int cycles = 4;
        int[] pattern = new int[total * cycles];
        int offset = l / total;
        l -= offset * total;
        r -= offset * total;
        offset = (r - l + 1) / total;
        if (offset > 2)
            r -= (offset - 2) * total;
        int diff = (a > b) ? (a - b) : 1;

        for (int cycle = 0; cycle < cycles; cycle++) {
            for (int i = 0; i < a - diff; i++)
                pattern[total * cycle + i] = i;
            for (int i = 0; i < diff; i++)
                pattern[total * cycle + a - diff + i] = (cycle % 2 == 0) ? (a - diff + i) : (a + i);
        }

        int best = a + a;
        for (int i0 = 1; i0 <= diff; i0++) {
            for (int j = 0; j < b; j++)
                pattern[total * 0 + a + j] = pattern[total * 0 + a - i0];
            for (int i1 = 1; i1 <= diff; i1++) {
                for (int j = 0; j < b; j++)
                    pattern[total * 1 + a + j] = pattern[total * 1 + a - i1];
                for (int i2 = 1; i2 <= diff; i2++) {
                    for (int j = 0; j < b; j++)
                        pattern[total * 2 + a + j] = pattern[total * 2 + a - i2];
                    for (int i3 = 1; i3 <= diff; i3++) {
                        for (int j = 0; j < b; j++)
                            pattern[total * 3 + a + j] = pattern[total * 3 + a - i3];
                        best = Math.min(best, count(pattern, l, r));
                    }
                }
            }
        }
        System.out.println(best);
    }
}

