        int l = Integer.parseInt(parts[2]) - 1;
        int r = Integer.parseInt(parts[3]) - 1;
        int ab = a + b;
        int M = 4;
        int[] arr = new int[ab * M];
        int block = l / ab;
        l -= block * ab;
        r -= block * ab;
        block = (r - l + 1) / ab;
        if (block > 2)
            r -= (block - 2) * ab;
        int delta = (a > b) ? (a - b) : 1;

        for (block = 0; block < M; block++) {
            for (int i = 0; i < a - delta; i++)
                arr[ab * block + i] = i;
            for (int i = 0; i < delta; i++)
                arr[ab * block + a - delta + i] = (block % 2 == 0) ? (a - delta + i) : (a + i);
        }

        int result = a + a;
        for (int p0 = 1; p0 <= delta; p0++) {
            for (int j = 0; j < b; j++)
                arr[ab * 0 + a + j] = arr[ab * 0 + a - p0];
            for (int p1 = 1; p1 <= delta; p1++) {
                for (int j = 0; j < b; j++)
                    arr[ab * 1 + a + j] = arr[ab * 1 + a - p1];
                for (int p2 = 1; p2 <= delta; p2++) {
                    for (int j = 0; j < b; j++)
                        arr[ab * 2 + a + j] = arr[ab * 2 + a - p2];
                    for (int p3 = 1; p3 <= delta; p3++) {
                        for (int j = 0; j < b; j++)
                            arr[ab * 3 + a + j] = arr[ab * 3 + a - p3];
                        result = Math.min(result, countDistinct(arr, l, r));
                    }
                }
            }
        }
        System.out.println(result);
    }
}

