public class CF819A {
    static int countDistinctColors(int[] seq, int startIdx, int endIdx) {
        boolean[] visited = new boolean[24];
        int distinctCount = 0;
        for (int i = startIdx; i <= endIdx; i++) {
            int color = seq[i];
            if (!visited[color]) {
                visited[color] = true;
                distinctCount++;
            }
        }
        return distinctCount;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader stdin = new BufferedReader(new InputStreamReader(System.in));
        String[] input = stdin.readLine().trim().split("\\s+");
        int a = Integer.parseInt(input[0]);
        int b = Integer.parseInt(input[1]);
        int l = Integer.parseInt(input[2]) - 1;
        int r = Integer.parseInt(input[3]) - 1;
        int ab = a + b;
        int numBlocks = 4;
        int[] pattern = new int[ab * numBlocks];
        int blockOffset = l / ab;
        l -= blockOffset * ab;
        r -= blockOffset * ab;
        blockOffset = (r - l + 1) / ab;
        if (blockOffset > 2)
            r -= (blockOffset - 2) * ab;
        int diff = (a > b) ? (a - b) : 1;

        for (int block = 0; block < numBlocks; block++) {
            for (int i = 0; i < a - diff; i++)
                pattern[ab * block + i] = i;
            for (int i = 0; i < diff; i++)
                pattern[ab * block + a - diff + i] = (block % 2 == 0) ? (a - diff + i) : (a + i);
        }

        int minDistinct = a + a;
        outer:
        for (int idx0 = 1; idx0 <= diff; idx0++) {
            for (int j = 0; j < b; j++)
                pattern[ab * 0 + a + j] = pattern[ab * 0 + a - idx0];
            for (int idx1 = 1; idx1 <= diff; idx1++) {
                for (int j = 0; j < b; j++)
                    pattern[ab * 1 + a + j] = pattern[ab * 1 + a - idx1];
                for (int idx2 = 1; idx2 <= diff; idx2++) {
                    for (int j = 0; j < b; j++)
                        pattern[ab * 2 + a + j] = pattern[ab * 2 + a - idx2];
                    for (int idx3 = 1; idx3 <= diff; idx3++) {
                        for (int j = 0; j < b; j++)
                            pattern[ab * 3 + a + j] = pattern[ab * 3 + a - idx3];
                        minDistinct = Math.min(minDistinct, countDistinctColors(pattern, l, r));
                    }
                }
            }
        }
        System.out.println(minDistinct);
    }
}

