        int a = in.nextInt();
        int b = in.nextInt();
        int l = in.nextInt();
        int r = in.nextInt();
        System.out.println(computeResult(a, b, l, r));
    }

    static int computeResult(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b)) {
            return a <= b ? a + 1 : (2 * a - b);
        }

        int[] pattern = new int[3 * (a + b) + 1];
        int currentVal = 0;

        // First segment: 1 to a
        for (int i = 1; i <= a; i++) {
            pattern[i] = i;
            currentVal = i;
        }

        // Second segment: a+1 to a+b
        for (int i = a + 1; i <= a + b; i++) {
            pattern[i] = currentVal;
        }

        // Third segment: a+b+1 to a+b+a
        for (int i = a + b + 1; i <= a + b + a; i++) {
            int candidate = 1;
            while (containsValue(pattern, candidate, a + 1, i - 1)) {
                candidate++;
            }
            pattern[i] = candidate;
            currentVal = candidate;
        }

        // Fourth segment: a+b+a+1 to a+b+a+b
        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            pattern[i] = currentVal;
        }

        // Fifth segment: 2*(a+b)+1 to 3*(a+b)
        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            pattern[i] = pattern[i - (a + b)];
        }

        // Count distinct values in range [l, r]
        boolean[] seen = new boolean[25];
        int start = l % (a + b);
        if (start == 0) start += (a + b);
        int end = r - l + start;
        if (end < start) end += (a + b);

        for (int i = start; i <= end; i++) {
            seen[pattern[i]] = true;
        }

        int count = 0;
        for (int i = 1; i <= 24; i++) {
            if (seen[i]) count++;
        }
        return count;
    }

    static boolean containsValue(int[] arr, int val, int left, int right) {
        for (int i = left; i <= right; i++) {
            if (arr[i] == val) return true;
        }
        return false;
    }
}

import java.util.Scanner;

public class C {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int l = scanner.nextInt();
        int r = scanner.nextInt();
        System.out.println(solve(a, b, l, r));
    }

    static int solve(int a, int b, int l, int r) {
        int range = r - l + 1;
        if (range > 2 * (a + b)) {
            return a <= b ? a + 1 : 2 * a - b;
        }

        int[] seq = new int[3 * (a + b) + 1];
        int last = 0;

        // Build first part: 1..a
        for (int i = 1; i <= a; i++) {
            seq[i] = i;
            last = i;
        }

        // Extend to a+b with last value
        for (int i = a + 1; i <= a + b; i++) {
            seq[i] = last;
        }

        // Build next a elements
        for (int i = a + b + 1; i <= a + b + a; i++) {
            int val = 1;
            while (has(seq, val, a + 1, i - 1)) {
                val++;
            }
            seq[i] = val;
            last = val;
        }

        // Extend next b elements with last value
        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            seq[i] = last;
        }

        // Repeat pattern
        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            seq[i] = seq[i - (a + b)];
        }

        // Count unique values in [l, r]
        boolean[] present = new boolean[25];
        int startIdx = l % (a + b);
        if (startIdx == 0) startIdx = a + b;
        int endIdx = r - l + startIdx;
        if (endIdx < startIdx) endIdx += a + b;

        for (int i = startIdx; i <= endIdx; i++) {
            present[seq[i]] = true;
        }

        int uniqueCount = 0;
        for (int i = 1; i <= 24; i++) {
            if (present[i]) uniqueCount++;
        }
        return uniqueCount;
    }

    static boolean has(int[] arr, int value, int lo, int hi) {
        for (int idx = lo; idx <= hi; idx++) {
            if (arr[idx] == value) return true;
        }
        return false;
    }
}

