                candidate++;
            }
            base[idx] = candidate;
            prev = candidate;
        }

        // Fourth segment: a+b+a+1 to a+b+a+b
        for (int idx = a + b + a + 1; idx <= a + b + a + b; idx++) {
            base[idx] = prev;
        }

        // Fifth segment: repeat pattern
        for (int idx = 2 * (a + b) + 1; idx <= 3 * (a + b); idx++) {
            base[idx] = base[idx - (a + b)];
        }

        // Count distinct values in range
        boolean[] seen = new boolean[25];
