    static int calculate(int a, int b, int l, int r) {
        int windowSize = r - l + 1;
        if (windowSize > 2 * (a + b)) {
            return a <= b ? a + 1 : 2 * a - b;
        }

        int[] sequence = new int[3 * (a + b) + 1];
