        // Build first part: 1 to a
        for (int i = 1; i <= a; i++) {
            sequence[i] = i;
            lastAssigned = i;
        }

        // Fill next b positions with last value
        for (int i = a + 1; i <= a + b; i++) {
            sequence[i] = lastAssigned;
        }

        // Build next a positions
        for (int i = a + b + 1; i <= a + b + a; i++) {
            int candidate = 1;
            while (valueExists(sequence, candidate, a + 1, i - 1)) {
                candidate++;
            }
            sequence[i] = candidate;
            lastAssigned = candidate;
        }

        // Fill next b positions with last value
        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            sequence[i] = lastAssigned;
        }

        // Extend pattern
        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            sequence[i] = sequence[i - (a + b)];
        }

        // Count distinct values in range
        boolean[] found = new boolean[25];
        int start = l % (a + b);
        if (start == 0) start = a + b;
        int end = r - l + start;
        if (end < start) end += a + b;

        for (int i = start; i <= end; i++) {
            found[sequence[i]] = true;
        }

        int distinct = 0;
        for (int i = 1; i <= 24; i++) {
            if (found[i]) distinct++;
        }
        return distinct;
    }

    static boolean valueExists(int[] arr, int val, int startIdx, int endIdx) {
        for (int i = startIdx; i <= endIdx; i++) {
            if (arr[i] == val) return true;
        }
        return false;
    }
}

