        }
    }

    private int computeResult(int a, int b, int l, int r) {
        int total = a + b;
        if ((r - l + 1) > 2 * total) {
            return a <= b ? a + 1 : (2 * a - b);
        }

        int[] pattern = new int[3 * total + 1];
        int temp = 0;

        for (int i = 1; i <= a; i++) {
            pattern[i] = i;
            temp = i;
        }

        for (int i = a + 1; i <= a + b; i++) {
            pattern[i] = temp;
        }

        for (int i = a + b + 1; i <= a + b + a; i++) {
            int tc = 1;
            while (containsValue(pattern, tc, a + b - a + 1, i - 1)) {
                tc++;
            }
            pattern[i] = tc;
            temp = tc;
        }

        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            pattern[i] = temp;
        }

        for (int i = 2 * total + 1; i <= 3 * total; i++) {
            pattern[i] = pattern[i - total];
        }

        boolean[] seen = new boolean[25];
        int templ = l % total;
        if (templ == 0) templ += total;
        int tempr = r - l + templ;
        if (tempr < templ) tempr += total;

        for (int i = templ; i <= tempr; i++) {
            if (i < pattern.length) {
                seen[pattern[i]] = true;
            }
        }

        int res = 0;
        for (int i = 1; i <= 24; i++) {
            if (seen[i]) res++;
        }
        return res;
    }

    private boolean containsValue(int[] arr, int val, int left, int right) {
        for (int i = left; i <= right; i++) {
            if (i < arr.length && arr[i] == val) {
                return true;
            }
        }
        return false;
    }
}

