public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int l = sc.nextInt();
        int r = sc.nextInt();
        pw.println(solve(a, b, l, r));
        pw.close();
    }

    private static int solve(int a, int b, int l, int r) {
        int n = a + b;
        if (r - l + 1 > 2 * n) {
            return a <= b ? a + 1 : 2 * a - b;
        }

        int[] seq = new int[3 * n + 1];
        int cur = 0;

        for (int i = 1; i <= a; i++) {
            seq[i] = i;
            cur = i;
        }

        for (int i = a + 1; i <= n; i++) {
            seq[i] = cur;
        }

        for (int i = n + 1; i <= n + a; i++) {
            int val = 1;
            while (has(seq, val, n - a + 1, i - 1)) val++;
            seq[i] = val;
            cur = val;
        }

        for (int i = n + a + 1; i <= n + n; i++) {
            seq[i] = cur;
        }

        for (int i = 2 * n + 1; i <= 3 * n; i++) {
            seq[i] = seq[i - n];
        }

        boolean[] used = new boolean[25];
        int start = l % n;
        if (start == 0) start += n;
        int end = r - l + start;
        if (end < start) end += n;

        for (int i = start; i <= end; i++) {
            if (i < seq.length) used[seq[i]] = true;
        }

        int count = 0;
        for (int i = 1; i <= 24; i++) {
            if (used[i]) count++;
        }
        return count;
    }

    private static boolean has(int[] arr, int val, int lo, int hi) {
        for (int i = lo; i <= hi; i++) {
            if (i < arr.length && arr[i] == val) return true;
        }
        return false;
    }
}

