        int startIdx = l % sum;
        if (startIdx == 0) startIdx += sum;
        int endIdx = r - l + startIdx;
        if (endIdx < startIdx) endIdx += sum;

        for (int i = startIdx; i <= endIdx; i++) {
            if (i < base.length) present[base[i]] = true;
        }

        int uniqueCount = 0;
        for (int i = 1; i <= 24; i++) {
            if (present[i]) uniqueCount++;
        }
        return uniqueCount;
    }

    private static boolean contains(int[] arr, int val, int from, int to) {
        for (int i = from; i <= to; i++) {
            if (i < arr.length && arr[i] == val) return true;
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);
        int a = fs.nextInt();
        int b = fs.nextInt();
        int l = fs.nextInt();
        int r = fs.nextInt();
        pw.println(compute(a, b, l, r));
        pw.close();
    }

    private static int compute(int a, int b, int l, int r) {
        int n = a + b;
        if (r - l + 1 > 2 * n) {
            return a <= b ? a + 1 : 2 * a - b;
        }

        int[] seq = new int[3 * n + 1];
        int lastVal = 0;

        for (int i = 1; i <= a; i++) {
            seq[i] = i;
            lastVal = i;
        }

        for (int i = a + 1; i <= n; i++) {
            seq[i] = lastVal;
        }

        for (int i = n + 1; i <= n + a; i++) {
            int val = 1;
            while (has(seq, val, n - a + 1, i - 1)) val++;
            seq[i] = val;
            lastVal = val;
        }

        for (int i = n + a + 1; i <= 2 * n; i++) {
            seq[i] = lastVal;
        }

        for (int i = 2 * n + 1; i <= 3 * n; i++) {
            seq[i] = seq[i - n];
        }

        boolean[] seen = new boolean[25];
        int start = l % n;
        if (start == 0) start += n;
        int end = r - l + start;
        if (end < start) end += n;

        for (int i = start; i <= end; i++) {
            if (i < seq.length) seen[seq[i]] = true;
        }

        int count = 0;
        for (int i = 1; i <= 24; i++) {
            if (seen[i]) count++;
        }
        return count;
    }

    private static boolean has(int[] arr, int val, int lo, int hi) {
        for (int i = lo; i <= hi; i++) {
            if (i < arr.length && arr[i] == val) return true;
        }
        return false;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] parts = br.readLine().trim().split("\\s+");
            int a = Integer.parseInt(parts[0]);
            int b = Integer.parseInt(parts[1]);
            int l = Integer.parseInt(parts[2]);
            int r = Integer.parseInt(parts[3]);
            System.out.println(process(a, b, l, r));
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    private static int process(int a, int b, int l, int r) {
        int total = a + b;
        if (r - l + 1 > 2 * total) {
            return a <= b ? a + 1 : 2 * a - b;
        }

        int[] arr = new int[3 * total + 1];
        int prev = 0;

        for (int i = 1; i <= a; i++) {
            arr[i] = i;
            prev = i;
        }

        for (int i = a + 1; i <= total; i++) {
            arr[i] = prev;
        }

        for (int i = total + 1; i <= total + a; i++) {
            int candidate = 1;
            while (check(arr, candidate, total - a + 1, i - 1)) {
                candidate++;
            }
            arr[i] = candidate;
            prev = candidate;
        }

        for (int i = total + a + 1; i <= 2 * total; i++) {
            arr[i] = prev;
        }

        for (int i = 2 * total + 1; i <= 3 * total; i++) {
            arr[i] = arr[i - total];
        }

        boolean[] found = new boolean[25];
        int start = l % total;
        if (start == 0) start += total;
        int finish = r - l + start;
        if (finish < start) finish += total;

        for (int idx = start; idx <= finish; idx++) {
            if (idx < arr.length) found[arr[idx]] = true;
        }

        int unique = 0;
        for (int i = 1; i <= 24; i++) {
            if (found[i]) unique++;
        }
        return unique;
    }

    private static boolean check(int[] data, int value, int left, int right) {
        for (int i = left; i <= right; i++) {
            if (i < data.length && data[i] == value) return true;
        }
        return false;
    }
}
